/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20221031-9","meetingId":"r04-cm10","date":"2022年10月31日","dateIso":"2022-10-31","committee":"文教委員会","time":"午前１０時００分～午後 ４時００分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を107件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"田中委員","kind":"確認","question":"高橋しんじ議員の一般質問の中の、教育・子ども施策のところで、区立幼稚園の閉園の問題について触れられました。そのときに、伊藤幼稚園の閉園を教育委員会としての意思決定がなく、保育課、区の主導で進んでいて、これは越権行為ではないかという質問に対して、区教委の明確な答弁が確認できなかったので、そこの部分を改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"}]},{"id":"topic-02","title":"審査順を入れ替えまして、初めに、(2)第８５号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"審査順を入れ替えまして、初めに、(2)第８５号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"この内容ですけれども、ちょっと確認なのですが、公務中に怪我などをして介護を受けることになった際に、その費用を補償するという理解でいいのでしょうかということが１つと、それと、学校医や歯科医および薬剤師に限らず、区内の小中学校で実際にこの介護補償を受けたケースは、近年どれぐらいあるのかという状況だけ分かれば教えてください。","respondent":"勝亦学務課長","answer":"２点いただきました。介護補償です。安藤委員おっしゃったように、公務中の事故により介護が必要な状況になったときに、その補償として支払われる月額について定めているものです。","id":"exchange-002"},{"speaker":"若林委員","kind":"確認","question":"確認です。遡って今年の４月１日からの適用というところで、これは先ほどの労災保険法、また国、都も同じ内容、保険法に基づいてというところで、遡って適用するという根拠がどこら辺にあるのか教えてください。","respondent":"勝亦学務課長","answer":"こちらにつきましては、適用が令和４年４月１日ということで、国の政令、都条例についても同じ適用日としておりますので、それに条件等を合わせる形で４月１日としております。","id":"exchange-003"},{"speaker":"田中委員","kind":"確認","question":"介護補償の限度額が上がるということなので、確認ができたので賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"説明資料の２番の改正内容のところですけれども、この表の８７番、９１番のところですが、「当分の間」という文言がありますけれども、これはいつまでなのでしょうか。それと、７割水準にするということなのですけれども、現在は何割になっているのでしょうか。それと３つ目が、(2)「役職定年調整額を加算」とありますけれども、具体的にどの程度の加算になるのでしょうか。伺います。","respondent":"中谷指導課長","answer":"ただ、考え方としましては、例えば、校長先生をなさっていた方が、６０歳を迎えまして、６１歳になる年度で主任教諭になられるといったところで、今までの制度でしたら、校長先生を継続されている中で、今までもらっていた校長先生の給料の７割。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"国の制度が大きく変わる中での改定だと思うのですけれども、労働条件や環境に関わってくることなので、こちらは労働者の皆さんですとか、労働組合とかというところの協議と合意については、現在どのようになっていらっしゃるのか伺います。","respondent":"中谷指導課長","answer":"組合とのやり取りということにつきましては、東京都教育委員会、そして特別区人事委員会ともに、これまでにこの議論をしていた中での今回の提案ということになっておりますので、そのように承知をしております。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"賛成なのですが、国が正式に定年自体を６５歳まで延長するということであれば、同じ仕事をやるわけですから、私は５９歳までの給料を補償すべきだというふうに思うのですけれども、今回の改定は、役職手当とかもそうですけれども、不利益を生じさせない内容でもあるし、労働者側の皆さんとの協議の結果ということですので、賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"}]},{"id":"topic-03","title":"令和４年請願第１３号 区立小中学校の給食費の無償化を求める請願","agenda":"令和４年請願第１３号 区立小中学校の給食費の無償化を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"答弁で、いろいろ総合的に勘案するようなことをおっしゃっていたのですけれども、何をどう総合的に検討するのか、そこの本会議答弁の中身をもう少し詳しく教えていただきたいということが１つと、もう１つは、現在、給食費の３人目以降の補助をやっていらっしゃるのですが、目的と、あと所得制限とか、全部無償化でしたか、そこら辺の制度のもう少し詳しい内容を教えてもらいたいと思います。","respondent":"勝亦学務課長","answer":"３人目以降の多子家庭給食費の補助です。若干説明が重複いたしますけれども、義務教育に当たるお子様が３人いる中で、３人目以降、区立学校にお通いいただいているお子様の分につきましては、給食費を区のほうで負担するという制度です。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどの冒頭の課長の請願に対する区の説明は、かなり矮小化と言うと言い過ぎですけれども、ちょっと読み違えているというか、こちらは、もちろん冒頭、年間５万円、６万円もの経済的負担が解消されるというのは本当に助かると思うし、それは就学援助を受けていないご家庭にあっても、かなり厳しいですから、すごくありがたいことでやるべきだと思うのですけれども、同時にこれ。","respondent":"勝亦学務課長","answer":"学校給食法を持ち出してということでしたのですけれども、こちらのほうは、ＮＨＫのほうから、「法律に書いてあることですね」という確認がありましたので、「そうです」というふうにお答えしたもので、もちろん記載のとおりなのですけれども。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問","question":"私は、学校給食法は、それをもって各自治体の無償化の実施を妨げるものではないと、文科省がそういう答弁をしていますので、その答弁も踏まえて、私は、品川区は義務教育を無償にすべきだと、これを完全実施すべきだという立場で学校給食を無償化すべきだと思うのですけれども、いかがでしょうか。","respondent":"勝亦学務課長","answer":"無償としている自治体等々あります。そういったものに関しましては、今後、給食の教育的な意義ですとか、教育費の無償化ですとか、そういったものに関しましては、給食費のみならず、総合的に政策として判断、検討していくべきものだと考えております。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"しかし、区は、今もご答弁があるように、総合的に判断すると、煮え切らないということなのです。こういう請願も出ています。ぜひ議会としても請願を採択して、区に促すべきだと私は思うのですけれども、本会議で無償化を求めた自民党、公明党はじめ、ネットは紹介議員になっておりますので明確だと思うのですが、皆さんの意見もぜひ聞かせていただきたいなというふうに思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問","question":"ですから、これから無償化云々というのは、はっきり申し上げて、今またちょうど区長選も始まっていて、そこの政争の具にもなっているところですから、それをたやすくどういうふうにするということを私たちが今言えるところでもないというふうにも残念ながら思っているのだけれども、まずは子どもが主役というところを考えた上で、どういうふうにしていくかという議論がなされない限り、多分これはもう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"この無償化がもし、もしというか、してほしいのですけれども、なので、前向きにそういう議論がされたらいいなということと、あと、自民党もそうですし、公明党も無償化のことを、この前の一般質問でもされていますし、やっぱりみんなで採択に向けて、ここを一緒にできたらいいかなということを私は思います。質問にならなかった、ごめんなさい。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"今の３人の委員の議論、理事者も含めて興味深く拝聴しました。要望もさせていただきました。もう１つが、就学援助の中で実施されている。これが計、約２億円ということで、ここから、その他諸経費も含めてかかるのが約１１億円ということで、本会議の答弁の確認のようになりますけれども、まず、ここの土台のところを確認をさせていただきたいと思います。","respondent":"勝亦学務課長","answer":"各ご家庭にご負担いただいています給食費につきましては、今、ご説明いただきましたけれども、まず、総額で、小学校低学年で２４０円、中学年で２６０円、高学年で２８０円、それから中学生につきましては３２０円の給食費をご負担いただいております。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"今の検討状況と、それから、区で１１億円を投入して無償化にするといった場合、私会計と公会計、どちらか一方の会計しかないわけですけれども、これとの関係、手続の問題になりますけれども、私はステップを上がっていきたいと思うので、今できることは何かというところで、もしかしたらこの私会計と公会計の問題もちょっと横たわっているのかなというふうにも、国会議論なども聞きながら思ったので。","respondent":"勝亦学務課長","answer":"そういった意味で、給食費の徴収には、現場の教員、学校職員の負担は大きくないものでございまして、公会計化を行いますと、システム開発等の経費がかかるので、負担がさほどかかっていないという状況での、公会計化については、現在検討していないところです。","id":"exchange-015"},{"speaker":"若林委員","kind":"提案","question":"今の食材費の徴収の仕組みの中で、無償化に踏み切るということには何もハードルはないということを１つ確認させていただきました。いずれにしても、この１１億円という新たな予算、どうしても区長選挙の話になります。この１１億円、ほかの、給食費の品川区政の課題というのは、本当にそれはもう端から端までたくさんある中での、それでも１１億円の大切な学校給食費の公費負担というご提案です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"くにば委員","kind":"質問・要望","question":"何点か確認をさせていただきたいのですけれども、この請願文書に書いてありますとおり、都内では４自治体が既に実施されているということです。こちらが全国規模で考えたときに、どの程度の自治体が実施をしているかどうか、把握している範囲でお答えください。","respondent":"勝亦学務課長","answer":"少しデータは古いのですけれども、たしか記憶している範囲では、令和２年度の文部科学省の発表では、７０団体余りというふうに公表されてあります。現在、報道等で、様々な自治体の動きがありますが、ちょっと正確な情報は把握していないところです。","id":"exchange-017"},{"speaker":"くにば委員","kind":"質問","question":"先ほど、若林委員が、総予算、区が負担する予算が１１億円、こちらは本会議でもご答弁があった部分なのですけれども、まず、区として、この１１億円の、区の予算全体からの公平性というか、様々な課であるとか部局との調整の中で、この１１億円が、かなりの金額ではあると思うのですけれども、この財源の捻出が、例えば厳しいというような観点、庁内各部局との公平性の観点から。","respondent":"勝亦学務課長","answer":"品川区の予算の配分ですとか財源につきましては、給食単体ではなく、予算全体の中で検討するものかと考えています。","id":"exchange-018"},{"speaker":"くにば委員","kind":"意見","question":"葛飾区に関して、今回、給食費の無償化を実施されるということなのですけれども、こちらは、あくまで葛飾区に関しては、理由という部分で限定的に回答をしておりまして、今後、今回の憲法第２６条等々の理由等ではなく、あくまで物価高騰であるとか、材料費高騰の部分を、区民の方の負担を軽減するために無償化に今回踏み切ったという形で記載をされております。","respondent":"勝亦学務課長","answer":"給食費の補助、支援等についてのお問合せです。多子家庭給食費補助につきましては、やはり第三子以降の３人のお子様の給食費の負担が経済的に厳しいご家庭に関しては支援をしていこうということでの支給になってあります。","id":"exchange-019"},{"speaker":"田中委員","kind":"確認","question":"１つ確認を忘れてしまったのですけれども、臨時交付金を利用しての給食費の一部補助について、今年度までということは確認できていたと思うのですけれども、来年度はどうなるのかというところを伺いたいのと、あともう１点が、私が給食について何年か前に調べたときに、学校規模、生徒数によって、質というか、例えば、フルーツのバナナの大きさが違うとか、ミカンの大きさが違うとか。","respondent":"勝亦学務課長","answer":"臨時交付金を活用した補助です。臨時交付金については、今年度に充てる予算ということでいただいているもので、今年度中に適用するものです。来年度以降のお話ですけれども、物価等々の状況を見ながら、今後検討していくことかなと考えています。","id":"exchange-020"},{"speaker":"田中委員","kind":"意見","question":"この無償化をすることによって、どこの学校も公平に子どもたちがきちんと栄養をとれるといったところからも、私はこの無償化については、皆さん、目指す方向性は、多分どこの会派も同じだったということを、この議論の中で思ったので、ぜひ皆さんと一緒に全会一致で賛同ができたらと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"渡部委員","kind":"質問","question":"先ほど理由を述べたとおりなのですけれども、ともかく今、区長選の真っ最中で、いろいろな方々がいろいろな公約を出してきてやっている中で、そこで新たな議論がこれから発生すればしたで、そこでまた私達も文教委員会として話していけばいいと思うのですけれども、そもそも先ほどからご説明をいただいているように、福祉の観点での助成ですとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"安藤委員","kind":"提案","question":"区長に対して議会は、もう既に、主要会派も含めて無償化すべきだという提案もしているわけですから、どなたが新しい区長になったとしても、議会としてしっかりと無償化をすべきでしょうという意思表示を今からしていく。そうすると、新しい区長の方も、それを踏まえて、最終的には区長の判断になりますけれども、議論されるわけですから、私はここで絶対採択すべきかなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"くにば委員","kind":"質問・要望","question":"本日結論を出すで、不採択で考えております。もう１点、３点目に関してが、「義務教育は無償と憲法２６条でうたっている中」というこの一文に関して、当会派の中で議論を重ねた中では、最終的な教育の無償化を求める方向性に関しては同じではあるのですけれども、今回、この請願の内容に関しては、不採択という立場で考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"田中委員","kind":"質問・要望","question":"子どもを主体にといったお話がさっきあって、本当にそのとおりだなということを思っていたのですけれども、今、不採択の意見を聞いたところ、区長選があるからといったような話で、子ども主体といった、子どものためのというのはどこへいってしまったのだと私は思ったのですけれども、子どものためにも無償化を実施してくださいと求めている請願に対して。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-04","title":"令和４年陳情第５１号 品川区立学校図書館をもっと充実させるための陳情","agenda":"令和４年陳情第５１号 品川区立学校図書館をもっと充実させるための陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"ここでも書かれております国や都の動きについて伺いたいのですが、東京都が直接雇用を始めておりまして、その理由が陳情にも書いています。直接雇用に切り替える必要があるということを指摘していたりとか、実際にそういうふうに切り替えているわけです。そういう動きを区はどのように評価しているのでしょうか。このガイドライン等々をどのように受け止めているのでしょうか。伺いたいと思います。","respondent":"吉田品川図書館長","answer":"偽装請負につきましては、作業計画会議を毎月１回設けておりまして、こちらのほうで、校長、副校長、司書教諭と相手側の事業者の責任者およびスタッフで、これは毎月、次の月の事業における図書館の活用方法だとか、取りそろえてもらいたい資料などの選定だとか。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"国の図書館ガイドラインについても伺ったので、あとでお答えください。してしまうと偽装請負になってしまうわけです。これだけで今言ったような、では、図書館を活用してどういう授業をしようかとか、あるいは、綿密にふだんからこういう授業をやりたいのだけれども、何かいい資料ありますかとかということも含めて、連携が不十分になるのが明らかだと思うのですけれども、そこについてはどうなのでしょうか。","respondent":"吉田品川図書館長","answer":"図書館ガイドラインにつきましては、学校図書館の利活用だとか、学校図書館の運営等についてうたっているものですので、こちらには、そういった形で動いていくことを予定しています。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"そのガイドラインのところは、学校教職員の一員として参加することが重要なのですよというふうに書いているのですけれども、そこについてどう考えるかということを伺いたいのと、それと、私が先ほど伺ったのは、直接雇用でないと、委託ですと、仕様書に書いていることはできるかもしれないですけれども、それはあくまで個々の具体的な業務をやるということなのですけれども。","respondent":"吉田品川図書館長","answer":"学校の一員であるということにつきましては、当然、学校の一員として受託業者のほうでも動いていただく形になります。その中での必要なところは、まずは作業計画会議のほうで打合せをいただいて、その月の計画等を進めていくということになります。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"これはもう明らかですよね。そういったところで、週２日で十分だと思っているのでしょうか。それを伺いたいのと、併せて３番目のところ、学校図書館支援のためのサポートができる体制ということですが、ご説明の中では、学校図書館サポートという部署が陳情の中にもありますけれども、品川区は設けているとありますが、この学校図書館サポートの部署というのは、どういうことを実際にやっているのか。","respondent":"吉田品川図書館長","answer":"その辺もございまして、現在は２.５日という形でやっているところです。十分かどうかというところにつきましては、今後の予算の編成の過程を含めまして回答を出せればというふうには考えているところです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういう意味でも、週２.５日というのは、開いていたほうが珍しいという感じになってしまうので、ここを抜本的にぜひ増やしていただきたいですし、あと、雇用形態も、そういう学校図書館の連携、学校現場との連携を気兼ねなくフルに行うためには、直接雇用に踏み出していただきたいということで、委託ではなく直接雇用をしている区もたくさんあります。荒川、杉並、葛飾等々あります。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"田中委員","kind":"確認","question":"区教委の方向性を伺いたいのですけれども、週５、専任の学校司書を配置していく、２０１９年のお願いのときに、５年、１０年のスパンで５日間を目指していくということもあったので、区教委としての方向性として増やしていくという考えがあるのかというところをまず確認させてください。","respondent":"吉田品川図書館長","answer":"図書館としては、国の第６次「学校図書館図書整備等５か年計画」、こちらもあるので、そのように考えているところではあります。契約については、５年に一度、総合評価等で、今回、第３期目、来年の４月で３期目に入るのですけれども、その中で進めるところです。","id":"exchange-031"},{"speaker":"田中委員","kind":"質問・要望","question":"今のご答弁でも方向性が分からないのです。増やしていきたいのかどうなのかというところが明確ではないので、私は、ぜひ子どもたちのためにも学校図書館司書が配置される日数を増やしていただきたいと思います。そこのところを明確にお答えいただければと思います。この文科省からの通知に対して、品川区の姿勢を伺いたいのですけれども、いかがでしょうか。","respondent":"吉田品川図書館長","answer":"１人１台端末および公立図書館の積極的な活用というところにつきましては、電子図書館を含め、学校図書館を積極的に活用していくというのは、これまでも区で対応してきたところですし、この間も、学校図書館、令和元年からは急に学校図書館の年の貸出冊数が増えてまいりまして。","id":"exchange-032"},{"speaker":"田中委員","kind":"確認","question":"学校司書の配置の日数については、区教委としては拡大を希望しているということで確認がとれました。やはり学校司書の役割というのをとても重要視しているということで間違いないですか。そういった学校司書の役割というのが、なかなか知られていない状況がある中で、区教委として、学校司書に対する役割の重要性というところをどう認識しているのかというところを伺いたいと思います。","respondent":"吉田品川図書館長","answer":"これまでも品川区は、司書のほかにも、学校図書館を運営するに当たりまして、ボランティアであったりだとかで、学校図書館を一緒にやっていくなどして進めてきたところでもあります。地域を含めて充実していく方向でもできればというふうに考えているところです。","id":"exchange-033"},{"speaker":"田中委員","kind":"確認","question":"確認をしたいのですけれども、先ほど、月１回の作業計画会議のところで、偽装請負にはならないように議論がきちんとされているということがあったのですけれども、この陳情の中では、偽装請負状態になってしまうために授業への関わり方をセーブしているということと、授業計画から教員と司書が共同して授業案を練ることができないといった今の学校司書の状況が訴えられているのですけれども。","respondent":"吉田品川図書館長","answer":"偽装請負の考え方ですけれども、実際は学校において、これも学校のほうにも校長を経由してアンケートをとっているところですが、その中において、現状に対して著しい課題があるかという質問に対しては、特に問題がないと、ほとんどの回答はそういう形で戻っているところですので。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"１００％のサポートだったりとか、そういうものが発揮できていないという司書たちからの訴えだと思うのです。なので、そういった司書を育てるための、最終的には子どもたちの学びの場を高めるための研修といったところが、これから設置されていくのかというところを確認したいのですけれども、いかがでしょうか。","respondent":"吉田品川図書館長","answer":"学校司書向けの研修ということでありますと、学校司書は、現在、業務委託をしております。なので、例えば、受託業者からの去年の報告書を読みましても、月一回の研修が行われていたりだとか、受託業者において、一定程度、研修をやるものというふうに認識しています。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"今のご説明であったとおり、事業者内での研修は行われているのです。それをなくすため、品川区の教育をするための研修サポートセンターを設置してほしいということなのです。そこについて、品川区の教育を向上させるためにも、今どのようなお考えがあるかということを伺いたいのですけれども、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"今お話しになっています業務委託への理解、どういうふうにスタッフとお仕事を進めるかということの共有もしていますので、全体の学校の読書計画、指導については、図書館長という意味では学校長、そして、その下の教員も、今のような研修で、スタッフとのお付き合い。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっと私が質問していた趣旨とはずれてしまったかなということで、私が求めているのは、子どもたちの学びの場、学校図書館というのは、本当に子どもたちが学ぶ、読書する、そして情報のセンターでもありますし、子どもたちが本に接する機会が、きちんと公平になる、事業者によって研修内容が違って、学校によって子どもたちも、その事業者の影響を受けてしまう、学び方、本の選書や。","respondent":"吉田品川図書館長","answer":"事業者においてばらつきがあるというお話を伺いましたので、これについては確認したいと思います。週２で最低だというお話もありますけれども、実は自治体の中には週１ということも数々あります。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"２.５日からぜひ増やしていただきたいということを強く求めたいと思います。前の２０１９年のときにも、５年、１０年のスパンで５日間を目指しているという前向きなご答弁をいただいているので、どうぞ後退しないようにというのは強調したいと思います。なので、きちんとした研修が行われるように、ぜひ強く求めたいと思います。一旦やめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"まして、実は、私も友達に司書がいますから、品川区ではないですけれども、大体どういう仕事をやっているか、大学でもそういうセクションがあったので分かりはするのだけれども、でも、品川区の場合は、もううちの子どももでかいですけれども、そういう図書館の支援をしてくれるボランティアの方とか、地域の方とかがいて、しっかり授業で読み聞かせをやってというような中で。","respondent":"矢部教育総合支援センター長","answer":"私が所管しているところには相談室もあるのですけれども、話がちょっと似ているのでお伝えしますが、やっぱり先ほど委員がおっしゃっていましたけれど、この子にはこの本をというふうに、誰でも支援員の方は思っていらっしゃるけれども、子どもの心の中や。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、そこまで求めるのは、物理的にも無理に近いわけだから、その中でしっかり品川の教育が遂行できるよりよい方法を、その中の１つとして、先ほどから図書館長がお話をされているようなことがいいのであれば、それは次年度に向けて進めていっていただきたいでしょうし、また、いいことであれば進めていただきたいなというところ、ちょっと感想じみたことになってしまうのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"これは事実として、今、こういう授業計画は教員と司書が協働して授業案を練るということはできているのでしょうか。これは実際、できないと思うのです。そこら辺についてはどうなのでしょうか。","respondent":"吉田品川図書館長、矢部教育総合支援センター長","answer":"先ほどから申し上げているとおり、作業計画会議という中において、区側の責任者および受託業者の責任者とお互いのスタッフ等を交えた中で話合いを進めていまして、その中で一定程度の結論を出すことは可能かというふうに考えております。例えば、国語の授業であっても、この図書館部の事業であっても、図書館の方のご意見をいただきながら進めるということはあると思うのですけれども、実際に指導案という計画書を学校はつくるのですけれども。","id":"exchange-041"},{"speaker":"安藤委員","kind":"質問","question":"ですから、私は、だからこそ東京都は契約の、偽装請負の指摘とか、この前もあったと思いますけれども、この裏に書いていますけれども、生徒の主体的・対話的な深い学びの実現に向けた授業改善に生かすためには、やっぱり直接雇用に切り替えなくてはいけないということで始めたというこの事実は、しっかり受け止めて改善する必要があると思うのですけれども、最後にもう一度お願いします。いかがでしょうか。","respondent":"吉田品川図書館長","answer":"ご指摘の部分もあるとは思いますけれども、直接雇用のメリット・デメリットもあります。その中で、一定程度、直接雇用のデメリットも大きい部分がありますので、次回につきましては、委託で進める予定で今のところ進めているところです。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"ぜひ直接雇用にしてほしいのですが、直接雇用のデメリットというのは具体的に何なのか、メリットのほうを重要視して東京都は変えたと思うのですけれども、デメリットとは何でしょうか。","respondent":"吉田品川図書館長","answer":"その間は図書館において学校司書がいないような形になってしまう。このようなところは避けたいという思いがありますので、まず一番のデメリットとしては、そのようなところを考えております。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"大分議論も深まったと思うのです。やっぱり私は今の説明を聞いても納得できませんし、そのデメリット以上にメリットを放棄しているというところですよね。だから、子どもたちにとって、よりよい図書館、充実した図書館をつくるために、日にちのほうは、先ほど前向きな答弁もありましたので、ぜひ進めていただきたいのですけれども、雇用形態についても、ぜひ再検討をお願いしたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問・要望","question":"やっぱり文科省もこういって訴えていることですから、今、品川区の教育がそのようなのかということではなくて、もっとよりよい教育になるように、国も動いているので、ぜひこの陳情については、皆さん一緒に品川区の子どもたちの学びの機会とか、落ち着ける居場所の拡充というところも含めて、前向きに採択に向けていただければなということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"若林委員","kind":"質問・要望","question":"何点か確認です。今の小中学校司書は業務委託なのですが、何人いらっしゃるのか、意外と話が出ていなかったと思うので、そこの確認が１つと、これまでさんざんメリット・デメリットも含めて検討はされているということなのですが、業務委託については５年に１回の見直しをするということなのでしょうか。","respondent":"吉田品川図書館長","answer":"現在の令和４年度のスタッフ数ですけれども、５８名です。５年で見直しというところは、今までもそうなのですけれども、総合評価という制度を使って随意契約をやっているところです。","id":"exchange-046"},{"speaker":"若林委員","kind":"意見","question":"金額のことは、そういうことなのですね。いわゆるプロポーザルで。そういう質をしっかりと、特に来年度、次の一応５年という縛りがかかる中で、学校司書の要件をしっかり明記をして、日数も時間もそうですけれども、司書の資格の要件をしっかりと担保していくという姿勢は、しっかりと感じられたのが１つ。ただ、契約のことについては、５年間仕様が同じということですよね。そこは指摘だけします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"くにば委員","kind":"質問","question":"この東京都の方針、業務委託から直接雇用へどんどん切り替えていくという中で、品川区も直接雇用に切り替えるというふうな判断をされたら、それは年単位で区切って、速やかにではないですけれども、年度年度で切り替えていくことが可能なのかどうか教えてください。","respondent":"吉田品川図書館長","answer":"仮の話になりますけれども、もし区が方針を変えるということであれば、一定程度の期間からは可能なものと考えますけれども、今、５年という縛りは、委託業者で人を確保するに当たって、５年確保することを前提などにして人の確保をされている場合もあります。","id":"exchange-048"},{"speaker":"くにば委員","kind":"意見","question":"それがまず大前提かなと思うのですけれども、それでは、この東京都が、実際に１８７校中１２８校が業務委託の部分を正規の職員に切り替えていくということができるのは、これはまた契約の制度が違うから、これは各自治体、団体によって、例えば３年間であったりとか、本当に単年、単年でやっているところもあったり、品川区のように５年というところもあるからなのか、そこの違いをお聞かせください。","respondent":"吉田品川図書館長","answer":"それなので、幾つか契約がある中で、終わったものから必要に応じてという形であったというふうに伺っているところです。","id":"exchange-049"},{"speaker":"くにば委員","kind":"質問","question":"今現在、品川区のたしかホームページ上か何かで掲載されているか、事務局か何かで拝見したのですけれども、次の５年間に向けて、今、既にプロポーザルの業者の選定の部分まで入っているのか、どこまで今度の５年間について進んでいるのか、スケジュールの現状を教えてください。","respondent":"吉田品川図書館長","answer":"そのため、最初のところで申し上げた司書資格だとかということについては、仕様に盛り込んでいくという言い方はできるのですけれども、人数については、ダイナミックにお金が変化するような部分もありますので。","id":"exchange-050"},{"speaker":"くにば委員","kind":"確認","question":"もう１点確認したいのですけれども、本年の３月１４日、令和４年度予算特別委員会での質疑の中で、これまでの品川区には、ボランティア等を含めて学校図書館の充実を図ってきた歴史がある、そういった歴史の中で今現在の形態になっているという、ここに関して、これがいい意味での区民の方との協働、地域の方との協働で、この歴史があるという意味合いなのか、それとも。","respondent":"吉田品川図書館長","answer":"その関係もございまして、各学校でも、ボランティアを積極的に使いながら、学校図書館の運営をこれまでもしてきたというふうに考えているところです。","id":"exchange-051"},{"speaker":"くにば委員","kind":"質問・要望","question":"その品川区の方針、いろいろな方々とお子さんが触れ合っていただきたい、関わっていただきたいということと、あとは、今回の陳情の趣旨等にある専任の学校司書を置いて、その方が深くそれぞれの生徒について知っていただきたいという、ここに関しては、ある意味、相反しているように感じてしまうのですけれども、ここに関して、どうお考えでしょうか。","respondent":"吉田品川図書館長","answer":"それはボランティアの部分というところと、また、司書のところにおきましては、専任、今も必ず１人でやっているところではないところもあります。その辺は、各学校の事情等を踏まえまして、また検討していければです。","id":"exchange-052"},{"speaker":"くにば委員","kind":"質問","question":"もう１点なのですけれども、様々な分野で、民間の力、民間の活用という部分、私は、そういった切り替えであるとか、半々だとは思っているのですけれども、現状、司書においては、民間の業者と直接雇用の方で、司書に能力の差があるかないか、どちらのほうがバランスがとれているか、そちらについてお考えがあれば教えてください。","respondent":"吉田品川図書館長","answer":"人ですので、必ずある程度これは差はあるとは思いますけれども、会社における研修を継続して受けるなりしながら従事しているところを踏まえますと、一定程度の質は確保できているものというふうに認識しております。","id":"exchange-053"},{"speaker":"くにば委員","kind":"質問","question":"先ほども、直接雇用だと、欠員が出たときにすぐに補充が難しいという、そういった、ある意味、フレキシブルではない部分を、これは業務委託の場合ですと、人材派遣会社ではないですけれども、様々な委託をするスタッフを抱えているので速やかに補充できるというメリット、やっぱりメリット・デメリットのほうで、後者のメリットを強く感じているのかどうか。そこに関してもう一度お伺いしたいです。","respondent":"吉田品川図書館長","answer":"今までもその強みをいかした部分もありまして、委託業務で進めてきたところでもあります。","id":"exchange-054"},{"speaker":"くにば委員","kind":"質問","question":"もう１点伺いたいのですけれども、今現在、作業計画会議が月１回という部分なのですけれども、これは先ほどの質疑の中では、これを月１回より、さらにそのペースを増やすということが、契約等なのか、現状難しいということだったように聞こえたのですけれども、例えばこれを週１回なり、もっと緊密に連携をとるということは難しいのでしょうか。","respondent":"吉田品川図書館長","answer":"そうなりますと、まだ予算的なところが決まっていないところですので、できるかできないかということであれば、仕様書を変えればできるということになりますけれども、現実的に来年度からできるかどうかというのは、予算の編成の結果次第というところで考えているところです。","id":"exchange-055"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"簡潔に言います。それを踏まえて、今後、子どもにとって学校図書館はどういう位置づけなのか、どういうものになってほしいのか、これをやはり聞いていただきたいなということが私の本音なので、そういったアンケートをとっていただきたい、子どもの声を聞いていただきたいということが１点と、あと、スタッフとか学校司書の方、先生方には、アンケートをとっているという答弁があったのです。","respondent":"吉田品川図書館長","answer":"その中においては、９割をかなり超えた段階での高評価が学校からは戻っているところです。もう１つ質問が…。","id":"exchange-056"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"ぜひよろしくお願いします。図書館長の発言の中で、今、これからの予算調整の中で、これから先の図書館の予算なども調整しているというお話があったのですけれども、それは前向きな検討として捉えていいのか、そこだけ教えてください。","respondent":"吉田品川図書館長","answer":"予算について触れることはなかなか難しいところですので、図書館としては前向きに考えておりますけれども、予算としての結論は、私どもだけではなくて、いろいろなところの調整を図った上でという形になりますので、そこのところはご理解いただきたいと思います。","id":"exchange-057"},{"speaker":"渡部委員","kind":"質問・要望","question":"本日結論を出す、この陳情に関しては、不採択でお願いいたします。先ほど来、お話もさせていただきましたし、いろいろな手法を用いて、子どもたちの学校図書館の環境ですとかというより、本を読む習慣ですとか、向上していただきたい反面、また今、副委員長からもありましたとおり、子どもたちのニーズ調査等もどこかでまたしっかりやっていただいていかしていただきたいなと思います。お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"若林委員","kind":"確認","question":"本日結論を出すで、不採択です。例えば業務委託にしても、区の直接雇用にしても、いずれにしても、現場の良好なお声ということもあり、また次年度に向けての前向きな区の、最終的にどうなるかということも再三言われていましたけれども、教育委員会としては、前向きに上乗せしていくという姿勢も十分にそれは答弁の中で確認ができましたので、今日の時点では、不採択という結論で出します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"安藤委員","kind":"意見","question":"やっぱり学校図書館、ここにも書いていますけれども、読書センター、学習センター、情報センターという機能をやはり遺憾なく発揮していく品川の学校図書館をつくっていくためにも、こういった陳情項目は採択して進めていくべき内容だと思いますので、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"くにば委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。これを先ほど、月１回の作業計画会議ではなく、週１回にもっと緊密にするという部分に関しても、これも今後の予算等の中で、もっと緊密に連携をとることが可能だということをお伺いしましたので、その部分も、民間業者であるというデメリットが補完されていくのかなという形で思いました。等々の理由も含めまして、今回に関しては不採択という形で考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論出すで、採択を主張します。そういった中でも、これを改善していくためにも、そしてまた、先ほど学校司書の配置については、区教委としても予算の中で拡大を希望していきたいという話があって、予算の話もあった中で、その区教委の姿勢を後押しするためにも、ぜひ皆様には採択を主張していただきたいということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-05","title":"第８２号議案 品川区子どもの医療費の助成に関する条例の一部を改正する条例","agenda":"第８２号議案 品川区子どもの医療費の助成に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"質問ですが、区は所得制限をつけないという考えなのですが、いいと思います。子育てというのは社会全体で応援すべきで、そうすべきだと思うのですけれども、区としては、なぜそうした判断にしたのか、区自身の考えを伺いたいということと、無償化の財源について伺いたいのですが、東京都は、今、無償化の財源について、具体的に何年間、どこまでを対象にして出すというお考えなのか伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"財源について都はどのように考えているかということですが、今のところ、都の発表ですと、令和７年度まで、所得制限内のみの方に対しては１０分の１０の補助というふうに伺っております。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"所得制限をつけるというところを東京都が考えているということ自体もおかしいなと思うのですけれども、さらに令和８年度以降は２分の１にするという、どうしてでしょうという感じなのですが、３年たった後も当然やるべき施策だし、それが都内の自治体の財政状況によって、できる、できないということになってはいけないと思うので、おかしいなと思うのですが、３年たった令和８年度からについても。","respondent":"飛田子育て応援課長","answer":"令和８年度以降、２分の１というところでなくなることは心苦しいことなのですが、これについては品川区だけではなく２３区で、特別区の区長会のほうでも、今後継続して国のほうにも訴えていくということなので、そちらのほうでまた都のほう、国のほう。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほど聞くのを忘れました。区の負担といいますか、１８歳までの今回新たにかかる医療費の見込み、それをどれぐらいだと考えているのかお伺いするのと、仮に２３区連帯して働きかけていくにしても、それ以降東京都が２分の１だよということであっても、ぜひ区としても財政措置をして継続していっていただきたいというふうに、これは要望したいと思います。先ほどの質問だけお願いします。","respondent":"飛田子育て応援課長","answer":"今までの１人当たりの医療費等をざっと計算しますと、約３万２,０００円ぐらいになるだろうと。そういうところで所得制限内の方とか、区の負担分を考えますと、約１億１,０００万円弱ぐらいが区の負担というふうに想定しております。","id":"exchange-065"},{"speaker":"田中委員","kind":"質問・要望","question":"条例改正は歓迎したいと思うのですけれども、高校生等の医療費助成制度という名前から、ここにも注意書きとして書いてあるのですけれども、「年齢を要件とするため、在学しているかどうかは要件ではない」とあるのですけれども、やっぱりこの制度の名前を見たときに、高校生の年齢の高校生ではない子を持つ保護者から、対象になるのかという不安の声が結構聞かれたりするので。","respondent":"飛田子育て応援課長","answer":"こちらの周知の方法ですが、この後、決定が下りましたら、その対象になる方に、住民基本台帳にのっとり一斉に周知、また、ホームページ等でも周知していきたいと考えております。児童福祉法の要件のところです。","id":"exchange-066"},{"speaker":"田中委員","kind":"質問","question":"なので、そういった分かりやすい表記と、また、この助成要件の中でも、こういった方が対象になりますよといった行政用語と言ったらあれなのですけれども、そういう表現ではなく、誰にでも伝わるような表記での周知をぜひお願いしたいと思うのですが、いかがでしょうか。","respondent":"飛田子育て応援課長","answer":"そうですね、おっしゃるとおり、こちらは誤解が生まないように、「高校生等」というのは一般的な分かりやすい表記にしていますけれども、生まれた年というところで、年齢の要件が一番大事になりますので、そこはまた注意しながら周知をしていきたいと思います。","id":"exchange-067"},{"speaker":"若林委員","kind":"質問・要望","question":"一遍に何点か。２ページ目の裏面、所得制限のところで、今回、東京都の所得制限というところなのですが、当然、東京都の補助金の関係で所得を把握する必要があるわけですけれども、これはどのようにして把握するのですかということを確認をするのが１つ。何かまた変に、本当にいわゆるご丁寧な説明になると、今の質疑でも、「うん？以上、３点。","respondent":"飛田子育て応援課長","answer":"新旧対照表のほうになります。ここの(2)のところに挙げている要件は、高校には入学していませんけれども、場合によっては、高校に行かず自立している方もいるということで、ここに挙げていますが、人数はまだ実際に把握はできていない状況です。","id":"exchange-068"},{"speaker":"若林委員","kind":"質問・要望","question":"今回、第２回定例会の一般質問、それから、濱野元区長への要望を会派としても重ねさせていただいて、当然その前段として、都議会公明党で小池都知事に、高校生等までの医療費の無償化ということで、東京都の補助金を活用しながら、品川区においても、これまでどおり所得制限を設けないでやってくださいというふうにしたことがこういう形になったということで、あとは分かりやすい説明、また。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"渡部委員","kind":"質問","question":"１点だけ教えてください。もう本当に初歩的な質問かもしれないですけれども、今までの子どもすこやか医療費助成というのが、そのままずっと生き続ける、将来的にはというか、１つの事業としていくわけですよね。これ、申込みに漏れる人などが仮に出てくるではないですか。医療証がないから受けられなくなってしまうのか。その辺のところだけ教えてもらっていいですか。","respondent":"飛田子育て応援課長","answer":"今後また引っ越し等があって、新たに東京都外から来た方については、今までどおり、子どもすこやか医療証と同じようにご案内を差し上げて、１人でも漏れがないように周知は今後も続けていく予定です。","id":"exchange-070"},{"speaker":"渡部委員","kind":"質問","question":"分かりました。それはもう本人の責任ではあるのだけれども、現実そういう人たちは出てくるでしょうから、それに関しては、その辺もしっかりやりますよということだと思うので、そういうケースでもちゃんと対応してあげてくださいというところだけ、すみません、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"くにば委員","kind":"質問","question":"もう１点が、「事実上婚姻関係と同様の事情にある場合を含む」というのも削除されている理由、これを教えてください。","respondent":"飛田子育て応援課長","answer":"こちらに対しては、今までここで書いてあるところが、今度は新しい改正後のところの２／８の第３条(2)において、全て網羅するということで、こちらのほうから削除させていただいているということになります。","id":"exchange-072"},{"speaker":"安藤委員","kind":"意見","question":"一方、１０月から後期高齢者の方々が、７５歳以上の方々は、医療費の窓口負担が２倍になったりとか、かなり厳しい状況がありますので、ぜひこういった区独自の高齢者に向けての医療費の無料化ですとか、軽減策についても、私は検討すべきだと思っています。そのことを申し上げさせていただきまして、賛成します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"}]},{"id":"topic-06","title":"第６９号議案 令和４年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第６９号議案 令和４年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"恐れ入ります。こちらに関しては、基本的には高校生等までの医療費に関して補助しようという大変すばらしい目的だと思うのですが、この入院費、通院費の部分を伺いたいのですが、ある意味、高校生までの医療費に関して全般の助成制度であるならば、もちろんこれ、東京都が決めた部分なのですが、投薬治療だけする方、パターンがありますね。","respondent":"飛田子育て応援課長","answer":"この医療費なのですけれども、保険適用に関われば医療費の対象になるというふうにご理解していただければと思います。","id":"exchange-074"},{"speaker":"くにば委員","kind":"質問","question":"そうですか。はい、分かりました。では、この入院費、通院費、ほかという形の認識、はい、分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問","question":"申請受付開始が１月からとなっておりますが、これまで中学生までの子どもすこやか医療費助成を受けていた子どもや家庭も申請が必要だということなのでしょうか。そこら辺をお伺いします。","respondent":"飛田子育て応援課長","answer":"例えば、今現在、中学３年生が正に対象になるかと思いますけれども、中学３年生のところでは、今までの対象年齢ということで、こちらで住民情報が分かっていますので、そこのところは継続的に。","id":"exchange-076"},{"speaker":"田中委員","kind":"質問","question":"今の部分なのですけれども、では、今の高校２年生、高校生の家庭への周知がどういう工夫をされるのか、申請をしなければいけないとなると、やはりより周知が必要かなと思うのですけれども、その部分だけ教えていただけますか。","respondent":"飛田子育て応援課長","answer":"取りあえず、住居が今、品川区内にある方で、対象の、今、中３、高１、高２の方に対しては、全員にお知らせを配布、各家庭に配布する予定です。","id":"exchange-077"},{"speaker":"若林委員","kind":"質問","question":"準備経費の補正予算ということで、課長の力の入れ具合が、意気込みがよく伝わる資料だなというところで、準備経費としては、このスケジュールの事業周知が１つ、それから、システム改修が１つ、具体的にこの２つですか。準備経費の２,８２０万円、これの内訳を聞いておきます。","respondent":"飛田子育て応援課長","answer":"今回この周知等を図りますので、そちらは３６７万９,０００円ほどで、あと、新たに医療証を作ったりとか、また、封筒とか用紙代、そういうところでは２１９万１,０００円ほどを想定しています。","id":"exchange-078"},{"speaker":"若林委員","kind":"質問","question":"ここが今回の補正予算のところだということで承知いたしました。そうすると、一番大きいのは、当然、２,２００万円のシステム改修ということで、今回、契約も含めて、今までこういうシステムだったので、こういうふうに改修しなければいけないという、そこら辺も分かりやすく教えてください。","respondent":"飛田子育て応援課長","answer":"今回は、それを高校生まで拡大するというところで１つと、あと、東京都が所得制限があるかないかというところ、そこのところで、また補助を持ってこないといけないということなので、システムの変更が必要になってきたという、大きなところではその２つになります。","id":"exchange-079"}]},{"id":"topic-07","title":"令和４年請願第１１号 品川区私立幼稚園保護者負担教育費の軽減に関する請願","agenda":"令和４年請願第１１号 品川区私立幼稚園保護者負担教育費の軽減に関する請願","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"それ以前までは、各園いくらだったというところを伺いたいのと、あとまた、平成２７年度から心身障害児教育事業費補助金の増額をしていただきましたとあるのですが、この補助金の使われ方というところでの活用状況の確認がどうやってできるのかというところを伺いたいということと、あとまた、この裏面のところに、昨今の痛ましい事故とかがありまして。","respondent":"中元保育支援課長","answer":"重大事故については報告を都や国に上げていきます。軽微なちょっとした転んだ傷とか、そういうものは特にこちらには実際には報告は来ておりません。やはり私立幼稚園独自で独立した事業者ですので、東京都に届けていると考えているところです。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"それと、３点目は、公私の教育格差という問題があるということなのですけれども、現状としては、大分改善されてきているとは思うのですけれども、保護者の金銭的負担という点、あるいは、様々な事務費用が、区立でやっているのだったら区の事業の中でやるわけですから、特別園ごとにかかるということはないと思うので、だからあえて事務負担軽減のため２２０万円出しているというふうに思うのですけれども。","respondent":"中元保育支援課長","answer":"残りの４,３００円という部分が補助金として給付され、こちらは税区分が、所得割課税額が７万７,１００円以下の世帯で第１子の方であれば、保育料の月謝は、こちらもかからないという形になってまいりますということで、様々な補助により。","id":"exchange-081"},{"speaker":"田中委員","kind":"確認","question":"すみません、１点確認したいのですけれども、さっきの事故報告書のところで、軽微なものは各園で報告書を上げているということで、そうではない、例えば、置き去りだったりとか、そういうものが起きてしまったときの報告は、品川区に一旦報告書が上がってから、そこから東京都や国に上がるのかといったところだけ確認させてください。","respondent":"中元保育支援課長","answer":"重大事故として規定されているものにつきましては、一旦品川区に上がりまして、こちらを経由して都のほうに出しています。","id":"exchange-082"},{"speaker":"くにば委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いいたします。私事ですが、長女が、あした、あさって、正に私立幼稚園の入園というか、面接日で、かなりどきどきしているのですが、ぜひとも公立の幼稚園だけではなく、私立幼稚園の教育費であるとか保護者への負担に対する拡充をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"}]},{"id":"topic-08","title":"令和４年陳情第５０号 品川区立伊藤幼稚園の閉園までのスケジュール見直しに関する陳情","agenda":"令和４年陳情第５０号 品川区立伊藤幼稚園の閉園までのスケジュール見直しに関する陳情","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"公開されたことについては、私たちは歓迎するのですけれども、この８月２２日に資料は完全に内部の資料なので、情報公開という形をとってほしいと言っていたその方針が変わったのはいつなのか、そして、今後もこういう事業決定の経緯等が示される資料は公開に向けていただきたい、その方針に立ってほしいと思うのですけれども、いかがでしょうかということをまず２点伺います。","respondent":"立木保育課長","answer":"これまで進めてきました今後の区立幼稚園の在り方検討につきましては、昨年度、需要調査をさせていただきまして、３,０００余の区民の方からご回答いただいております。そういった事実データに基づきまして検討を進めてきておりますので、そこのところをベースにしたです。","id":"exchange-084"},{"speaker":"田中委員","kind":"質問・要望","question":"資料を示された、公開されたということは本当にいいことだと思うのです。区として情報開示を進めていく姿勢に立ってくれたことは、すごく歓迎したいのですけれども、ただ、今後もこうした事業決定の経緯が示される資料は、本来、委員会でも示されるべきですし、情報公開請求をするまでの資料ではないと思うので、ぜひそういった視点に立っていただきたいと改めて求めますが、いかがでしょうか。","respondent":"立木保育課長","answer":"正にその適正規模というところで検討を進めてきておりますので、何ら根拠に反しているものではないと考えていますし、私どもがお話をさせていただいているのは、なぜそれを決定したのか、その根拠をというようなことだったと思いますので、検討委員会を開いて、方針として、まず。","id":"exchange-085"},{"speaker":"田中委員","kind":"質問","question":"保護者、地域住民等ということがちゃんと主語にあって。だから、なぜ品川区に限っては保育課が進めていくのかということを伺いたいというのと、プロジェクトの議事録も、私、すごく読み込んだのです。そういうところも見られて、これはどうしたのかなということがとても不思議です。どうしてここまで拙速に進めなければいけなかったのかというところを、もう一度改めて伺いたいと思います。","respondent":"立木保育課長","answer":"おおむねそういった形で、１年、最短のスケジュールでいくというような形で、大きな反対が出ていないというようなところ、それからやはり区としましては、行政資産、様々な人の部分ですとか、お金の部分ですとか、物の部分ですとか、そういったことを勘案した中で。","id":"exchange-086"},{"speaker":"田中委員","kind":"確認","question":"この在り方検討会の中の話を伺いたいのですけれども、たった２回であり方検討プロジェクトチームは終了しているのです。２０２２年６月１０日にあり方検討委員会が開かれます。検討委員会の議事録を確認したのだけれども、質問者には委員の名前が出ています。しかし、回答者の名前は出ていません。その回答者というのは誰が答えているのかお知らせいただけますか。","respondent":"立木保育課長","answer":"事務局側で答えております。事務局は保育課に置いてありますので、保育課長もしくは保育課の関係者ということになろうと思いますが、そこの部分は、委員と事務局サイドという、そういうような体制になっていると考えています。","id":"exchange-087"},{"speaker":"田中委員","kind":"質問・要望","question":"やっぱり保育課が回答者ということで確認がとれました。なぜ保育課は、教育委員会の声も聞かずに急いでしまったのか、閉園の決定者は保育課ということでいいですかというところを確認したいと思います。転用は可能なのですかというところと、そして、保育課はどのような転用を想定して地域の理解を得ようとしているのかというところをお知らせください。","respondent":"立木保育課長","answer":"プロジェクトも含めて、検討委員会を続けてやってきている場の中では、当然いろいろな議論があります。","id":"exchange-088"},{"speaker":"田中委員","kind":"質問","question":"これも答えているのは保育課ということでいいですかということを聞きたいのと、１９９７年の第二延山幼稚園の閉園では、方針は学務課長が出しています。これはどこ、誰が素案を上げているのですかということを伺いたいと思います。８月１２日の起案が「至急」という文言になった理由と、幼稚園の閉園起案責任者が保育課で、決定権者が区長ということは、法律上の問題はないのでしょうか。","respondent":"立木保育課長","answer":"それを一旦、検討委員会の中で見ていただいておりますが、まだ素案の案という状況で止まっているところですので、第二延山幼稚園閉園時の学務課方針というものはありますけれども、今後どうしていくかというところも含めまして、これから区立幼稚園の方向性といいますか。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問","question":"だから、もうちょっと猶与、教育委員会が言うように、時間に余裕を持たせるべきだったのではないでしょうかということを伺いたいというのと、１９９７年の区立幼稚園集約化方針では学務課長が通知しているけれども、現在は方針の案だから、この方針の素案を誰がという表記がないけれども、今後は教育委員会になるのか、事務局という保育課なのか伺います。","respondent":"立木保育課長","answer":"検討委員会では、先ほど申し上げましたが、様々な議論がなされております。","id":"exchange-090"},{"speaker":"田中委員","kind":"意見","question":"やっぱり本来であれば、この幼稚園の閉園についての進め方というのは、教育委員会が進めるべき事案だったのではないかということは、保育課も理解はしていて、今このような状況に、なぜ私も保育課とやり合っているのかよく分からないのです。だから、なぜかなというところをもう１回、区民の方にも分かりやすく説明できるようにお知らせいただけますか。","respondent":"立木保育課長","answer":"そうした中で、子ども行政として今後の在り方を検討していく中で、区立幼稚園の方向性としては、こういう方向にいくのだということを今回決めさせていただいたということですので、それは、むしろ逆に、私どもがやるべき話だというふうに思ってあります。","id":"exchange-091"},{"speaker":"田中委員","kind":"質問・要望","question":"分かりました。そうですよね。質問を続けます。保護者からのご意見です。利用者の方たちに、この陳情の中にもありますが、誠意を持った対応をしてほしいというのは本当にそのとおりだと思うのですけれども、今後どのような対応をされるのか伺いたいということと、１年延長したからそれでおしまいではなく、きちんと利用者と今後について話し合える機会を設けていただきたいと思いますが、いかがでしょうか。","respondent":"立木保育課長","answer":"今後の進め方につきましては、教育委員会ともよく協議をして、どのような形でご利用者の方たちに、こういったことをご理解いただくのがよろしいのかというところは、いろいろ検討してまいりたいと思います。","id":"exchange-092"},{"speaker":"田中委員","kind":"質問","question":"教育委員会の中で意思決定をするといったことでした。それがあって、また今度、先ほどの説明だと、これから幼稚園の本当に閉園するかどうかの決定を教育委員会が決定すると、もう１回教育委員会で示されて、閉園の決定について賛否を問うということなのですか。順番がおかしいし、教育委員会としても、これは困ったなという感じになるのではないかと思うのですけれども、いかがでしょうか。","respondent":"立木保育課長","answer":"区立幼稚園全体の方向性を決めさせていただいているということですので、個別の廃園手続等につきましては、これから子ども未来部、区長部局と教育委員会とで進めていく形になるということをご説明させていただいているところです。","id":"exchange-093"},{"speaker":"田中委員","kind":"質問","question":"はい、分かりました。今でもやっぱり混乱します。９月から来年度伊藤幼稚園を募集しないと区のホームページに掲載していたので、変更になったなら注記等があってもよかったのではないか。今、勝手に混乱しているかのような言われ方というか、ちょっと言い方は悪いかもしれないですけれども、混乱させているのは品川区の保育課ですからということを私は強く言いたいと思います。一旦やめます、私。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"安藤委員","kind":"質問","question":"本当にそうだなと思うのです。こちら、未就学児の会、未就園児の会というものもありますし、この間も、こういう区の拙速で、ここに書いているけれども、乱暴だと思うのですけれども、乱暴な対応というのに反省はあるのでしょうか。伺いたいと思います。","respondent":"立木保育課長","answer":"その都度、その都度、しっかり立ち止まりながらといいますか、そのときの状況をしっかり検討しながら柔軟に対応していくということで考えているところです。","id":"exchange-095"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと反省があるのかないのか、間違いがあったのかどうかは、はっきりとは答弁がないのかと思うのです。今のお話を聞くと、結果として想定した以上にそういうお声があったということで、想定が甘かった、考えが甘かったというのは、区の反省点なのでしょうか。もう一度お伺いしたいと思います。","respondent":"立木保育課長","answer":"いろいろなことを想定している中で、方向転換したほうがいいだろうというような形に考えが至ったです。","id":"exchange-096"},{"speaker":"安藤委員","kind":"質問","question":"一般的なニーズ調査なので、やっぱり伊藤幼稚園に通っている方とか地域の方は、この幼稚園に入りたいという、通いたいということなわけですから、その地域、その当事者、就学前の保護者の方も含めて声を聞かなければ、私は当事者の声を聞かずに方針を決めたということになると思います。そこに反省はないのか伺いたいと思います。再検討もあるでしょう。そういう考えはあるのか伺いたいと思います。","respondent":"立木保育課長","answer":"説明会等の部分に関しましても、これから検討する中で説明会等も検討していくような答弁をしていますので、このような形で今後の進め方をいろいろ検討させていただきたいと思っているところです。","id":"exchange-097"},{"speaker":"安藤委員","kind":"質問・要望","question":"検討会、浜川や城南も含めてということですけれども、検討をするということですが、私が求めているのは、やっぱり方針は変えませんと、もう閉園の方針は、私たちが決めたのだから、それをどう理解してもらうかという説明ではなくて、方針を決める上で説明会を開いて、当事者の意見もよく聞いた上で、その方針決定にいかす、そういう説明会をしていただきたいというふうに思いますが。","respondent":"立木保育課長","answer":"説明会等につきましては、今後進めていく中で検討させていただきたいと思っているところです。","id":"exchange-098"},{"speaker":"安藤委員","kind":"質問","question":"公平性という話もありましたけれども、区立幼稚園を、資源の有効活用ではないから閉めますと言った後に、閉めない、続けると言って、怒る人はいるのですかというか、子どものために、どうぞ使ってくださいと、豊かな品川の子どもの育ちのためには使ってほしいという方が私は多数だと思いますし、そして今、定員を切っているというのであれば、例えば、さらに魅力を発信して通ってもらう努力をするとか。","respondent":"立木保育課長","answer":"学級編制につきましては、先ほどちょっとお話に出ていたのですけれども、学務課のほうで決定しております１０人に満たない場合は学級編制をしないという基準があります。","id":"exchange-099"},{"speaker":"安藤委員","kind":"質問・要望","question":"１０人を下回った場合は、もう学級編制しないというのは、あまりにも機械的で、教育的な根拠も乏しいというふうに思います。追い込んでしまったのですよ。そのとおりだと思うので、そちらにそういう手順があるかもしれませんけれども、仮に希望が１０人を下回った場合でも、しっかり存続に向けて頑張る、教育環境の充実に向けて頑張るということをやっていただきたいと思いますが、いかがでしょうか。","respondent":"立木保育課長","answer":"明日、明後日の入園の状況を見させていただいた上で区として判断させていただきたいと考えています。","id":"exchange-100"},{"speaker":"田中委員","kind":"質問・要望","question":"区立幼稚園の意義と、伊藤幼稚園だから通いたいという保護者、子どもがいるということを、本当に忘れないでいただきたいということは、最後、きちんと伝えたいと思うのですけれども、品川区が考える区立幼稚園の意義というところを確認させてください。","respondent":"立木保育課長","answer":"区立幼稚園の成り立ちは、以前の委員会でもご説明させていただいたかもしれないのですが、私立幼稚園のほうが幼稚園の教育という部分に関しましては先行しておりまして、昭和４０年代に、私立幼稚園への入園希望者が増え。","id":"exchange-101"},{"speaker":"田中委員","kind":"質問・要望","question":"区立幼稚園の意義、あと、地域の中にある区立幼稚園ということで、本当に必要としている子どもたち、保護者がいるということを、本当に忘れないでいただきたいということと、今回の閉園のロードマップ、パターン１、パターン２とありましたが、今、パターン２で進んでいる状況ですが、そうではなくて、きちんとそこに通う子ども、保護者、そして地域の人たちと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"渡部委員","kind":"質問・要望","question":"それと、この間の議論の中で、実際、今日の陳情で言いますと、１年間延ばすという話が新たな話としてあって、１年延ばすことが決定されていって、ただ、読んでいて、保育課の説明が云々かんぬんで、補助執行をしているわけですから、保育課の説明は区の答えですよね、誰が聞いても。当然、品川区の子育てを今担っていっているのは保育課なわけですから、そこが説明をしているから、そこは最終決定でしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"若林委員","kind":"質問","question":"ここの場での保護者の耳に入るまでのタイミングが、ここが今回、短かったので、私どもも１６日に拙速だというふうに指摘をせざるを得なかったわけですけれども、これはもう補助執行であろうが何であろうが、ここのタイミングを、こういうパターンの場合は、少なくとも１年前には言いましょうねとか、ほかの区でも、いろいろなパターンがあるのでしょうけれども、そこはやっぱりお互いのために。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張するのですが、１年閉園を延期という措置がとられたというのは、当初のパターン２であったということになる。城南、浜川も含めて、区の閉園の方針は一度白紙にしていただきたい。そして、スケジュールは当然、閉園そのものの見直しも、当事者参加でぜひ検討していただきたいという意見を述べさせていただきまして、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"くにば委員","kind":"質問・要望","question":"なので、気持ちは重々分かるのですが、ただ、この陳情の要旨であるとか、あとは、区が、今回の件で実際に反省というか、こういうふうにすべきだった、今後こういうふうにすべきだという部分に関して、一定の、例えば、スケジュールの見直しについては、保護者からというか、今回のことがあって、正に柔軟に素早く１年閉園を延期する、なかなかそこまで素早く対応することは難しい中。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張します。きちんと説明をしてほしいということが大前提にある文章だということは読めます。本来なら、３、４年以上前から、もし閉園の方向があるのだったら公表すべきというのは、本当にごもっともだなということです。そういった意味での訴え、７３３名、この陳情代表者の方を含めて７３４名の方たちの意見は、本当に重いものだと思います。皆さんに投げかけます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/449994?Template=document&Id=5080#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":82597,"voices":355}},{"id":"r04-20221031-5","meetingId":"r04-cm10","date":"2022年10月31日","dateIso":"2022-10-31","committee":"総務委員会","time":"午前１０時００分～午後 ３時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を110件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３の役職定年制のところで伺いたいのですけれども、現在、管理職は、部長、課長がそれぞれ何人いるのか教えていただきたいのと、そのうち再任用の部長、課長がそれぞれ何人いるのかも教えていただきたいと思います。個人型で言えば、「特別な業務・特別な事情」と書かれているのですけれども、それは具体的にどういう場合なのか、それを規定するものがあるのか、その点を伺いたいと思います。","respondent":"崎村人事課長","answer":"個人型の特別な業務、特別な事情に何か具体的なものがあるのかですけれども、特に今すぐに思いつくものはございませんけれども、例えば、複数年にわたるような特別なプロジェクトを進めている者が６０歳で役職から降りるとなったときに。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それと、部課長は、６０歳になった後は、来年の４月以降は、基本、管理職以外の職に降任になるということになっていくのでしょうか。それもまた本人自身もすごく働きにくいということになっていかないのかと思うのですけれども、そこら辺のところはどうなっていくのか、どう考えられているのか、伺いたいと思います。","respondent":"崎村人事課長","answer":"管理職以外の職はどういうところでというお話なのですけれども、こちらは、委員おっしゃるとおり、部長級・課長級が、例えば課長補佐に降任となった場合には、やりづらさというのは当然感じられるのかと思うのですけれども。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"誰が指名するのか。そこら辺のところはどうなっていくのかを伺いたいのです。その声明の中には、そのためにも、課長補佐以下の職層、係長ですとか、課長補佐、主任とか、そのような職層を厚くするということを求め、特別区長会もそれを受け止め、万全を尽くすということで述べられたということが書かれていたのです。そういう点は区もこれからどのように取り組んでいくのかについても伺いたいと思います。","respondent":"崎村人事課長","answer":"課長補佐２年以上ということですので、即戦力として管理職になれるような職員を任命権者が指名するというものです。これも選考に当たりましては、今委員のお話にありましたように、公平性が担保されるように、人事評価に基づいてしっかりと指名をするような形で今検討しています。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、基本的に試験は今のまま、今までどおり試験で課長、部長になっていくということはありつつ、それに足りない分を指名制で補っていくということで考えればいいのでしょうか。","respondent":"崎村人事課長","answer":"足りない分をというと語弊がありますけれども、課長補佐としての経験を積んでいただいて、管理職としての職務、職責を果たせると区のほうで判断をいたしましたら、その職員を管理職として指名をするというのが前提ですので、今委員のお話にありましたように。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"６０歳に達した職員の給料月額というところで伺いたいのですけれども、現在は、６０歳で定年になると、その後再任用で働く方が多いと思うのですが、現在再任用で働く方というのが、定年に達した後、何％ぐらいの方が再任用で働かれているのか。それから、現在、フルタイムで再任用で働く場合、どれぐらいの減額になっているのか、その割合も伺いたいと思います。","respondent":"崎村人事課長","answer":"給与につきましては、再任用については単一の給料月額となっておりますので、その職員がその級で受けていた給料月額によって、どのぐらい下がるかというのはかなり差があるのですけれども、大体一般的に６割から７割ぐらい引下げになるといったところが。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、再任用で働かれる方は、６０歳で定年になって、再任用で働き続けたいということで、希望すれば全員、フルタイムで働きたいといえばフルタイムで働ける、短時間で働きたいといえば短時間で働けるということで、希望どおり全員働けるという仕組みになっているのかも伺いたいと思います。もし見直されるのであれば、いつ頃になっていくのか、それも伺いたいと思います。","respondent":"崎村人事課長","answer":"ただ、一方で、民間の部分については、昨年ですか、法律の改正がありまして、高齢者雇用安定法などが施行されたところで、７０歳までの雇用確保の努力義務も課されているところですので、そういったところも踏まえて、今後、定年年齢が６５歳に引上げになる間に。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"６０歳を過ぎたからといって能力が下がるわけでもないし、同じような形で仕事はできるわけですから、これはぜひ引き上げる方向で、区のほうからも上げていっていただきたいと思います。それが５５歳から５７歳に、昇給の抑制も引き上がるということも聞かれていたのですけれども、そこら辺はどうなるのかを確認しておきたいと思います。","respondent":"崎村人事課長","answer":"６０歳以降、定年引上げになる場合でも、６０歳以降については、そういった勤務成績が良好な成績である職員については昇給がなされるといったところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこの人事評価のところはいろいろ様々意見があると思うのですけれども、本当にこういう形で、年金の年齢が引上げになったことで、また、社会の情勢というのもかなり、６５歳ぐらいまでは働けるような、そういう情勢というものもあるかと思うのですが、そういうところで定年が引き上がるというのはありなのかとも思うのですけれども、同じ労働を続けているのに７割に減ってしまうというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"吉田委員","kind":"質問・要望","question":"私がよく理解できなかったのが、３の役職定年制の例外のところで、今、鈴木ひろ子委員のご質問の中でも少し触れられたのですけれども、具体的に誰がどのようにして判断していくのか。要は、どうやって公平性を保っていくのかと思うのですけれども、その辺について、もう一回、ごめんなさい、繰り返しになるかもしれませんけれども、ご説明いただきたいと思います。","respondent":"崎村人事課長","answer":"公平性というお話がありましたけれども、原則、降任するということがまず第一にあるので、区としての区政の継続的な運営ですとか、業務を進めるに当たって支障が生じないというところを重く捉えて、異動期間を延長するかしないかというのを判断するというものですので、その人の。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"それは分かるのですけれども、やはりこの人とかこのグループにはこういう措置が必要だという、そもそも手続き上、誰かが言い出してという言い方がいいのか、具体的にどういう手続きでこういうことが決まっていくのかというのが、その現場にいないから分からないのかしら、何かもう少し具体的にイメージできるようなご説明は無理ですか。今以上のご説明は。","respondent":"崎村人事課長","answer":"なかなか個人型（勤務延長型）というところについても、その人でなければならない仕事というのがどれだけあるのかということはもちろんありますので、そこが役職定年制が導入された趣旨というのをしっかりと踏まえて。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"あくまで原則としては降任というのに至って、その職務に注視して、特定管理監督職群というのは特別区人事委員会としての判断が最初に入ってくるということで、あまり個人の事情とか、そこの区の事情というよりも、そのようにある程度きちんと客観的な基準になっているという判断でよろしいでしょうか。","respondent":"崎村人事課長","answer":"もちろんこの制度が導入されることになりますと、なぜこの例外を活用したのかということをしっかり説明できなければなりませんので、そこは議会にもしっかりと説明できるような理由を提示して、この制度といいますか。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"今回、定年制の延長ということで、社会がそのような仕組みに変わりつつあるということと、年金の受給時期の変更ということも、このような状況を生んできていると思いますが、今回のこの改正に当たって、現行の制度と、今度変更になる改正後の制度に対して、給与と、それ以外に何かメリット、デメリットというのはどういうものがあるのか。簡潔に教えていただければありがたいと思います。","respondent":"崎村人事課長","answer":"デメリットと言えるのかどうかはあれですけれども、例えば６０歳で定年を迎えて、退職手当が支給されるといったところで、これまで人生設計を考えられた方にとっては、定年が引上げになることによりまして、退職時に退職手当が支給されることになりますので。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"それぞれ皆さん工夫してやって、定年を逆に６０歳で新陳代謝というのですか、長年働いてご苦労された方に退職していただいて、新しい若手職員を採用するというのは、会社にとっていい面もあるのでしょうが、ただ、こうやって働ける年齢もだんだん変わってきて、今６５歳でも７０歳でも元気な人は元気なので、またいろいろこういうことも変わっていく時代が来るのではないかと思います。以上、意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"つる副委員長","kind":"確認","question":"先ほど来の質疑の中の部分の確認で、役職定年を迎えた方が、例えば、課長であれば課長補佐というのが想定であるわけですけれども、やりづらさとか、若干あったのですが、ただ、役職定年を迎えた方の異動部署、その辺はまた別の考え方になるのだと思うのです。","respondent":"崎村人事課長","answer":"異動の考え方といったところのご質問ですけれども、ほかの委員からもありましたように、役職定年によって降任する管理職については、ご本人もやりづらいと思いますけれども。","id":"exchange-014"},{"speaker":"つる副委員長","kind":"質問・要望","question":"まだ考える期間というのがあるわけですので、まさに先日、総務委員会で行政視察に行かせていただきましたけれども、人材育成とか、そういう部分では、品川区だけではなく、他の自治体のよき事例というのですか、そういったこと、全国的にこれが再来年の４月１日からあるわけですので、いろいろな工夫を模索していると思うのです。そこについても同様に７割になっていくのでしょうか。","respondent":"崎村人事課長","answer":"一方で、手当の中でも、例えば、扶養手当ですとか、当然通勤手当、特殊勤務手当、そういう手当については、７割ではなくて、１０割といいますか、従前と同じ額の手当が支給されるというものです。","id":"exchange-015"},{"speaker":"つる副委員長","kind":"確認","question":"その辺りのことということは、法律だとかを確認すると、まさに明文化されているのか。それとも、何か資料とかで私が見落としているのかというところで、その辺の確認ができるところというのはどこを見ればいいのですか。事前に確認できなかったので、あえて伺っている部分もあるのですけれども。","respondent":"崎村人事課長","answer":"一方で、扶養手当ですとか通勤手当については、実費について規定をしていますので、それについては７割にはならないといったところでご確認いただけるのかと考えているところです。","id":"exchange-016"},{"speaker":"湯澤委員","kind":"質問・要望","question":"私からも確認だけさせていただきたいと思います。そのときに、少し確認をしたいのが、定年が延びていくことによって、新規採用とか、そういうことに影響が出てくるのかということと、昇進とか、そういったところでも、待ち時間が少し増えていくというか、そういったことがあるのかというのを確認させていただければと思います。","respondent":"崎村人事課長","answer":"今の状況からしますと、主任ですとか係長級をもう少し増やさなければならないというのは区として認識しているところです。そこはなるべく影響が出ないように、これから考えていきたいと考えております。","id":"exchange-017"},{"speaker":"湯澤委員","kind":"質問・要望","question":"資料にも書いてあるように、本当に６０歳を超えても、豊富な知識、技術、経験等、そういったところに活かしていただきたいと思いますし、また、若い職員のアイデアとか、発想とか、そういったものもやはり品川区にはこれからも必要だと思いますので、そういったところを引き続きしっかりとやっていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"須貝委員","kind":"質問","question":"今の質問で、定年が延長されると、今までは辞めて退職される方がほとんどだったと思うのですが、そうすると、その方たちの職員の数はそのまま増えていくわけではないですか。そうすると、それでも新しい職員の方の数というのは今までどおり変わらないとするならば、やはり職員数が増えていってしまうと、我々は考えておくのがいいのですか。","respondent":"崎村人事課長","answer":"今回、再任用の短時間については定数外なのですけれども、定年前の再任用短時間勤務制というのが引き続きできますし、これもご自身の人生設計と健康上の理由から再任用短時間を選ぶ職員というのも一定数いるだろうということを考えますと。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"少しだけ意見を言わせてください。先ほど６０歳になったときの給料月額が下がるということについては、少しどうかと思ったのですけれども、やはり働く期間を延ばすというほうを優先して、かつ、後進に道を譲るという言い方は変ですかね、若い人たちにもどんどん積極的に関わっていってもらうことも同時に考えた場合、この面はあってもやむを得ないかと判断いたしました。全体としては賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-02","title":"第７０号議案、品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する条例の一部を改正する","agenda":"第７０号議案、品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人情報の提供に関する条例の一部を改正する","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは東京都の補助金が所得制限がついていて、品川区がそこに助成して所得制限をなくすということにするために、それぞれの所得を把握することが必要だということで、そのときにマイナンバーを使うということで捉えていいのか、そのことを確認させていただきたいと思います。","respondent":"宮澤情報推進課長","answer":"委員のご指摘のとおり、東京都の補助金を受けるに当たり、所得状況の制限がありますので、状況を把握するために個人番号を利用するというものです。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここには庁内連携をするために必要な改正を行うということなのですけれども、庁内であれば、税情報とかはマイナンバーがなくても連携は取れるのではないかと思うのです。その点を伺いたいと思います。それから、区民にとっての具体的なメリットというのは何があるのか、お聞きしたいと思います。","respondent":"宮澤情報推進課長","answer":"１点目の庁内連携です。庁内の税情報につきましては、マイナンバーの利用がなくとも連携はできるところですが、マイナンバーを利用する事務として条例上に追加するものであります。続いて、メリットの部分です。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"結局、今回こういう形でここに改めて定めることによって、具体的なメリットというのが、他の自治体からの転入者が他区から転入するときに、どれぐらい税金を払っていたということでの課税証明書を取らなくてもよいということがメリットということになるのか、その点の確認をお願いしたいと思います。もし必要であればどのように取るのかという、その同意についてお聞かせいただけたらと思います。","respondent":"宮澤情報推進課長","answer":"１点目です。他自治体に情報照会することによって、区民の皆様が申請する際に、所得の証明書を添付するのを省略することができるというのが、この情報連携のメリットの１つになってあります。２つ目の同意の部分です。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そうしますと、条例を見ると、ざっと数えたところ５５ぐらいの事務がマイナンバーを使う事務の中に様々書いてあるのですけれども、これは区民が子ども医療費の助成事務だったりとか、ひとり親家庭の医療費助成事務だったりとか、前回、今年の２月でしたか、障害者の様々なサービス利用に当たってのいろいろな事務なども、この条例の中に規定されることになりましたけれども。","respondent":"宮澤情報推進課長","answer":"区の独自利用事務については、委員のご指摘のとおりです。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"分かりました。そういう場合、委託業者というのは、おおよそこの条例の中に書かれている事務を取り扱っているところで、どれぐらいの委託業者が関わられているのか、そこら辺のところが分かったら教えていただきたいのです。マニュアルだったりとか、管理の仕組みだったりとか、そこをどこがどのようにされているのかというあたりをお聞かせいただけたらと思います。","respondent":"宮澤情報推進課長","answer":"ただ、それぞれの独自利用事務を行っております各所管部署において、委託をしている場合は、委託の契約を結び、その契約の中で個人情報の取扱いに関する特記事項というのを設けまして、個人情報の適切な取扱いについて委託業者に求めている、契約の中で取り交わしています。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それとも、その課に任せて、その課がやるということになっているのか。それとも、庁内全体として、そのようなものはこういうマニュアルがありますとか、そういうものがあるのかどうなのか、その点も伺いたいと思います。","respondent":"宮澤情報推進課長","answer":"データの保管に関して基準等を設けて、庁内周知も図っておりますし、セキュリティガイドラインを設けております。そういう形で、セキュリティ対策を取っております。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのようなところのセキュリティというか、今言われたみたいにマイナンバーを取り扱うところは限られていて、セキュリティがこのように管理されていてということのチェックそのものも、情報推進課としてもされているのか、その辺りをお聞かせいただきたい。","respondent":"宮澤情報推進課長","answer":"そこにつきましては、契約の主体は各所管部署が契約を行いますが、情報推進課に関しても支援をしておりますので、把握はしているところではあります。ただ、個人番号を取り扱う事務の中でシステムを使わない部分がありましたら、その委託の部分に関しては把握していないです。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"情報推進課とか庁内で、ぜひそういうところは、漏えいとか何かが起こらないような、そういうチェックも含めて慎重にやっていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"先ほど鈴木ひろ子委員のご質問にもあったと思うのですけれども、申請する当事者にとってのメリットというのは、要するに、例えば、転居してきたときには、前の自治体から情報を取得して提出する必要がなく、代わりにマイナンバーを申請するといいますか、マイナンバーを出せばいいという。それだけというか、そういうメリットなのでしょうか。ほかのメリットが何かあったら教えてください。","respondent":"宮澤情報推進課長","answer":"ただ、区内にお住まいの方であれば、庁内連携を行って確認はするですので、メリットと言われると、区外から転入されてきた方の省略が一番大きなところかと考えています。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"要は、区内にずっとお住まいの方にとっては、手続き的に特に便利になるとか、そういうことではないということなのですか。","respondent":"宮澤情報推進課長","answer":"区民の皆様の申請に関しては、確かに添付するものはもともとないので、メリットはないのですが、ただ、個人番号を取り扱う事務としては条例上に規定が必要です。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"それは分かります。当然だと思います。新たに追加があるのだったら。結局は、基本的に形式的に、たとえＤＶをやっている人であっても、その人が扶養している人ということであれば、制度的には逃げている人たちのほうに有利になるということにもならないという理解でよろしいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問・要望","question":"皆さん結局、国に対して信頼を持てないということと、それがイコール、マイナンバー。そしてマイナンバーは必要なのだというのは、皆さん、多くの方は理解しているのですが、やはり委託業者にいって、それで情報が漏えいされる。かなりの方が心配しているからなかなか踏み込めないということは、私は理解していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"マイナンバーを使いますということで、同意書も取って申請をするということになると思うのですけれども、マイナンバーを使うことに対して同意しませんという方の場合は、例えば、転入をするときには、課税証明書とかを持ってくるということをすれば、同意しないでマイナンバーを使わないという選択はできるということでいいのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういう形でマイナンバーを使いますよということで条例の中に規定されている事務であっても、マイナンバーを使うことに同意しませんという方はどうなるのですかということなのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"反対です。そもそも共産党は、政府が国民一人ひとりに生涯変わらない番号をつけて、他分野の個人情報をひもづけして利用するようにすること自体、プライバシー権の侵害の危険を持つ重大な問題だと、マイナンバー制度を廃止すべきとの立場です。今回の条例はさらに利用を拡大するものであり、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"吉田委員","kind":"意見","question":"反対します。理由は、私たちも基本的にマイナンバー制度に反対をしております。ただ、区民がすごく便利になるとか、利便性が上がるとか、そういうメリットがあったときにどのように考えるのかと思ったのですが、今回のことについては特にメリットがないということですので、反対いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"}]},{"id":"topic-03","title":"第９４号議案、しながわ区民公園北側ゾーン改修工事（第二期）請負契約","agenda":"第９４号議案、しながわ区民公園北側ゾーン改修工事（第二期）請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"この契約の概要については資料に書かれているのですが、主な工種が１８ページに書かれています。できたら、規模というか、このマンホールトイレを造ることによって、防災力が今までよりどれぐらい、どういう形で強化されるのかということをご説明いただけると大変ありがたいのですが、いかがでしょうか。","respondent":"高梨公園課長","answer":"その際に、こちらに避難される方、また、一時身を寄せる方がトイレに困らないようにということで、この部分にマンホールトイレを、南側ゾーンにも設置をしていますが、北側ゾーンには二式、第一期、第二期工事とそれぞれ設置することで。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"そうすると、そこに避難される方がどれぐらい、公園課の所管を外れてしまうかな、どれぐらいという想定の下に、今、こういう状況である、このように考えているという理解でいいかと思うのですけれども、まださらに必要なのか。それとも、これで一定、ここに集まってこられるだろうという方たちには十分なものになっていると理解していいのか、その辺、もう一度教えていただけますか。","respondent":"鈴木（真）委員長、高梨公園課長","answer":"防災課の所管に入るところもあると思うので、公園課長の答えられる範囲でお願いします。このしながわ区民公園は国道に近いということで、帰宅困難者の方が一時身を寄せる場所としても考えられているところですので、様々な場面について。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問・要望","question":"おっしゃるとおりだと思います。どこまで想定しても、なかなか難しいところはあると思うのですが、可能な限りということで了解いたしました。一緒に聞けばよかったのですけれども、同じように、植栽工一式というのも、この契約金額の中でどこからどこまでが含まれるのか、それも教えていただきたいと思います。","respondent":"高梨公園課長","answer":"植栽工一式ですけれども、こちらは開園から約４０年ぐらい経ってありますので、非常に密に植栽されているようなところもありますし、今回新たに防災対応で、園路を６ｍ幅にするために、一部、樹木を移植や伐採することもありますので、その移植や伐採、また。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。この間、２回目の説明会、また、今後のあり方などについても説明会を開いていただきましたけれども、そのような、公園課としての区民に対する説明というのは別の問題として、今、公園課として予定している植栽に関する工事が全部ここに含まれるという理解でよろしいのでしょうか。","respondent":"高梨公園課長","answer":"しながわ区民公園北側ゾーンにつきましては、この第二期工事で終了ですので、再整備に係る植栽に関する工事はこの部分に全て含まれているという認識です。","id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"最後は意見です。そこに全部一式含まれているとしたら、こういう予算でこういう使い道なのですという理解を、ぜひこれからも周辺の方たちに、その公園を愛してくださっている全ての方に理解していただけるような説明は、また公園課として丁寧にしていただくよう要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-04","title":"第９６号議案 ロッカー他の買入れ","agenda":"第９６号議案 ロッカー他の買入れ","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このロッカー等の納期が令和５年３月２０日なのですけれども、児童相談所の開設は令和６年１０月で、これは竣工するのはいつぐらいなのでしょうか。少し早いのかなと思って……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"来年の１月に竣工。そうなのですね。すみません。そこら辺のところのスケジュール感を教えていただけたらと思います。","respondent":"長谷川児童相談所移管担当課長","answer":"竣工時期に関しましては、令和５年１月頃を予定しております。その後検査を終えまして、物品納入が令和５年３月２０日ということで予定しております。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、１月に竣工して、３月２０日にこういう様々なものが入って、開設までに１年半くらいかかるというのは、どういう準備で１年半くらいかかるのか、その点を教えていただけたらと。この契約議案の内容とは少し違うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"吉田委員","kind":"質問","question":"こういうものは、やはり一定更新をしていくものだと思うのですけれども、そういう今後のことも含めて、体制が少し足りないと思ったら買い足されるとか、そういうことがあると思うのですけれども、そういうことを前提に、今回このように契約金額をはじき出しているという理解でよろしいのでしょうか。","respondent":"長谷川児童相談所移管担当課長","answer":"その人員が働くときに必要な物品、あるいは、子どもを一時保護する場面で使う物品、こういったものの積み上げで計算しております。","id":"exchange-045"},{"speaker":"吉田委員","kind":"質問","question":"一時保護するときの物品もこの中に入っているということなのですか。一時保護のものと、私のイメージの中ではずれるのですけれど、またその辺を教えてください。","respondent":"長谷川児童相談所移管担当課長","answer":"今回ご提案させていただいている什器、家具類の中には、一時保護所の中で使う物品も含まれております。その物品に関しましては、必要児童数を算出して、その上で積算をしております。","id":"exchange-046"}]},{"id":"topic-05","title":"第９５号議案、会議テーブル他の買入れ","agenda":"第９５号議案、会議テーブル他の買入れ","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"今回、総合区民会館に新規に会議テーブル他の買入れをするということですが、中には、全然使用に堪えるものもあると思うのですが、今回、全面的に新規購入ということで買い換えるのでしょうか。教えてください。","respondent":"篠田文化観光課長","answer":"今回の施設の改修に伴う物品の買換えにつきましては、当然、これまでも古いものは順次換えてきてありますので、使えるもの、使えないものをきちんと仕分をした上で、今回の改修に当たりまして、新たに買い換えたほうがいいだろうというものだけを選んでおります。","id":"exchange-047"},{"speaker":"須貝委員","kind":"意見","question":"それで、恐らくそのような対応はすると思うのですが、安全ではあると思うのですが、使えるようなものがありましたら、恐らく各区有施設のほうに、これを使うかどうかという問合せはしてくださると思うのですが、施設によってはすごく古い、老朽化した椅子とか机を使っているところが多々あるので、その辺、ご配慮をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"吉田委員","kind":"提案","question":"そういうときに、大体今までもこういう会館の会場を使っていた団体に要望を聞く場面があるとか、その結果このように決められたのか、それとも、あくまで事務方の考え方と契約の相手方の提案で決められてしまったのか、その辺を伺いたいのですけれども。","respondent":"篠田文化観光課長","answer":"場所が決まっていて、そこで何台、どれだけ入れなければいけないというのがありますので、そこが基本にはなるのですけれども、これまで当然３０年以上運営してきてまいりまして、様々なご意見を頂戴しています。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですので、そういう方たちがどんどん意見を出してくだされば、多分届いていると思うので、問題ないのですけれども、そういうこともあるということを想定していただいて、ぜひみんなが使いやすいものになるように考えていただけたらいいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"つる副委員長","kind":"確認","question":"令和５年１月に部分開館ということで、一応、確認すると、来年の２月からイベントホールが使えるようになるということと、それ以外の場所もあるかと思うのですが、１月から部分開館で、今回の購入は納期が３月２０日ですね。これは先ほどの児童相談所も、納品先は別ですが、同じ納期、３月２０日になっているのです。これはそういう事務手続き等で何か意味のある日付なのでしょうか。","respondent":"篠田文化観光課長","answer":"今回のきゅりあんに関しましては、大ホールが来年の９月いっぱいまで工事がかかりまして、１０月から開館の予定です。そのほかの部分につきましては、２月１日から開館を予定しています。","id":"exchange-051"}]},{"id":"topic-06","title":"第９２号議案、（仮称）西大井三丁目障害者グループホーム新築その他工事請負契約","agenda":"第９２号議案、（仮称）西大井三丁目障害者グループホーム新築その他工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"防災広場のほうで、かまどベンチ２基というのがこの契約金額の中に入っていると思うのですけれども、かまどベンチの数え方が分からないのです。かまどベンチ２基というと、いわゆるかまどというのは２つしかないものなのか、それとも、ベンチだから、それを設置したら二、三個つくものなのか。どういうレベルのものがこの契約金額の中に入っているのか、教えてください。","respondent":"小林施設整備課長","answer":"かまどベンチですが、かまどの数ではなくて、ベンチの数ですので、かまどにつきましては、そのサイズに応じたものが使用できるということで、ベンチとしては２台です。","id":"exchange-052"},{"speaker":"吉田委員","kind":"質問・要望","question":"防災広場としてその規模で十分なのか。この広さだったらどれぐらいが妥当なのか。お考えを改めて確認させてください。それから、よくこういう建物のときに、今回はグループホームですけれども、大体今、新しく造るときには、例えば太陽光発電とか、そういう環境配慮というのでしょうか、そういうものについての機能がいつも付けられているように理解していたのですが、今回はそういうことは難しかったのか。","respondent":"大石木密整備推進課長、小林施設整備課長","answer":"基本的には意見を聞きながら、あとは公園施設、または防災広場として十分な機能を発揮できるような形で検討してきた結果が、この結果となっております。この施設につきましては、太陽光パネルの設置、あるいは断熱性の高いガラスや、空調機につきましても高効率のものを使用するなどして、環境学習施設エコルとごしでは。","id":"exchange-053"},{"speaker":"吉田委員","kind":"質問","question":"すみません。図面を見落としていました。分かりました。欲張ったことを言うようですが、私、いつも聞くので、お許しください。防火水槽というのは、防災広場のほうにはついているのですけれども、あくまで趣旨としては防火ですよね。この建物に関しては、例えば、中水の雨水利用とかは難しかったということなのでしょうか。検討されなかったのか、教えてください。","respondent":"小林施設整備課長","answer":"雨水利用ですが、この施設につきましては、貯水タンクを外構の下に埋設してございまして、これらにつきましては外構の植栽に利用する計画として計画しています。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、太陽光パネルがつくというご説明もあったのですけれども、何ｋＷ分ぐらいなのかを一つ教えていただきたいです。グループホームのほうなのですけれども、知的障害者のグループホームということですが、重度化も見据えたグループホームになるということになってくるのかと思うのですけれども、エレベーターとか、そういうバリアフリーの状況がどういう状況になっているのかを教えていただきたいと思います。","respondent":"小林施設整備課長","answer":"バリアフリーの観点ですが、エレベーターについては１基、施設に設置しています。それ以外につきましても、スロープであったりとか、段差の解消とか、そういったものを多用しまして、バリアフリーに十分対応した施設になってあります。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"エレベーターの印はどこかに書いてあるのか、見つからなかったので聞きたいのですけれども、どこら辺につくのか。そうすると、身体（の障害）がかなりの重度になっても対応可能という施設になっていると考えているのか、その点をお聞かせください。","respondent":"小林施設整備課長、川崎障害者施策推進課長","answer":"エレベーターにつきましてですが、内部のプランにつきましては、これから所管課のほうからお話があるかと思いますが、施設を利用される方がいらっしゃるということもございまして、白紙にはなってありますが。そうすると、中度とも重度とも考えられる方にはなるのですけれども、１階に関しましては、やはり車椅子を利用される方もいるので、バリアフリーを含めた環境というのは整えていきたいとは考えております。","id":"exchange-056"},{"speaker":"吉田委員","kind":"質問・要望","question":"私、以前に、別の施設のときにそれを確認するのをうっかり忘れて、エレベーターがついているからそれで避難ができるのだと思い込んでいたのです。電源は別だとおっしゃったので。今回はその辺はどうなのか。そういう避難用のエレベーターというのは別の基準があるのですけれども、それはそのときには知らなかったので、今回はきちんと確認したいと思いますが、いかがでしょうか。","respondent":"川崎障害者施策推進課長、小林施設整備課長","answer":"地域の方のご意見ということなのですけれども、西大井三丁目につきましては、住民説明会を３回行いました。今回、１階に多目的室というものを造っております。エレベーターですが、結論から申し上げますと、停電になれば使えなくなります。２階建てということもありますし、階段につきましても、２方向避難をしっかり取れているところもございまして、動かないことになります。","id":"exchange-057"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。ぜひ、こういう施設ですので。それから、もう一つが、住民説明会は３回行われたということでよいと思うのですが、私が先ほど申し上げたのは、この建物の、今、設計段階に来ているわけですから、その中身について、利用を想定されるような方たちのワークショップというのはされたのかどうかということを確認したかったのですが、その点についてはいかがでしょうか。","respondent":"川崎障害者施策推進課長","answer":"利用を想定される方のワークショップというのは開いてはございません。","id":"exchange-058"},{"speaker":"吉田委員","kind":"質問・要望","question":"少し聞いてくれればこんなことにはならないのにというのは、すごく叱られつつ、いつも見学するのです。ですから、そういうご意見をあらかじめ聞いておけば、区にとってもすごく有効な意見になるし、そういうものは蓄積されていきますので、こういう機会にはぜひそういうワークショップを開いていただきたいのですが、見解を伺いたいと思います。","respondent":"川崎障害者施策推進課長","answer":"今後、利用者のニーズを踏まえて、皆様からのご意見を基に、こういったグループホームの整備の中身についても検討していきたいと思います。努めたいと思います。","id":"exchange-059"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひそうしていただきたいです。本当に早い段階で意見を聞いておけば、そういうものをわざわざ改修する手間が省けると思うのです。私たち、すごく強くご要望をいただいているので、声をかけてくれればそういうことには参加するからという団体も既にいらっしゃいますので、ぜひその辺は前向きに検討していただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"須貝委員","kind":"質問","question":"先ほど停電になったらエレベーターは使えないというお話がありました。停電になったときは、一般の、普通の電灯類を含めて、全然使えなくなってしまうのかどうか。その点、先に教えてください。","respondent":"小林施設整備課長","answer":"蓄電池には、およそですが、各事務室とか、中にあります居間であったりとか、そういうところの照明器具であったりとか、コンセントの一部が使用できることになってございまして、簡単な蓄電池の状況ですと、約１日半から２日ほど使える蓄電池を設置していますので。","id":"exchange-061"},{"speaker":"須貝委員","kind":"質問","question":"そういう備えがあるというのはすごくいいことなのですが、実際、東京都の防災計画もそうですけれども、やはり最低３日以上は必要だと。確かに蓄電池はいいのですが、今度それが切れてしまえば、充電ができないですから、そのままずっと使えなくなるということは、考え直したほうが、何か追加して、やはりそういう装備を置くべきではないかと私は思いますので、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"}]},{"id":"topic-07","title":"第９３号議案、（仮称）北品川高齢者多世代交流支援施設新築工事請負契約","agenda":"第９３号議案、（仮称）北品川高齢者多世代交流支援施設新築工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"トイレのことなのですけれども、どのように使う人を想定しておられるのか分からないのですが、これだと、普通の個室だけということなのでしょうか。それこそ多世代交流ということであれば、いろいろな方たち、車椅子の方が利用されるとか、そういうこともあるのかと思うのですが、バリアフリートイレというのはここにありますけれども、基本、そんなにはご利用はないだろうという感じなのでしょうか。","respondent":"小林施設整備課長","answer":"１階のバリアフリートイレにつきましては、今お話がございましたとおり、ユニバーサルベッドがあったり、オストメイトがあったり、いわゆる、今までは誰でもトイレと言われていたものが、今度名称を変えようというところでございまして、現在、バリアフリートイレですが。","id":"exchange-063"},{"speaker":"吉田委員","kind":"質問","question":"そうですね。多分、これがユニバーサルベッドですよね。そういうことについても、この図面の段階というよりも、もう少し工事が進んだ段階で、そういうことを想定されるような方たちの何人か、いろいろな方たちがいらっしゃるので、ご意見を聞いた上で固めていっていただけると、当事者にとっては大変いいトイレになると思うのですけれども、そういうことについて、もしご見解があったら伺いたいと思います。","respondent":"小林施設整備課長","answer":"ただ、東京都、あるいは国につきましても、よりよい配置の方法であったり、メーカーにつきましても、様々な声を聞いた上でのレイアウト案を示しているところでございまして、区としましても、そういったものを参考にしながら。","id":"exchange-064"},{"speaker":"吉田委員","kind":"質問・要望","question":"ぜひそのようにお願いします。当事者の方と一口に言っても、いろいろな方が、半身が不自由の方も、右が不自由な人と、左が不自由な人というのだとご要望が違ったりしますので、全てにというのはなかなか難しいと思いますけれども、できるだけそういう方たちの意見を取り入れていただけるように要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"須貝委員","kind":"質問・要望","question":"先ほども申し上げましたけれども、やはりこれからは避難場所にもなるということで、区有施設においては、地震想定を考えるならば、発電機を設置するようなそういう施設に、区有施設というのは持っていくべきだと私は思います。そういう施設が身近にあるということは、やはり非常に安心もされると思うので、その辺は今後、今日のこの件もそうですが、私は考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"}]},{"id":"topic-08","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"これはやはり２３区にすれば、様々ないろいろな事業をやらなければいけない中で、このようにしますよ、してあげていますよというのはいいのですけれども、何か非常にじくじたる思いというか、悔しいというか、本来ならこれだけ人口が増えて、これだけ建物が増えて、これだけタワーマンションをどんどん増やして、税収、固定資産税が上がる一方なのに、やはり下げないというのはいかがなものかと思うのですが。","respondent":"提坂税務課長","answer":"これはあくまでも地方税法という大本の法律があって、東京都については、東京都の独自性に基づいて、特別区は地価が高いとか、そういう状況を踏まえまして、毎年、経済状況を踏まえた上でこういう判断をしていて、毎年軽減措置を延長しているということを把握しています。","id":"exchange-067"},{"speaker":"須貝委員","kind":"質問","question":"区長職務代理者の方が今日いらっしゃるのですが、毎年言っていると思うのですけれども、全然対応が悪いというか、返事がないというか、相手にされないのでしょうか。分かる範囲で、よろしければ教えてください。","respondent":"桑村副区長","answer":"品川区としての方針がそうなのだとは、言い切れない部分があるのではないかと思います。","id":"exchange-068"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２番は平成１４年からということなので、２０年前から、３番が平成１７年前ということで、１７年前で、それぞれの年度から軽減がされているということなのですけれども、このときにはそれぞれどんな理由でこういう措置が取られたのかというのをお聞かせいただきたいのです。そこの、どんな経緯というか、理由で軽減措置が出されてきたのかというのをお聞かせいただきたいと思います。","respondent":"提坂税務課長","answer":"それぞれの制度を東京都のほうで取り入れるということで、かなり以前のものなので、詳細は、申し訳ないですが、把握していないところですけれども、その時点の経済状況とか、その辺を東京都のほうでよく斟酌した上で導入して現在に至っているということしか。","id":"exchange-069"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そこら辺の東京都の考えというのはどういう状況になっているのか。毎回こういう形で意見書を出さない限りは、これが継続されないものなのか。そこら辺の理由とか、東京都の考えだったりとか、あと、区のほうからも、このようなことを恒久的な制度としてできないかだったり、同じことを毎年出さなくてもよくなる道はないのかという思いがしているのですけれども、その点をお伺いします。","respondent":"提坂税務課長","answer":"先ほど申し上げましたけれども、大本は国のほうで定めている地方税法に基づいて課税させていただいているものなので、その都度その都度の経済状況を東京都のほうでよく判断して、毎年、軽減措置を延長しているということで。","id":"exchange-070"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところで言えば、さらにこれを拡大するとか、そういう方向というのも検討されてもいいのではないかと思うのですけれども、そういうことは２３区の課長会だったり、区長会だったり、そういうところで東京都に求めるみたいなことは、より厳しい状況になっていることに対して、そのようなものというのは特にないのでしょうか。","respondent":"提坂税務課長","answer":"特別区の税務課長会のレベルでは、請願が２３区全てに出ているわけではないということを聞いております。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に何十年と、３番にしてみれば１７年ですけれども、そういう形で続いているし、実際は、本当に区民の状況というのは決していい状況にはなっていないというのがここ（請願）でも訴えられているような状況ですので、私はぜひ区長会としてもそのようなことは求めていただきたいし、できれば、このような形で毎回訴えなくても制度化していただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"},{"speaker":"吉田委員","kind":"意見","question":"品川・生活者ネットワークとしても、本日結論を出すで、両方とも採択を主張します。そして、意見書は出すという方向で。一言意見を言わせていただくなら、本当に毎年こういう請願が出されておりますので、ぜひ恒常的な制度にしていただくということを、それが言えるのかどうか分からないのですけれども、そういう意見を前提として、採択で意見書を出すということにしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"}]},{"id":"topic-09","title":"令和４年陳情第５４号、小学生以上の未成年者に模擬投票権を付与することおよび当該投票結果の公表を実施することを求める陳情","agenda":"令和４年陳情第５４号、小学生以上の未成年者に模擬投票権を付与することおよび当該投票結果の公表を実施することを求める陳情","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういうことが本当に大事なのではないかと思います。もう９年経つわけですから、７年生であれば、その後選挙権ができているということになっていると思うのですけれども、そういうところにどう効果が出ているとか、この模擬選挙をされたことの評価ですとか、これからさらにこのように深めていくだったりとか、そういう方向だったりとか、そういうことがあれば教えていただけたらと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"今まで続けてきたこの出前模擬選挙の成果ですが、先ほど申し上げましたように、実施後のアンケート等を取っておりますと、１つは、今まで行ったことがなかったけれども、この選挙をやってみて、これからは選挙に行こうと思うという生徒が全体の７割を超えるような数字で。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういうことからすると、私は中学校も一、二校で、１回５年生のところでやればいいというのではなくて、毎回中学校でも取り組むという形で、意識づけをしていくのがすごく必要なのではないかと思うのですが、その点もどう考えられるか、伺えたらと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"選挙管理委員会と教育部門と連携しての主権者教育ですが、先ほど申し上げましたように、一応、これは教育カリキュラムに位置づけていただいて、授業の一環としてやっていただいていますので、教育委員会としても。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"本当にスウェーデンとかがこれだけ高い、選挙の投票率が必ず８割を超えているのです。そういうことからも、ぜひ中学校でも位置づけていただいて、選挙権を得る前から、自分は政治に主体的に関わっていくのだと、主権者なのだという、民主主義を学ぶだったり、そのようなところをしっかりと学校とも連携を取って、ぜひ進めていただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"},{"speaker":"吉田委員","kind":"質問・要望","question":"ただ、私自身も、これを読みながら、現在の実務上どうなのだろうか、これが可能なのだろうかと。基本的に公職選挙法の中で、投票人以外は入場してはいけないとか、それから、その中で別のものを配るのは難しいということも伺いましたけれども、一方で、公職選挙法上のあれは少し変わってきているのではないかと思うのです。その辺を確認させていただきたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"ただ、実際の模擬投票での入場となりますと、先ほど申し上げましたように、単独で未成年の方が行くというケースも増えると思いますが、それについてはやはり法で認めていない部分ですので、難しいかと。","id":"exchange-077"},{"speaker":"吉田委員","kind":"質問","question":"もう一歩踏み込んだものが必要かと思っています。これは基本、教育委員会が考えることなのですが、選挙管理委員会事務局としては、もう少し踏み込んだような連携のあり方を考えておられるのか、このまま継続すればいい、行う範囲を広げればいいというお考えなのか、その辺を改めて伺いたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"ですので、出前選挙の形をどうするかというよりも、もう少しフィールド、範囲を広げて何かできないかということは、まだ教育委員会と相談しながら進める余地はあるかと考えております。","id":"exchange-078"},{"speaker":"吉田委員","kind":"確認","question":"フィールドを広げてというのは、学校教育の範囲でフィールドを広げるという意味なのか、それとも別のところと連携して、一般の区民向けの投票率アップということを考えておられるのか、その辺を確認させていただけますか。","respondent":"鈴木選挙管理委員会事務局長","answer":"１つ何か新しいものをやって大きな効果が一度に出るというものではないので、そういう意味では、いろいろなことを取り組みながら継続することで、少しずつ向上していくのを目的としているというのが、選挙の啓発と考えておりますので、今後も引き続きいいご意見やご提案があれば。","id":"exchange-079"},{"speaker":"せらく委員","kind":"質問・要望","question":"２点質問させていただきたいと思いまして、私も小学１年生の子を持つ母なのですけれども、この陳情でいうと、小学生以上の児童ということで、１年生も含まれるということなのでしょうか、ということをお伺いしたいです。","respondent":"鈴木選挙管理委員会事務局長","answer":"例えば４年生以下のうちから主権者教育を実施するかということに関しては、教育委員会の所管なので、私のほうからはここでは何とも申し上げられませんが、機会があればやっていただくことは必要かと考えております。","id":"exchange-080"},{"speaker":"せらく委員","kind":"質問","question":"私の質問が分かりにくかったのかもしれないのですけれども、小学１年生からという質問は、今回の陳情にある「小学生以上の未成年者に」というところで、今回の陳情についての１年生から実施するのかどうかという質問でした。","respondent":"鈴木選挙管理委員会事務局長","answer":"この陳情の文章からはそれ以上の詳細が読み取れないのですが、素直に読めば、小学生から１８歳未満の子ども全員と読めますので、この陳情だけでは、それを何か特定の選挙のときにやるのか、毎回やるのかも不明なのですが。","id":"exchange-081"},{"speaker":"大倉委員","kind":"質問","question":"郵送すると、今言ったように、費用対効果の部分では大変なのだろうというのもあって、いろいろな課題も先ほどお話しいただいているのですが、その中で、両親とご家族と一緒に行った未成年が投票所に入れるのは、騒がないとか、そういういろいろなルールを守ったら入れるというところでいうと、こういう子どもたちも投票できますよみたいなものを別途つくるとかというのはできないのかと。","respondent":"鈴木選挙管理委員会事務局長","answer":"そうすると、当然、そのための対応の人員を用意したりとかというのが必要になって、そうすると、今度、本来の正規投票とは別のチームをつくって対応するということになれば、正規の投票の制約の多い中でやるよりは、別立てでやったほうが、同じ人材や資機材を使ってやる上では。","id":"exchange-082"},{"speaker":"須貝委員","kind":"意見","question":"今までお話を聞いていたのですが、確かにこういう案も、私は前向きな考え方でいいとは思うのですが、実際に模擬投票を可能にすることではなくて、やはり我々政治家なり、学校も今やってくださっているのですが、いかに政治に関心を持っていただけるように我々も活動しなくてはいけないし、教育は教育で学校でやっていただけるということはあるのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"湯澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。理由に関しましては、先ほどご説明があったように、法的な問題があることや、実務上の支障、それから模擬選挙を５年生や７年生に行っているというご説明があったかと思います。将来主権者になったときの投票率向上にもつながると思いますので、そういったことはこれからもしていくべきなのかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"つる副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。理由は、先ほど選挙管理委員会事務局長からご説明いただいたとおりの部分です。そうした媒体をいろいろ活用しながら、区政に関心を持っていただくという取組を行っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いしたいと思います。これそのものが実行に移せるとも思いませんし、移すべきだとは思ってはいませんが、大きなところで趣旨は賛同できるということで、趣旨採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。先ほど来いろいろご説明もありましたが、様々な、単独での未成年の入場ができない、事務の煩雑化、取り違いなど、正規の選挙に影響が出る可能性が大いにあるというところと、費用対効果も含めてなかなか難しいだろうというお話でしたので、不採択ということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-087"},{"speaker":"須貝委員","kind":"意見","question":"本日結論を出すということと、不採択でお願いいたします。区民の身近にいて話し合える本当の場にいる議員として、今後もやはり我々が投票率を上げる努力をすべきだと思いますので、そちらのほうをまずやっていきたいと私は考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-088"},{"speaker":"吉田委員","kind":"質問","question":"本日結論を出すということで、品川・生活者ネットワークとしても趣旨採択を主張したいと思います。いきなり陳情の要旨が模擬投票権となっておりますので、そうなると、先ほどの質疑を伺った限りでは、実務的には難しいとは理解しております。大きく投票率を上げるべきという趣旨については賛同できますので、趣旨採択にしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"せらく委員","kind":"質問","question":"理由としましては、低年齢の方から投票や政治に関心を持っていただくことはいいことだと思いますが、先ほど１年生からという質問をさせていただきましたが、いきなり低年齢、１年生の方から投票を始めるのではなく、現行でやっていただいている出前模擬投票をしっかり浸透させていきながら、そこから拡大をしていく方向のほうが取り入れやすいかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"}]},{"id":"topic-10","title":"令和４年請願第１２号、「消費税５％減税とインボイス（適格請求書）実施中止を求める意見書」を国へ提出を求める請願","agenda":"令和４年請願第１２号、「消費税５％減税とインボイス（適格請求書）実施中止を求める意見書」を国へ提出を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"いや、区民にどんな影響になっているかとか、そういうことに対して区がどう考えるかということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"国の制度によって、品川の中小業者の方々だったりとか、消費税が増税された影響だったりとか、コロナ禍の影響だったりとか、請願に書かれているように、円安、物価高とか、そのようなところで区にどのように影響されていて、それを区としてどう考えられているかとか、そのようなことというのは区のほうにも認識を伺いたいという思いはしているのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは影響のところではそういうところに影響が出るのだから、そういうことであれば、本来だったら区民委員会に（付託）すればよかったのかもしれないのですけれども、でも、総務委員会に付託されてしまったからには、それを審議するということになってくると思うので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"でも、そうそうたる部長がそろっているわけだから、そういうところはぜひ答えられる範囲でお聞かせいただきたいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"消費税の増税に加えてコロナの大打撃という状況になったのですけれども、そういう消費税１０％への増税とコロナ禍の影響が、区民、特に中小零細業者の方々とか、これからインボイス制度によって影響を受けるとされている、そういう区民の方々にどのような影響を与えていると区が認識されているのかというのを一つお聞かせいただきたいのと、それから、コロナで丸３年近くなるわけですけれども、そういう中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"インボイス制度がどのように影響を与えるかという。区民が消費税１０％の増税とコロナ禍で大変な状況に、苦境に立たされていると思うのです。そういう状況を区としてどう認識されているかということを伺っています。区民の実態。","respondent":"黒田財政課長","answer":"区の施策としまして、融資あっ旋でありますとか、プレミアム付商品券の発行でありますとか、また、ポイント還元、様々そういった状況を勘案して、補正予算として提案しておりますので、そういった苦しい状況にあると認識しておりますので。","id":"exchange-096"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"なかなかすごく聞きにくいのですけれども、そういうところで言えば、いろいろな区民の実態を総合的に把握されているところというのは、どこにもないのですか。総務委員会だと分からないですよね。分からないのかと思うのですけれども、そういうところで、区民の実態を総合的につかまれているというのは、どこの部署でつかまれているとかということはあるのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"産業、ものづくりは中小業者とか、そういうことだと思うのですけれども、そうではないところの区民全体がこういう制度をこのように使われていて、こんな実態になっているとかというのを丸ごとつかまれている部署というのはないのですかということを伺っています。","respondent":"黒田財政課長","answer":"様々、対応については、各所管のほうで対処すべき事象に応じては、補正予算を編成する中では、当然、財政部門でも、財源がどうであるかとか、どのぐらいの経費がかかるかというところを把握して、補正予算として提案は。","id":"exchange-098"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今日はそういうところをどう考えているかとかというのを聞くところはないわけですよね。ないのですよね。だから、そういう実態が全然浮き彫りにならないまま委員だけの討議で、本当だったら、ここ（総務委員会）でやるのだったら、そういうインボイスに関わるような理事者にも来てもらって、実態が把握できるようにすべきだったのではないですか。委員長と副委員長に伺いたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"だって、インボイスによって影響を受ける、シルバー人材センターとか何か、関わっている部署というのがあるわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"須貝委員","kind":"質問・要望","question":"コロナから円安が始まって、物価高騰で、それで、その中でインボイス制度が来年１０月から始まると。事務の煩雑さの面で、それを思います。現にインボイスも国の制度としてそのように法律で決まってしまっているわけですから、なかなか難しいと思いますが、インボイス制度の改善とか何かを行えば、また変わるのではないかと思うので、国への意見書提出を求めるこの請願については賛成いたします。以上です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"様々いろいろな声が上がることで、消費税の増税のときも延期されたときがあるではないですか。来年の３月までに登録する方は登録をするようにというスケジュールになっていると思うのですけれども、これを延期もさせ、延期をしている間に廃止をさせていくという方向にするためにも、ぜひ総務委員会でこの請願を採択をして、意見書を出していくということでしていきたいと思うのですが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"吉田委員","kind":"質問・要望","question":"消費税５％は、以前もこういうご意見の請願・陳情があって、生活者ネットワークとしては、消費税自体は広く薄く納税する一つの方法として必要な税制だと思っていますが、今の１０％は、そのときも申し上げたと思うのですが、本当に広く薄くですかと。１０％はかなり厚いのではないかと考えておりますので、この辺についても併せて意見書を提出するということには賛成したいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-103"},{"speaker":"湯澤委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。理由としましては、消費税を５％に引き下げるというところに関しましては、消費税は国を支える安定財源の一つであるということは認識しておりますし、税率についても、生活に直結する財源でありますので、これはぜひ消費税率の上げ下げ、それから軽減税率などに関しましても、国会でしっかりと審議をしていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-104"},{"speaker":"つる副委員長","kind":"質問・要望","question":"社会保障３経費とか、その辺を含めると、その１０兆円をどうやって財源として賄っていくのかというのが、請願頂いている中ではまだ分かりかねるところもありますし、ただ、インボイスについては税制度の維持のものだと理解をしているところでありますし、免税事業者になったから、インボイスを理由として、取引業者でも、現実として排除されるかどうかというのは、これはまだ来年のことですけれども、懸念。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-105"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"本日結論を出すで、採択でお願いしたいと思います。意見書を提出していくということでお願いしたいと思います。そういうところで、経済を回すためにはこれが一番有効だということで各国がやっているわけですから、今こそ消費税の５％への減税こそすべきだと思います。そういう点でも、インボイスは中止して、消費税５％への減税こそすべきだということで、ぜひ意見書を出していきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。消費税率についても、５％と数字が出てきていて、これは安定財源というところではしっかりと運営していく、また、いろいろな施策を打っていくためには、一定必要だというところは理解しています。その辺も含めて、しっかり国で議論をしていただくというのが重要だと思いますので、この請願については、不採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-107"},{"speaker":"須貝委員","kind":"意見","question":"私は、本日結論を出すということと、採択でお願いしたいと思います。この請願の理由は、もっともだと思います。先ほどから財源はどうなのだという消費税の問題はありますが、私はこうやって収入、所得の二極化がなった以上、一時的でもいいのですが、やはり所得の収入の多い人には税率を上げて、その方たちが社会に貢献するということを一時的にでもやるべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-108"},{"speaker":"吉田委員","kind":"質問","question":"意見書も提出したいと考えております。理由は、先ほども言いましたが、やはり消費税制度そのものは必要だと考えておりますが、今この状況で１０％というのは、とても広く薄いとは言えないと考えております。品川区内でも、中小の企業が大多数を占めると、今までご説明を受けておりますけれども、そこに影響があるということで言えば、これは品川区議会としても意見書を提出していきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-109"},{"speaker":"せらく委員","kind":"質問","question":"理由としましては、消費税５％減税については、こちら（請願）にも書かれているとおり、コロナ禍と円安、物価高、区民の家計は圧迫されていますので、こちらに対しては賛成の意見を持っておりますが、インボイス制度の廃止に対しては、フリーランスの方々や、売上げ１,０００万円以下の小売業者の方が消費税を課せられてしまうということで、守りたいという気持ちはあるのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982063?Template=document&Id=2246#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":77963,"voices":430}},{"id":"r04-20221101-6","meetingId":"r04-cm11","date":"2022年11月1日","dateIso":"2022-11-01","committee":"区民委員会","time":"午前１０時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件抜き出しています。","topics":[{"id":"topic-01","title":"第２２回、品川区中学生の主張大会","agenda":"第２２回、品川区中学生の主張大会","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"テーマは自由だということですけれども、何かそこに最近の傾向といったものが伺えるのでしょうか。そのことを１つお聞きしたいと思います。それから、これは中学生ということですけれども、小学生にも同様の機会はあっていいのではないかなと思ったりもしたのですが、実際に何かあるのでしょうか。そのことをお伺いしたいと思います。","respondent":"川島地域活動課長","answer":"小学生に対してですが、こちらは私どもの地区委員会連合会事業としては行っていないのですけれども、大井第一地区の地区委員会事業で「子どもの主張発表大会」という形で、地区委員会事業として、大井第一地区のほうでは、管内の小学生と中学生になりますけれども。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"どうもありがとうございました。私もできればこういうものを聞いてみたいなと思いました。自分自身の成長過程を振り返ってみたいなというものもあったもので、この機会に思いました。それで中学生だけではなくて、小学生もこういう機会があると、本当に自分自身の成長にとって役に立つのではないかなというふうに思いましたので伺いました。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"}]},{"id":"topic-02","title":"令和３年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和３年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"最初のスタート時点では非常に大ざっぱに言って８割前後あったのが、ＳＨＩＰ、産業支援交流施設だけ３割台にまで落ち込んで、ほかは６割前後なのが、３７.３％にまで落ち込んで、それから、令和３年度の戻りが、ほかは７割ぐらいにまで戻したのに、産業支援交流施設だけ４７.２％ということで５割にも到達してないというので、これはなぜなのかというところが気になった点で伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"昨日説明しました産業文化施設のほうですけれども、あちらも令和元年度、令和２年の３月からコロナの影響が出てきていますので、平成３０年度は以前もお示ししましたが９０％の稼働率だです。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問・要望","question":"分かりました。それから、その引いた額が令和２年度と令和３年度でそれほど増えているわけではないのだというようなご説明だったと思うのですが、それにしても、令和元年度から３年間見てみますと大ざっぱに言って少し増えているのかなというところが読んでいて気になりまして、この区の負担というのは、こういうふうに増えたら増えた分だけ支払うような仕組みになっているということなのでしょうか。","respondent":"遠藤商業・ものづくり課長、篠田文化観光課長、辻スポーツ推進課長","answer":"私どもの産業支援交流施設のほうの見方といいますか、少し分かりづらい部分がありますけれども。今回、コロナというような状況ですと、予測ができない形ですから、それを事業者のほうに全て負担させるというのは、それは非常に運営上難しいということで。令和元年度が、最後の３月のときが緊急事態宣言ということで閉めてしまった部分なので、ほぼほぼ例年並みとしますと。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"すみません。この管理運営委託料と利用料金の関係が、よく聞こえなかったせいもあってよく分からなかったのですが、利用料金を引くのですか、管理運営委託料から。申し訳ないです。もう一度すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"分かりました。とにかく青天井なのかなという気がしたもので、そういうふうにならないようにいろいろ工夫をしていっていただきたいと思います。要望として述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問","question":"施設がたくさんあるので幾つかあるのですけれども、まず区立の品川産業支援交流施設からお伺いしたいのですけれども、これは３階の収支差額のところを見ると、ここはコロナ禍であっても、基本的には黒字だったという理解でいいのでしょうか。お願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"３階の部分につきましては、令和３年度は最終的には２,８００万円の黒字という形になっているところです。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"分かりました。それと、支出のほうを拝見すると、令和３年度は少し上がっているというのは先ほどご説明があったから理解しました。だけれども、そんなにここの支出が、変化が３０万円余ですか。３０万円ぐらいしか令和元年と令和２年で４階の支出が変わっていない。これはどういう理由なのでしょうか。お願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"令和２年度のときに、完全に閉めたときも少しあったりしまして、そのような形で経費がかかると。歳入もどうなるか分からないというところがありまして、管理費を相当詰めて運営するということがありますので、結果として、ほぼとんとんか少し少なくなったというような状況です。","id":"exchange-008"},{"speaker":"松本委員","kind":"質問","question":"なぜこういうことを聞いたかといったら、アリーナの必要性のところでお伺いしたのですけれども、ご指摘のとおり、戸越体育館はそんなに観客席が多くない中で、８割程度ということは、まだまだフットサルにしろバスケットボールにしろ、プロスポーツは、日本の場合はそこまでサッカーのＪリーグとかに比べると観客数はそこまで入らないのだなということは理解しました。","respondent":"辻スポーツ推進課長","answer":"それを平均すると７５％弱ということになっておりますので、かなりばらつきがあるということで、全体の数字となっております。","id":"exchange-009"},{"speaker":"松本委員","kind":"質問・要望","question":"私が間違っていたのは、１日ではなくてコマでやられているということですね。この辺はいかがでしょうか。","respondent":"篠田文化観光課長","answer":"そういったことで、この１枚の中で全てはなかなか表現しきれないところもありますので、お話としては承りましたので、企画部門のほうにもそういった話を伝えていくようにはしたいと思いますけれども、なかなか簡単には、難しいのかなです。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"荏原平塚総合区民会館なのですけれども、特に総括と改善が必要とされた原因の分析および対応方針ということで、利用料金が大幅に減少しているということで、これはあらゆる機会を捉えて利用率の向上を図るということで、あえて記載をされているのですけれども、コロナが収まってくると同時に自然と回復してくる部分というのはあるとは思うのですが、ここをあえて書かれているというところで言うと。","respondent":"篠田文化観光課長","answer":"これは、昨年、一昨年は施設自体を閉めている期間がかなりございましたので、その辺の影響がどうしてもあったのですが、今年度は基本的に閉めてございませんから、そういった意味ではユーザーの方が。","id":"exchange-011"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"区民の皆様、お客様の意見があったのかその辺を教えていただきたい。もう１点、婚姻届を出す窓口なのですが、これもずっとこの委員会等で私は発言をさせていただいたのですが、民間の企業にお願いをして、お客様が来たときに寄り添っていろいろ教えてくださっていた方たちが、何か月前かでメンバーが変わったのではないかという気がしまして、変わっているのだったら変わっていると。","respondent":"吉野戸籍住民課長","answer":"それから２つ目なのですけれども、委託先ということなのですが、こちらのほうが今まで窓口と、それから郵送という形で２社でやっていたのですが、これを１社に変更いたしました。委託内容は一切変わっておりません。これは、例えばコロナとかそういった場合です。","id":"exchange-012"},{"speaker":"松本委員","kind":"質問","question":"こちら私も拝見いたしまして、すごくいいなというふうに思ったのですけれども、過去のしながわ写真ニュースとかを見ると、この１１月２２日にこういうのを渡していますよという告知とかが結構あったように思うのです。もしよければ、例えばＳＮＳとかでアップできればなと思うのですけれども、それはいつぐらいから行っていいものでしょうか。お願いします。","respondent":"吉野戸籍住民課長","answer":"事前にホームページとかＳＮＳのほうでは告知のほうをする予定でおりますので、今日この場でご報告させていただきましたので、ＳＮＳのほうは大丈夫です。なるべく早めにホームページのほうは告知いたしますので、よろしくお願いいたします。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/277018?Template=document&Id=2944#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":21465,"voices":59}},{"id":"r04-20221101-7","meetingId":"r04-cm11","date":"2022年11月1日","dateIso":"2022-11-01","committee":"厚生委員会","time":"午前１０時００分～午後 １時４４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","topics":[{"id":"topic-01","title":"令和３年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"令和３年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"そうしたコロナで、利用が減少したり、また収支のところでマイナス、赤字になっている事業所に対して支援策的な、区としてどう対応されているのか伺いたいです。それともう１つ、そうした大変な中なので、離職率を昨年も聞いているのですけれど、昨年はそれほどなかったといったお答えだったのですが、今年も変わりないのか、どういう状況なのか、お聞かせいただきたいと思います。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"２点目のクラスターの件数ですけれども、高齢者、障害者とも複数施設があります。３点目、離職率についてですが、障害者の部分につきましては、離職率はコロナ前とあまり変わりはないです。しかしながら、長引くコロナ禍において、例えば令和３年度については、従事者に対するＰＣＲ検査の実施や抗原検査キットを配布して、感染者の早期発見による感染拡大の防止や、重度化予防を図るとともに。","id":"exchange-001"},{"speaker":"石田委員","kind":"質問","question":"本当に大変な中ですので、区としての支援というところでは、たしか２年前ですか、介護や障害者福祉のサービス業務の継続支援金という形で、職員の方々のモチベーションアップということで、区が支えているという姿勢を見せていくということで、補正予算を組みましたということもあったと思うのです。","respondent":"松山障害者支援課長","answer":"今後、インフルエンザ等の感染症の流行がまた懸念されることから、区としても引き続き、各施設に対する支援をするとともに、区全体で、例えば高齢者、障害者の入所向けの相談窓口は東京都が設けておりますので、即応支援チームの活用であったり。","id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"支援を拒否する姿勢ではないので、そこはぜひ引き続き対策を考えていただきたいと思います。それと、ＰＣＲ検査ですけれど、現在の職員、働いている方への検査の頻度は、高齢者の介護施設では週１回というところも、以前はあったと思うのですが、障害者と高齢者の施設で今はどのようになっているのか、伺いたいのですが。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"施設のＰＣＲ検査の実施についてということですが、東京都のほうでＰＣＲ検査のスクリーニングをしているところで、週に１回各施設において従事職員の方が検体を出して、スクリーニングをしているところです。障害者施設につきましても同様に、ＰＣＲ検査、それから区のほうでも抗原検査キットを配布して、早期に発見できるように努めております。","id":"exchange-003"},{"speaker":"石田委員","kind":"確認","question":"障害者施設のご説明で、利用率は高いのに収支がマイナスになっているところ、そういう施設は他にもあるのですけれど、その仕組みというか、利用率は１００％とかあるのに、収支が差し引きマイナスになっているというのは、どうしてなのか伺いたいのと、心身障害者福祉会館ですが、たしか平成３０年に改めて心身障害者福祉会館の運営事業者が選定された時。","respondent":"松山障害者支援課長","answer":"１点目の、利用率が１００％であるのに、収支がマイナスになっているというところは、例えば４ページの福栄会のところを指していらっしゃると思いますが、生活介護は１００％ですけれども、就労継続支援Ｂ型は９４.８％です。","id":"exchange-004"},{"speaker":"石田委員","kind":"確認","question":"そうすると、これは年に１回やられているという感じなのか、その確認と、改めてこの会館の運営事業者選定のときに、医療的ケアの受入れというところもあったと思うのですけれど、それはこの総括シートにも書いてありますけれど、医療的ケアの必要な障害者の受け入れ態勢を整えているということなのですけれど、まだ始まっていないということなのですか。そこを伺いたいと思います。","respondent":"松山障害者支援課長","answer":"心身障害者福祉会館による事業所連絡会の開催については、年に１回です。２点目の医療的ケアが必要なご利用者については、本年の４月より受入れを行っております。","id":"exchange-005"},{"speaker":"石田委員","kind":"確認","question":"それと、ぐるっぽ、障害児者総合支援施設のところで、１０月に運営事業者が移行することになって、もう１か月たったという状況ですけれども、福栄会だけになるということなので、この総括シートでも、３事業者という形ではなくなって、１つにまとまった報告という形になるのか、今まではゆうゆうだったところ、グローだったところ、愛成会だったところ、というふうに事業で分かれていましたけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田委員","kind":"質問","question":"その指定管理が変わっていくというところでの、利用者への影響というのを伺いたいと思いますので、答えられる範囲で答えていただいていいでしょうか。","respondent":"松山障害者支援課長","answer":"２点目の利用者への影響ですけれども、指定管理者の変更に当たりまして、区と指定管理者、双方が共に協力しまして、利用者を取り巻く環境の変化に配慮しながら、引継ぎを丁寧に、段階的に行ってまいりました。","id":"exchange-007"},{"speaker":"石田委員","kind":"質問・要望","question":"ぐるっぽの運営事業者の変更に関しては、様々ご意見が寄せられまして、本当に人間らしく扱われたというところでの、事業者の継続を望む声が本当に多かったので、その入れ替わりのところがとても心配だというのもあったので、聞かせていただいたのですが。分かりました。引き続き私たちも現場の声を聞きながら、よりよい支援につながるように、引き続き意見させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ご説明ありがとうございました。それで、相談件数がありますが、これはもうかなりいろいろな相談、電話相談とかも含めてだと思うのですが、プランを作った相談の数、それをモニタリングで追ったりした数、それから障害児、そもそもお子さんの相談というのは非常に大事だと思うのですが、児童の相談は何件か、ということが分かれば教えていただきたいと思います。障害者支援関係、お願いします。","respondent":"松山障害者支援課長、菅野高齢者福祉課長","answer":"障害児者総合支援施設の相談の関係の実績です。全体では１万１,６１１件ですが、そのうち計画相談の件数は、大人のほうが３７７件、お子さんの計画相談は１３０件です。それから、担当職員は４人、あと補助の方が１人ついておられます。その中で施設ごとに、利用者のアンケートをしていただいたりとか、そういったことも取り入れてもらったりして、よりよいサービスを、施設のほうで利用者に還元していくことが、結果として、利用者に対する周知になるかなということで。","id":"exchange-009"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ですから、その辺のお話と、児童の相談が１３０件ということで、事業者が変わったので、それについてはまた、別の機会にお伺いしたいと思います。モニタリングについては、ソフト面でお知らせしているということですが、ここの施設はこういう感じで事業者が一生懸命やっているのだということも含めて、もう少し何らかの形で、分かりやすくお伝えする必要があると思うのですが、いかがでしょうか。","respondent":"菅野高齢者福祉課長、松山障害者支援課長","answer":"モニタリング評価の利用者への周知についてですけれども、モニタリング評価は全体的に区の方針としてやっている制度になりますので、全体的なことを考えつつ、今後利用者等にどういうふうに還元していくか、お知らせしていくか。一般相談にかかる時間がかなり長いため、あるいは困難ケースに対応するため、人材を確保して対応していただいております。","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"高齢者地域支援課の所管ですけれども、大井倉田わかくさ荘についての支出が、事業運営費ということでざっくりとしたことしか書いていなくて、他の施設は幾つかの分野に分かれて書いてあって、「評価の視点」別のコメントの、２．予算執行（財務）の視点では、「管理運営費については、管理人の人件費、維持管理費、修繕費に充て、計画通り」とあるので、それぞれの何とか費というのをここに記せば。","respondent":"川原高齢者地域支援課長","answer":"ご意見をありがとうございました。いただきましたご意見に関しまして改めて、その事業の内訳等を確認いたしまして、引き続き検証していきたいと思います。","id":"exchange-011"},{"speaker":"高橋（し）委員","kind":"質問","question":"ぜひよろしくお願いします。モニタリングで、委員会のほうでいろいろ質問をしますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問・要望","question":"私からは１点だけ。障害児者総合支援施設のゆうゆうのところで、改善が必要な事項で、「困難なケースが増加しており、関係機関と連携した専門的な対応が必要である」と。やはり、今後はオンラインを使って医師と連携していくのはとても大切だと思っていまして、そういったところが可能なのかどうか、教えてください。","respondent":"松山障害者支援課長","answer":"そのほかにも、福栄会のほうも実際に医師との連携を強化しようということで、やはり、ニーズの高い医療相談、専門職による相談というのは、今後も進めていく必要があると考えています。","id":"exchange-013"},{"speaker":"せお委員","kind":"質問・要望","question":"ケース会議とかも、医師が入るとまた新しい視点もあると思いますので、ぜひ積極的に、オンラインを活用してやっていただくというところも、取り入れていただきたいと要望いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"あくつ副委員長","kind":"質問","question":"１点だけ、高齢者地域支援課の八潮わかくさ荘のところで、字面だけで申し訳ないのですが、２ページのところ、改善が必要とされた原因の分析および対応方針、「ワーデン（管理人）１名の不在であり、長期間補充できていない」というところで、過去の議事録も見て、一昨年も同じような記載があり、職員の方が一生懸命回して、何とか乗り切ったというような表記があるのですけれども。","respondent":"川原高齢者地域支援課長","answer":"今年度もやはり同じような状況で、募集は外部に対して行っているのだけれども、成り手がいないという指定管理者からの回答をいただいております。よって、外部でなく内部の職員、施設長もしくは副施設長で夜間の見守り等、管理人業務を行っているという状況にあります。","id":"exchange-015"},{"speaker":"あくつ副委員長","kind":"意見","question":"ワーデンありきなのか、それとも職員でやれるのだったら職員でやっていくべきなのか、というところもあると思うので、そこについては、こうやっていこうかと改善点で出てきているので、区のほうも協力していただいて、苦情やクレームが上がったとか上がってないという話は載っていないのですけれども、そこについては安心して皆さんがお暮らしいただけるように、ぜひ、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"渡辺委員","kind":"質問・要望","question":"普及啓発のところで、何点か教えてください。この辺のところで、普及の啓発ですから、やはり意識を高めていただきたいという思いからすると、十数年前に受けた方がそのまま手つかずだと、そんなに意識が高いとは思えないのです。今ここまで何となく手がついた、次のステップ、こういう方に理解してほしいとか、そういう行動計画みたいな、ビジョンみたいなものがあるのかどうか。その２点をまずお願いします。","respondent":"川原高齢者地域支援課長","answer":"これらの方たちを対象に、今年度、認知症サポーターの企画会議という形で開催しまして、既にオレンジリングをお持ちでサポーターとなっている方が、今後地域への、特にそこは地域連携というところをポイントにして。","id":"exchange-017"},{"speaker":"渡辺委員","kind":"意見","question":"必要だけれども、広く浅く過ぎてしまって、てこ入れをどこかで、重点年度とか、重点期間とか、もちろんキャンペーンを打つのも、よりしてほしいという意味で言うのですが、告知にしても、先ほどの普及啓発もそうですが、予算も関わってくるにしても、少しインパクトが弱いのかなというイメージがあります。","respondent":"川原高齢者地域支援課長","answer":"今後におきましては何かしら、品川らしさというか、インパクトのある取組というところで、宣言も含めてどういった形で発信していけるかというところは、実際にサポーター企画会議の中で提案をさせていただいて、サポーターの方々の意見も聞きながら取り組んでいけるように。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問","question":"なので、この「もの忘れ検診」の継続性というのは、今どのように考えられているのか、分析されているのか伺いたいです。たしか、セルフチェックのできるチラシも作られているという答弁もあったと思うので、そうしたものもあるということを、この場を借りてではないですけれど、周知させていく、そうしたこともできるのではないかと思うのですけれども、いかがでしょうか。","respondent":"川原高齢者地域支援課長","answer":"委員のご質問で、３番の医療との連携、もの忘れ検診ですが、認知症専門医との検討委員会を１回開催いたしました。","id":"exchange-019"},{"speaker":"石田委員","kind":"提案","question":"もの忘れ検診は、９月も受診されているということでした。それと予防のところで、補聴器のことも提案させていただいたのですが、やはり認知症を早期に発見するということで様々な、かかりつけ医だったり周囲があると思うのですけれど、その最大の因子、認知症の因子となるのが難聴となっているので、そこも含めて早期発見にやはりつなげていけるのではないかと思うのです。引き続きよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"高橋（し）委員","kind":"質問","question":"認知症に関する様々な施策が、ここ数年で次々実施されて、大変、認知症の施策が充実してきていると思います。２０自治体ぐらいは制定して、東京都だと世田谷区が制定し、さらに推進していくと、こういった施策を整理して進めていく形になっていると思います。条例についてと、推進体といいますか、そういうものの設立というか、プロジェクトチームではないですけれど、ということに関して、いかがでしょうか。","respondent":"川原高齢者地域支援課長","answer":"現在も事業計画の中でも認知症の部分は施策として方針を掲げている中で、そこで具体的にどうしていくかというところは、きちんと文字に起こして、皆様に周知をしていきたいと考えております。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ありがとうございました。このように施策が次々に充実したもの、そして認知症予防について、さらなるいろいろなことを進められているので、ぜひ、今お話があった条例についての検討と、その進め方というのですか、せっかくいいことをやっているので、トータルで、総合的に共生しながら進めていけるといいかなと思いました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"あくつ副委員長","kind":"提案","question":"その頃は認知症は高齢者の中で１３％ぐらいだったのですけど、現在ではもう１７％ですか、随分増えてきているところなのですが。それで、子どものキッズサポーターなどもそのとき提案させていただいて、検討するとおっしゃっていたのですが、残念ながらそこはまだ進んでないのかなというところです。この実施件数と受診率の差、実施と受診というのはどう違うのか、教えていただきたいと思います。","respondent":"川原高齢者地域支援課長","answer":"こちらの表記の部分、分かりづらくて申し訳ありません。こちらは受診件数とイコールです。受診件数に対して受診率という形で出しております。","id":"exchange-023"},{"speaker":"あくつ副委員長","kind":"質問","question":"ごめんなさい。私の理解が悪くて申し訳ないです。受診率２.３％というのは、１１２件受診したという意味なのですか。","respondent":"川原高齢者地域支援課長","answer":"説明が不足しておりまして、申し訳ありません。こちら、７５歳になる区民で、実際に受診券を発送した方が、すみません、字が小さくて申し訳ありません、４,９６２人に発送しております。実施件数とこの送った受診券全体から割り出したのが受診率という形で、出しています。","id":"exchange-024"},{"speaker":"あくつ副委員長","kind":"質問","question":"実はもうやっている、実の部分ではやっているけれども、そういう意味も含めて、ここでまた条例を作ってくださいというのではなくて、品川区として、せっかく認知症サポート係というところで一つ大きく、重点実施事業をやっているわけですから、そこの部分で、先ほどもありましたけど、何かこう前向きなところをもう一つ、見せていただいたほうがいいのではないかと思うのですが。","respondent":"川原高齢者地域支援課長","answer":"ケアマネージャーなどの支援係と、ちょうど組織的にも席が、隣の課で近いこともありますので、引き続きそこの部分の連携もとりながら、認知症になっている方の対応、あとは早期発見への取組というところを連携して、実施していきたいと考えております。","id":"exchange-025"},{"speaker":"あくつ副委員長","kind":"意見","question":"非常に重たい話ではあるのですけど軽やかに、認知症の人が自分らしく生きられるというものを発信していく、蛭子さんが自分の体験とかマネジャーとの鼎談みたいなものもやって、そういうものも非常にいいなと思ったので、ご参考にしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"石田委員","kind":"確認","question":"１点だけ、確認し忘れたのですけれど。そうしたところでも、この大綱にもあるので、やはり地域包括支援センターは大事だと思うのですけれど、その機能強化という点で、認知症の早期発見・早期対応できる、そういう機能強化につながるものになっていくのかというのを、お聞きしたいのですが。","respondent":"川原高齢者地域支援課長","answer":"私どものところでの地域包括支援センターの機能強化事業ということで、理学療法士が地域づくり推進員となって、今後の地域包括支援センターや区と連携して、どういったところができるか、介護予防、認知症予防の構築をどのように実施していくかという。","id":"exchange-027"},{"speaker":"石田委員","kind":"質問","question":"そうすると、今、地域包括支援センターという名前でなく、在宅支援センターと呼ばれていますけれども、そこには保健師等が配置されていないけれども、認知症の早期発見・早期対応のところでは保健医療の対応が、相談体制としてはとても大事だということなので、そうすると、保健師なども配置されていくことになっていくのか、というのを伺いたいです。","respondent":"菅野高齢者福祉課長","answer":"地域包括支援センターの役割として、総合相談や高齢者の実態把握、介護予防のスクリーニングからケアマネジメントまでを実施しているわけですけれども、その機能については現在でも十分満たしておりまして、その中で、今、委員からご質問のありました認知症の相談等も。","id":"exchange-028"}]},{"id":"topic-03","title":"を、改めて聴取いたします。 初めに、(1)令和３年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"を、改めて聴取いたします。 初めに、(1)令和３年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"石田委員","kind":"質問","question":"人件費というのは、事業運営経費の中に入っているということですか。","respondent":"若生健康課長","answer":"人件費につきましては、この支出の事業運営経費の中に含まれてあります。","id":"exchange-029"},{"speaker":"石田委員","kind":"質問","question":"品川健康センターと荏原健康センター一括ですが、されている事業の中身というのは若干違うと思うのですけれど、今までも１枚にまとまっていましたか。違う健康センターを一括にまとめているので、どちらがどうだったのか分かりづらいかと思うのですけれど、これはなぜか教えてください。","respondent":"若生健康課長","answer":"こちらの健康センターにつきましては、品川と荏原と２つありますが、指定管理としては両施設一括でやっておりますので、こちらのモニタリングですとか評価についても一括して、両施設合わせた形でこれまでもやってきているです。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"意見","question":"利用料収入がこれだけあるのですけれども、この利用料収入の行き先というか、指定管理者にどれだけ入って、区のほうにはどれだけ、戻ってくるのか。そのルールを改めてご説明いただければと思います。","respondent":"若生健康課長","answer":"ちなみに令和３年度で申し上げますと、利用料収入は、約１億２,０００万円ですが、それに対しまして基準額を１億３,７００万円弱ぐらいに設定しておりまして、見込んだ収入基準額に到達しなかったということで、こちらは還元が生じなかったということで。","id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、令和２年度は利用料収入が少なかったので１億円程度の事業間流用をしたということで、監査委員のほうからも補正予算を組むべきであったというご意見をいただいたと記憶していますが、令和３年度は、通常は２億円ぐらい利用料収入があるのですけれど、元年度の額ですけれど、３年度はそれに満たなかったのですが、流用等は行われたのでしょうか。","respondent":"若生健康課長","answer":"令和３年度につきましては、当初予算の編成の段階で、既にコロナの状況がかなり見込まれたというところもございまして、令和２年度については流用という形で対処したところなのですけれど、そういったご指摘等々もあることも想定しまして。","id":"exchange-032"},{"speaker":"高橋（し）委員","kind":"質問","question":"３年度はコロナを見込んで、もともと指定管理料を約５,０００万円アップしたので流用は行わず、指定管理料の中で事業ができたということでよろしいでしょうか。","respondent":"若生健康課長","answer":"委員のご指摘のとおりです。","id":"exchange-033"}]},{"id":"topic-04","title":"新型コロナウイルス感染症に感染した被保険者等に係る傷病手当金の延長","agenda":"新型コロナウイルス感染症に感染した被保険者等に係る傷病手当金の延長","exchanges":[{"speaker":"石田委員","kind":"確認","question":"延長ということで、よかったと思うのですが。今、ご説明いただいた傷病手当金のほうでは、濃厚接触者は対象ではないということで、いいのですよね。確認で伺います。","respondent":"池田国保医療年金課長","answer":"これとは別に保護者の方が、学校が休校になった場合とか、保育園が休園になってお休みになった場合の補償というのも、今のところ、たしか１０月で終了と予定していたとは思いますけれども、延長の見込みで検討しているところだというふうに聞いてあります。","id":"exchange-034"},{"speaker":"石田委員","kind":"質問・要望","question":"休業手当は企業のほうがやるようになっているということですね。分かりました。やはりそういった企業側が、本社側がそういうことをなかなか出せないというところもあったりする場合、濃厚接触で仕事ができないとなれば収入の問題にもなってきますので、濃厚接触者もこうした対象にするように、国のほうにも求めていただきたいと思いますけれど、いかがでしょうか。","respondent":"池田国保医療年金課長","answer":"現在、コロナによってお休みされた方でお給料の出ない方には、傷病手当金ということで２３区でも各区で支給していますけれども、実際に濃厚接触者の方ということでは、もともとの趣旨と違ってまいりますので、現在のところ、国のほうに要望することについては。","id":"exchange-035"}]},{"id":"topic-05","title":"品川区における新型コロナウイルス感染症対策","agenda":"品川区における新型コロナウイルス感染症対策","exchanges":[{"speaker":"石田委員","kind":"質問","question":"新型コロナウイルス感染症対策についてということで、要はこの表の形式が全面的に変わったということですね。この分かりやすい形のものは残しつつ、今回の見直しの、限定された報告をプラスするという形には、ならないものなのでしょうか。","respondent":"坂野保健予防課長","answer":"今回の９月２６日からの変更ですけれども、全国一斉に行われているということで、省令の改正ですね。もとより発生届そのものが来ない形になりますので、もうそれを実際レベルでどうこうアレンジをして、というふうにはできない、ということだと思います。","id":"exchange-036"},{"speaker":"石田委員","kind":"質問","question":"そうなのですね。来る情報がまるで変わってしまったので、ここに載せる情報としても、今回の新しい形にならざるを得ないということなのですね。分かりました。それで、今後、インフルエンザとの同時流行が危惧されているもとで、品川区としてのそれに向けた対応をどう検討されているのか、伺いたいと思います。","respondent":"坂野保健予防課長","answer":"区としての対応ということですが、既に前回の委員会で報告しておりますように、東京都の事業を活用して、高齢者のインフルエンザの自己負担分の公費負担化というのは、既に広報もしています。","id":"exchange-037"},{"speaker":"石田委員","kind":"質問・要望","question":"本当に、３年近く続いているという状況で、だからこそ、今、第７波まで来ている中での、その間の教訓というものを生かすべきですし、死者を出さない、命を守り抜くという立場で対応していただきたいと思うので、今回、インフルエンザはワクチン接種が無料になりましたけれども、そうしたことも含めて、やはり、今まで続いているから同じというか、粛々と、とおっしゃられましたけれど。","respondent":"坂野保健予防課長","answer":"見通しということですけれども、大変高名な先生方がいろいろ、見通しと称するものを、いろいろなところで言っているわけですけれども、それぞれ全然違うということも、今までも高名な先生方の見通しというのもなかなか、当たったり、当たらなかったりという部分もありますので。","id":"exchange-038"},{"speaker":"石田委員","kind":"質問・要望","question":"毎日のようにまた通知、通知で、日々そこに対応されるというのは、本当にご苦労されているだろうと思いますけれども、命守るという立場で、早め早めに、区としての対策、検査して、隔離して、早期に治療に向かうというのが一番いいのですけれど、今もやっているそうした対応とともに、医療機関へのさらなる支援と、部は違いますけれど、福祉部のところにも、ケア労働にあたる皆さんへの支援というのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/831364?Template=document&Id=3644#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":48136,"voices":118}},{"id":"r04-20221101-8","meetingId":"r04-cm11","date":"2022年11月1日","dateIso":"2022-11-01","committee":"建設委員会","time":"午前１０時００分～午後 ３時１９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を87件抜き出しています。","topics":[{"id":"topic-01","title":"会議の運営上、予定表の順番を入れ替えまして、(3)（仮称）西大井三丁目防災広場の整備","agenda":"会議の運営上、予定表の順番を入れ替えまして、(3)（仮称）西大井三丁目防災広場の整備","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この整備について、住民の皆さんと意見交換をしながら進めてきたということなので、皆さんよくご存じなのかもしれませんが、工事着工に当たって説明など、住民の方にも周知をしていただきたいというふうに思いますので、よろしくお願いします。いかがでしょうか。","respondent":"大石木密整備推進課長","answer":"説明会の開催ですが、隣のグループホームと併せて計４回説明会を行ってきておりまして、１２月にも中旬を予定しているのですけれども、着工前の説明会をグループホームと併せて行う予定にしております。","id":"exchange-001"},{"speaker":"横山委員","kind":"確認","question":"すみません、基本的なことですけれども確認させていただければと思うのですが、このトイレスツール、かまどスツール、具体的にどのような形で使われていくのかというところと、防災パーゴラ、こちらも教えていただけたらと思います。","respondent":"大石木密整備推進課長","answer":"ご質問いただきましたトイレスツールですが、通常時はベンチのような１人がけの腰かけのものになっておりまして、災害時にこれが非常用のトイレに変わるという形になります。","id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"ですので、まず職員のほうで事前に確認していただけるのかどうか分からないですけれども、そうした事前のチェック、加えて研修ですとか実際に使っていただくということを、ほかの課とも連携して進めていっていただきたいというふうに要望したいのですが、一言お願いいたします。","respondent":"大石木密整備推進課長","answer":"委員ご指摘のとおり、通常時と使い方が変わると、実際に緊急時に使えるかどうかというところがやはり課題になってきますので、そちら、関係所管、公園課、防災課とも連携しながら、日常の管理だとかをしっかり行って周知徹底に努めていきたいと考えております。","id":"exchange-003"}]},{"id":"topic-02","title":"「品川区マンション管理適正化推進計画」（素案）について（パブリックコメントの実施）","agenda":"「品川区マンション管理適正化推進計画」（素案）について（パブリックコメントの実施）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"それで、今回、区としてはこの推進計画をつくっていくということで説明されておりますけれども、適正化の仕組みというのですか、実際にマンションの管理組合がこの仕組みを使おうとすると、どういった流れになっていくのか、その全体の流れをご説明いただきたいと思います。それと、今回、品川の指針のところで、国と都と違う部分はあるのかどうか、その違いを伺いたいと思います。","respondent":"竹田住宅課長","answer":"それで、その適合証を持って品川区のほうに申請していただくと、合致している場合は認定が受けられるというケースが一つと、もう一つのケースとしましては、書類を全てそろえて品川区のほうに直接お持ちいただいて。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"どういったマンションが対象になってくるのかというところですけれども、そこを伺いたいと思います。今回、素案が出されましたけれども、この作成に当たってはどういった、何か検討会とか作成委員会を設置して、外部の学者の方とかに入ってもらってご検討されたのか、どのように作成されたのか伺いたいと思います。","respondent":"竹田住宅課長","answer":"相当期間の考え方ですけれども、一律に、例えば４０年たったから、５０年たったから、このマンションは危険性が高まったとか、そういう年数で絞るのではなくて、それぞれのマンション、構造等も違いますので、そのマンションに合わせた老朽化の度合いを考えながら、必要に応じて。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"それで、この中身のところで、その実態把握をこの計画期間内に実施するということになっておりますが、その期間内というと５年以内だと思うのですが、まず初めに実態把握をして、それから対策というのをいろいろ手だてを打っていくということになるのではないかと思うのですが、そうすべきではないかと思うのですがいかがでしょうかというのと、区独自の基準を設定した理由を伺いたいと思います。","respondent":"竹田住宅課長","answer":"そういった点を捉えて、外部の方にご意見をいただく機会も検討していきたいと考えています。それから、実態把握ですが、こちら、区内のマンションの状況につきましては、平成２８年度に行っております。","id":"exchange-006"},{"speaker":"のだて委員","kind":"意見","question":"詳細に把握をされているということなので、そうするとマンションの数とかも分かるのではないかと思うのですが、対象になるマンションの数とか、この把握している内容を少しご説明いただけたらと思うのですけれど。","respondent":"竹田住宅課長","answer":"計画の素案のほうにも少し書かせていただいておりますが、区内のマンション数は約１,７００棟と推計しております。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問・要望","question":"平成２８年度には詳細につかんでいるということですから、それも踏まえながら、耐震の実態把握も、これを早めにやっていっていただいて、適切に手だてを打っていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"横山委員","kind":"確認","question":"この資料の概要版の２ページの、品川区独自の基準のところですけれども、こちらの地域連絡調整員の選任ですとか、防災マニュアルの作成または防災訓練の実施というところですが、こちらまだ、既に調整員がいらっしゃったり、また防災マニュアルであったり、防災訓練をやっていらっしゃるところもあるかとは思うのですけれども、まだそういったところに取り組んだことがないような。","respondent":"竹田住宅課長","answer":"ただ、認定されますと５年間は有効ですので、５年間は確実に実施していただく形になりますので、どういった形でご報告いただくかというのは今後の検討課題です。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"それに対して、区としてどういう形で、まずは小さい詳細なステップを踏まないと、なかなか独自で取り組むのが難しいのかなというふうに思うのですけれども、実際に既にマニュアルを作成していただいていたりですとか、調整員がいらっしゃるところというのは、助言であったり指導であったりということが比較的、区としても調整しやすいのかなと思ったのですが。","respondent":"竹田住宅課長","answer":"国の施策として住宅金融支援機構が提供する住宅ローンのフラット３５や、共有部分のリフォーム融資の金利の引下げや、管理組合が修繕積立金などの積立てをサポートする債券である、すまい・る債というのがあるのですが。","id":"exchange-010"},{"speaker":"横山委員","kind":"質問・要望","question":"ありがとうございました。次の質問に関係してくるのですけれども、新築マンションに対しては、こちらの件についてどのように周知、またはその計画がされている新築マンションに対して、区としてどのような確認・チェックや働きかけを行っていくことになっているのでしょうか。教えていただけたらと思います。","respondent":"竹田住宅課長、中村都市環境部長","answer":"デベロッパーとの関係ですが、今後、新築マンション等を様々、建設予定をお持ちだと思うので、そういった方々のご意見もお聞きしながら、周知あるいはこの計画を今後どのように見直すべきなのか。マンション管理士会との連携というところは今、住宅課長が説明したとおりですが、補足をしますと、マンション管理士会に区として期待することとしましては、まず東京都マンション管理士会、東京都全体の把握というところがありますので。","id":"exchange-011"},{"speaker":"横山委員","kind":"質問・要望","question":"新しいマンションの物件に関しては、様々、別の所管課のところで計画団体から区として情報収集できる機会があると思いますので、ぜひ品川区独自の認定基準を満たしていただいた上での、また建築計画ですとかを立てていただいたり、また、管理組合に働きかけていただくというところを協力していただいたりですとか、ご理解いただけるような形にできると理想的かなというふうに思いますので。","respondent":"竹田住宅課長","answer":"新しいマンションについての働きかけは、様々な形で、ぜひこちらの認定制度を受けていただけるように進めていきたいと考えております。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問","question":"そうしたときに、この３割というのはどういった方々、いわゆる、一番は未然に防ぐという大きな目的があるので、管理組合がなく計画もないといったところが一番危険をはらんでいるというか、そうしたところだと思うので、そこにもきちんと具体的に、そこが一番手が入らないとなかなか難しいかなというか、この事業自体というかこの認定が認定で終わってしまうというか、認定はされるのだけれども。","respondent":"竹田住宅課長","answer":"それで、３割を実施するのが１０年、１０年間で実施する、今回の計画が５年ということなので、その半分の２５０棟を当面の目標としました。ただ、５年が経過したときに、状況を見ながら、また目標の変更は考えていきたいと考えております。","id":"exchange-013"},{"speaker":"こんの委員","kind":"質問","question":"これまでのそうした事業があって、なおかつそれをさらに、そうした事業の成果なり実績が認定されるというものに反映していくと思われるので、そこら辺のアドバイザーだったり相談窓口だったりというところが、今までと同じような形でいいのかな、そこに課題はなかったのかな、こんなことも考えるのですけれども、それはいかがでしょうか。","respondent":"竹田住宅課長","answer":"２３区の中で、今年の４月から先行して実施している区があるのですけれども、そちらでは残念ながらまだ、認定を受けたのは１件というふうに聞いておりますので、この周知というのも大きな課題ですので、制度を周知しながら、さらに全てのマンションに働きかけを行って。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問","question":"周知というところもいろいろな方法があって、セミナーをします、講座を開きますというところですが、具体的に、課題を抱えているマンションがどれぐらいあるのかとか、マンションの実態がどうで管理組合の実態がどういうふうになっているのかというところの把握をぜひ、区が押さえつつ、やはり周知の方法というところも個別に変わってくる、いわゆる周知といったら紙ベースでとか、ホームページでとか。","respondent":"竹田住宅課長","answer":"委員がおっしゃるとおり、実態の把握というのは大変重要と考えておりますので、この計画の期間内に詳細な調査のほうを行って、有効な施策を立てていきたいと考えています。","id":"exchange-015"},{"speaker":"こんの委員","kind":"質問・要望","question":"始まったばかりというかこれから始めるものなので、手探り状態というところもあるかと思いますけれども、ぜひ、この計画が実効性のあるものになるように、私もまちのいろいろな情報などをお伝えしながら、また、マンションの方々に寄り添う、そうした計画となりますように期待をしておりますので、よろしくお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"大体それが幾つぐらいあるのかというのと、住民の方から、やはり老朽化していてエレベーターの設置ができないという状況もあると思うのですが、そういった方たちに対しての、区営住宅に住まれている方々に対しての対応というか、どういった形でお知らせしているのかちょっと伺いたいと……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"大丈夫です。では、マンションのほうでちょっと質問をします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"このマンションの防災訓練とか、防災マニュアルを作成する際には、管轄の消防署や消防団との連携も図っていってはどうかと思うのですけれどもいかがでしょうか、ご意見を伺いたいと思います。先ほどメリットをお聞きしました。こうした中で、一応分譲マンションのみということであったので、ぜひ全てのマンションを、また、区営、都営を含めて全てやっていただければと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"そちらの経費は特にかからないというふうに聞いてあります。助成制度についても防災課でやっておりますので、防災課のほうからのご案内になろうかと思います。消防署や消防団との連携につきましても、防災課の観点のほうから進めていくのが適当かと考えています。","id":"exchange-019"},{"speaker":"松永委員","kind":"質問","question":"改めてですが、先ほどの質問の中で、申請の方法ですけど、これはマンション管理、オンラインでやるのと紙ベースということですが、もう書式というのは出来上がっていて、どういった形で、取りに行けばいいのか、それともコピーして、プリントアウトすればいいのか、ちょっとその方法だけ教えていただければと思います。入手方法です。","respondent":"竹田住宅課長","answer":"実際の申請書のほうは、国から標準的なものが示されておりますが、まだ区として確定してございませんので、確定次第、入手しやすいような方法、例えばホームページからダウンロードできるとか。","id":"exchange-020"},{"speaker":"芹澤委員","kind":"確認","question":"すみません、何点かお伺いします。区分所有して、そこから賃貸で貸しているというような方もいらっしゃるのかなと思うのですが、それも含まないということでいいのかの確認をしたいと思います。地域連絡調整員の選任ということで、これ実際には誰と誰の連絡を調整するということなのか、そこの業務の確認をもう一度すみません、お願いします。","respondent":"竹田住宅課長","answer":"区分所有の方が投資目的でほかに賃貸しているマンションのケースについては対象としてまいりますが、具体的にどういうふうに把握していくかというのは今後検討していきたいと思います。","id":"exchange-021"},{"speaker":"芹澤委員","kind":"確認","question":"すみませんもう一度、ちょっと聞き取れなかったので確認ですが、そうすると賃貸も含んで、１棟丸ごと持っている人か、区分で持っている人かで分けているので、区分で持っているのであれば賃貸になろうが自分が住んでいようが、関わらずこの指針の範囲に入ってくるということでよろしいのでしょうか。","respondent":"竹田住宅課長","answer":"区分で持っているものは今回の対象です。","id":"exchange-022"},{"speaker":"西村副委員長","kind":"質問","question":"この素案のところに助言・指導および勧告というところがありまして、伺いたいのですが、認定を受ける際にマンション管理士の方などの支援も見込めるのかなと思っているのですけれども、もし非認定の結果が出たり採点が低かった場合に、何かこう、どういうふうにしていくのかというところを少し伺えればなと思いまして、助言・指導、勧告を行うというふうにあるのですが。","respondent":"竹田住宅課長","answer":"申請していただいたにもかかわらず、残念ながら認定を受けられなかったというケースが発生した場合には、どこの部分がどのように満たしていなかったのかということを詳細に管理組合の方にご説明して、可能なものであればそこを改善していただいて。","id":"exchange-023"},{"speaker":"横山委員","kind":"質問・要望","question":"こんの委員の先ほどの質疑を聞いていまして、１点ちょっとお伺いしたいなと思ったことがあるのですけれども、品川区独自の基準を、これからいろいろ設定したりですとか、どういった形で目に見えるように分かりやすい手法を取っていくかということもこれから検討される段階かと思いますので、ただ一つちょっと、認定の第１号みたいな形ですとか、２０２３年みたいな形ですとか。","respondent":"竹田住宅課長","answer":"先ほど、ほかの区の例をちょっと挙げてご説明させていただきましたが、その区の認定が１件成立したときは、国のほうからマスコミに対して、１号が認定されましたということでプレス発表をしたというような状況です。","id":"exchange-024"},{"speaker":"横山委員","kind":"質問・要望","question":"マスコミ等で発表していただくというのもすごく効果的だと思いますので、ぜひ進めていただきたいと思うのですけれども、それと同時に、例えば分譲マンションを一度買われた方が賃貸に出す、もしくはまた別の方に、ちょっと事情があって品川区の別のところに引っ越したりする際に、例えば内覧のときに、新しく購入される方がそういったことが分かるように、やはり。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"質疑の中でもいろいろ皆さんから質問が出されて、分からないところもあったと思うので、これは、一般の方がすぐこのパブリックコメントを出すというのはなかなか難しいと思うので、このパブリックコメントに向けての説明会というのが必要だと思うのですけれども、ぜひこれを実施していただきたいと思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"パブリックコメントは１２月１１日からスタートですが、１２月１１日号の広報しながわに内容のご説明を掲載予定です。ホームページ等でも周知してまいりますので、関係団体等にも可能な限り周知して、様々なご意見をいただけるように努めてまいりたいと考えております。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"広報とホームページで公表するということですが、やはりこうした原文を見てもいろいろ疑問が出てくるわけですから、そこはしっかりと意見を出してもらうために、説明会を実施することを強く要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]},{"id":"topic-03","title":"令和３年度指定管理者による管理に対するモニタリング・評価","agenda":"令和３年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"総括シートの区営住宅、区民住宅のほうからお伺いしたいと思います。評価の視点というところの２番目、予算執行の視点というところをお聞きしたいと思いますけれども、施設・設備の点検、それから、建物管理というところですが、この委託されている宅建から、区営住宅で特に老朽化が進んでいるところが何件かある、また、老朽化とともにバリアフリー化されていない建物も散見される。","respondent":"竹田住宅課長","answer":"ただ、指定管理者によりまして日々チェックしておりまして、今後、問題が発生しそうなところをご指摘、ご連絡いただいて、速やかに、事故の起こらないように点検、修繕を実施しています。","id":"exchange-028"},{"speaker":"こんの委員","kind":"質問・要望","question":"こちらはある程度の使用料を払ってのことですけれども、一方で、やはり区営住宅も、区民の方が住む、良質な住宅を提供していただきたいので、これは言葉が入っている、入っていないという単純な問題なのかもしれないですが、ぜひ、区営住宅についてもやはり良質な住宅を提供するために、今申し上げた、抜本的に修繕をしなければいけないところは早く修繕をして、そうした住宅を提供していただきたい。","respondent":"竹田住宅課長","answer":"こちらの設置目的のところですが、もし、読む方によってそういう印象を受けられるような方がいらっしゃるようでしたらば、今後は表現の仕方についてさらに検討していきたいと考えております。","id":"exchange-029"},{"speaker":"こんの委員","kind":"質問・要望","question":"今、最後に言ってくださった、読み手のことを考えて、まさにそういうふうにちょっと見えてしまいました。要望ですけれども、抜本的修繕をされる、この区営住宅については、ぜひエレベーター設置も検討して、そうした抜本修繕を今後お願いしたいという要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、それがどういった事業者なのかというところを伺いたいと思います。併せて、ファミーユ西五反田のほうも伺います。賃金が最低賃金になっていないかどうか、やはり区が指定管理をお願いしているところで、そうした最低賃金のラインの給与ではいけないというふうに思うのですが、いかがでしょうか。","respondent":"竹田住宅課長","answer":"そういった点を中心に、区内の事業者さんに再委託のほうをお願いしています。それから、緊急対応が極力発生しないように、日頃から保守点検を進めていきたいと考えております。","id":"exchange-031"},{"speaker":"のだて委員","kind":"質問・要望","question":"それと、収納率のインセンティブは何％だと、収納率が何％だと何％上乗せというのがあると思うのですが、それをちょっと一例、ご説明していただけたらというふうに思います。職員のほうは今、資料がないということですが、やはりそうしたところも含めて評価、チェックをしていくということが必要だと思いますので、そこはしっかりつかんでいただいて、説明できるようにしていただきたいというふうに思います。","respondent":"竹田住宅課長","answer":"それ以外に、先ほど申し上げました、空き室のあっ旋をした分が、令和３年度は１８件ございまして、この分として２４０万８,７００円をお支払いしておりますので、合計してこの金額をお支払いしています。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"この収支が増えている理由をお伺いしたのですが、今のは委託料の額のご説明だったのかなという気がするのですけれども、そこのところをもう一度改めてご説明いただけますか。","respondent":"竹田住宅課長","answer":"逆に、空き室のほうが、令和２年は９件で１２７万４,０００円、それから、令和元年度は７件で１０２万円、お支払いしておりますので、都合、こちらの表では、令和元年度、令和２年度ともにプラスという表記になってあります。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"その収支のところは分かりました。先ほどの職員の関係は情報を持ってないということですが、やはり、そういった情報も含めてこの総括シートに載せていただければ分かると、こういったことも起こりませんので、こうしたシートの情報の充実を抜本的に強化していただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"横山委員","kind":"質問・要望","question":"質問に入るのですけれども、こちらの３番、サービス向上および業務改善の視点というところで、「本人の了解を得て単身高齢者世帯の緊急連絡先を収集し、緊急時対応や日常問題のケア等を円滑に行える体制を構築している」というふうにあるのですが、こちらどのような体制を構築しているのかというところを具体的に教えていただきたいというふうに思います。","respondent":"竹田住宅課長","answer":"それで、入居するときには連帯保証人を必ず出していただいているのですけれども、連帯保証人の方もご高齢になられましてお亡くなりになっているという方も、そういうケースもありますので、いざというときになかなか。","id":"exchange-035"},{"speaker":"横山委員","kind":"意見","question":"体制を整えている背景というか、目的というところを今ご説明いただいたのかなというふうに思いました。こちらの、特にその日常問題のケアなどを行える体制を構築しているということですけれども、具体的にどういった体制を構築されているのかという、体制についてのご説明をお願いできたらと思います。","respondent":"竹田住宅課長","answer":"そういった方には、その方と十分コミュニケーションを取りながら、火災等や事故が発生する前に、お独り暮らし、かなり難しくなっていますよね、というようなお声かけをしながら、施設の入居を検討していただくというのも入居者管理の一つだと考えておりますので。","id":"exchange-036"},{"speaker":"横山委員","kind":"確認","question":"体制のご説明ありがとうございました。そうした専門家の方々の意見だったり相談だったりを受け入れられるような体制というのは、今どういうふうになっているのかというところを確認させてください。次に移るのですけれども、こちらの区営住宅と、区民住宅それぞれの、もし分かりましたら、ひとり親家庭の入居率というのがどのくらいなのか教えてください。","respondent":"竹田住宅課長","answer":"専門家の連携ですが、その方のご事情に応じて対応しているというところですが、例えば、最近あった事例ですと、異臭がするというふうに入居者の方がおっしゃるのですけれども、客観的に指定管理者の方が確認しても異臭がしない、区の職員が行っても特にしないということで。","id":"exchange-037"},{"speaker":"横山委員","kind":"確認","question":"ちょっと別の機会に、入居率が分かりましたら教えていただけるとうれしいなと考えていますので、今日は大丈夫ですのでよろしくお願いいたします。最後に、こちらのファミーユのほうですけれども、こちらの３番の２つ目の丸です。こちらの入居者間のコミュニティ形成支援というところですけれども、具体的にどのように行っているのか確認させてください。","respondent":"竹田住宅課長","answer":"コロナ禍で、なかなか積極的なことが今まではちょっと、ここ数年できなかったのですけれども、大分収まってまいりましたので、今後は、顔の見える関係づくりを、町会・自治会に対してご協力していきたいと考えております。","id":"exchange-038"},{"speaker":"横山委員","kind":"質問・要望","question":"区民住宅、区営住宅におけるどういったコミュニティの在り方というのが品川区において最善なのかということは、私も研究を進めていきたいというふうに思っているところですけれども、例えばですが、コミュニティマネージャーみたいな、中間の支援ができる専門の方と指定管理者との意見交換の場ですとか、月１回でしょうか、そうした会議の場で、専門家の相談であったり。","respondent":"竹田住宅課長","answer":"その新しい指定管理者の選定を行っているところで、選定をしますということは、もう委員会ではご報告させていただいたところですが、その中の提案の中で、例えばコロナも落ち着いてきましたので、マルシェという感じでイベントを指定管理者の主催の下。","id":"exchange-039"},{"speaker":"松永委員","kind":"質問","question":"私からは、先ほどちょっとお話ししたのですが、区営住宅の老朽化が進む中で、住民の方も高齢化が進んでおりまして、エレベーターが設置されていないところは大変苦労されていると聞いております。そこで、区営住宅について、このエレベーターを設置するのは困難とも伺っております。そうした方々に対しての対応というのはどのようにされているのかお知らせください。","respondent":"竹田住宅課長","answer":"区営住宅のほうは１３住宅あるのですけれども、そのうち５階建てが１１住宅で、１１住宅のうちエレベーターが設置されているのが７住宅で、残り４住宅がエレベーターが設置されていないという状況です。","id":"exchange-040"},{"speaker":"松永委員","kind":"意見","question":"ぜひ対応をお願いしたいと思います。先ほどこんの委員からもありましたが、改めて区営住宅の建て直しの際は、ぜひエレベーターの設置と、区営住宅になかなか入れないという方もいらっしゃるので、ぜひ部屋数も含めた形で増やすという検討をしていただければと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"}]},{"id":"topic-04","title":"ざいましたので、ご案内いたします。 以降は、防災まちづくり部が所管する議題となりますので、よろしくお願いいたします。 それでは、引き続き","agenda":"ざいましたので、ご案内いたします。 以降は、防災まちづくり部が所管する議題となりますので、よろしくお願いいたします。 それでは、引き続き","exchanges":[{"speaker":"こんの委員","kind":"質問・要望","question":"ご説明ありがとうございました。私からまず１点目が、指定管理業務の概要のところからお伺いしたいと思います。むしろ建屋になっている２階建て、３階建ての駐輪場、こちらの施設の建物の維持管理、こうしたところの業務はどうなっているのか、この２点をまずお願いします。","respondent":"工藤交通安全担当課長","answer":"２点目、（５）の維持管理の部分ですけれども、建屋の部分ですが、こちらのほうも、その古くなった部分等をしっかり見ながら、毎年計画的に、この部分、この駐車場、修復をするといったことで維持管理を徹底しています。","id":"exchange-042"},{"speaker":"こんの委員","kind":"質問・要望","question":"具体的な場所で申し上げると、私も議会で何度かお声を上げしていますけれども、この稼働率が低いといった点を適正な利用に推進していただきたい課題と思っているところが、一つは、大井町の仮称猫公園と言われているところの建屋の駐輪場、やはり２階、３階になると、どうしても稼働率が低くなっていく。屋根がないので３階に止めたくても止められない。","respondent":"工藤交通安全担当課長","answer":"ただ、そのままということではございませんで、定期利用で空いているスペース、特に西大井の屋上は空きがあるのですけれども、そちらに対して、当日利用を誘導したりというようなことも現在やっておりますので、引き続き柔軟な運用を続けて、少しでも利用率。","id":"exchange-043"},{"speaker":"こんの委員","kind":"質問","question":"ああいう屋根という形にはできないのか。その辺の構造上の問題もあると思うのですが、大森駅のような屋根に対して、ここはどのようにできるのかを教えてください。ここの数字、例えば令和３年、８７.５％の利用がされて、一方で放置自転車との関係はどれぐらいなのか。放置自転車がより多い場所というのはどこが多いところなのか、比較的多いところなのか、ちょっと現状を教えてください。","respondent":"工藤交通安全担当課長","answer":"大森駐輪場につけてあるような屋根が可能かどうかという点ですけれども、こちらについては、指定管理者のほうと少し検討をさせていただきたいと思います。","id":"exchange-044"},{"speaker":"こんの委員","kind":"質問","question":"分かりました。やはりこの放置自転車をさせないと、それを防止するための駐輪場というところも必要だなと思いますので、その点ぜひお願いしたいというふうに思います。先ほどの稼働率が低いというところにも、この放置自転車を防止するために促していくためにも、建屋のところなどは、やはり稼働率を上げていくための方策というのが必要だなというふうに思っておりますので、最後その点いかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"ただ、やはり駅から遠い、もしくは不便なところにあるといったところもありますので、そこら辺は適宜、指定管理者と情報共有しながらやっていきたいと考えています。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問","question":"それで、毎月、全ての場長を集めて会議をしているということで、この会議の場ではどういった内容が話し合われているのか、そこを伺いたいのと、場長は何人いるのかも含めて伺いたいと思います。ＩＣカードの端末を導入されたということで、今、大井町駅東口のところに導入したということで、今その１か所だけなのかどうか、その導入状況も伺えればと思います。","respondent":"工藤交通安全担当課長","answer":"こちらについては、現在、３つの駅で稼働しているような状況です。大森駅水神口駐輪場、それと大井町東口の駐輪場、最後に、３か所間違いなく稼働しているのですけれども、ちょっと１か所すみません。","id":"exchange-046"},{"speaker":"のだて委員","kind":"質問","question":"そうです。それがどれだけあったのかというところを伺ったので、そのご答弁をいただけたらと思います。やはり区として、自治体が委託をしているところで働いている方がそういう低い状況になっているということは、よくないというふうに思いますので、そこは改善していくことが必要ではないかというふうに考えるのですけれども、いかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"最低賃金の関係ですけれども、法にのっとってそれ以下にならないように、当方、区のほうとしてもやらせていただいていますので、引き続き、この法にのっとった形でやらせていただければと考えています。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問・要望","question":"コロナの返還のところは、その前の年ですか、令和２年度は２,１１２人いらっしゃったということなので、昨年度は少し、少ない状況なのだなというところでちょっと、思ったというか感想だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"松永委員","kind":"確認","question":"すみません、ちょっと繰り返しになるか分かりませんが、この自転車等駐車場の使用料の徴収に関することですけれども、その駐輪場に自転車を止めてそのまま放置されているものというのは、先ほど、７５％返したということでしょうか、そのまま撤去されたのは１,４１６台ということでよろしいのか、確認です。","respondent":"工藤交通安全担当課長","answer":"返還の関係です。委員ご指摘のとおり、先ほどご説明させていただいたとおり、長期間そこに置かれていた自転車も含めた撤去台数ということになります。併せて返還数についても同様の捉え方でよろしいかと思います。","id":"exchange-049"},{"speaker":"横山委員","kind":"質問","question":"幾つか伺ってまいりたいと考えています。機械式の駐輪場ですとか平置きの駐輪場があるかと思うのですけれども、具体的には大森駅水神口のところですが、こちらの利用者の状況ですとか、自転車の型式といいますか、どういった利用状況になっているかということを指定管理者の方から意見であったり、今後こうしていったほうがいいですとか、何かそういうものがありましたらお聞かせいただけたらと思います。","respondent":"工藤交通安全担当課長","answer":"機械式の駐輪場については、基本的には、チャイルドシートのついていないもので定期利用の方が対象となっておりますけれども、現状、チャイルドシートを設置した方が増えている中で、ではどうしようかというところで、機械式の駐輪場についても、チャイルドシートの幅。","id":"exchange-050"},{"speaker":"横山委員","kind":"質問・要望","question":"ただ今後、人口の推計ですとか、そのエリアのどういった方がお使いになられるのかというところを考えたときに、やはり今もう既に検討していただているところですけれども、チャイルドシートつきの幅のものに対応できるように、そういったものの収容ができるような定期利用というのをぜひ拡張していただきたいというふうに思っておりますので、要望させていただきたいと思うのですが一言お願いいたします。","respondent":"工藤交通安全担当課長","answer":"大森駅前につきましては、指定管理者共々、情報共有、現場の状況、ニーズ等、確認をしながら、それに対応した形で検討していきたいと考えています。","id":"exchange-051"},{"speaker":"横山委員","kind":"質問","question":"かなり使われている方が増えていらっしゃるのではないかなと思うのですけれども、ちょっとその辺り、ポート数が今８８か所、令和４年４月１日の時点でラックが７６１ラックということですが、そのシェアサイクルとの比較からの、指定管理者からもそういった意見が出ているのか、その辺り、どういった会議の場でどのような話がされているのか、もし分かりましたら教えてください。","respondent":"工藤交通安全担当課長","answer":"併せて、シェアサイクルのポートを増設すべく、いろいろなところで情報発信もしくはそういった話をさせていただいているので、それに対応できる場所、事業者なりが現れれば、どんどん増えていくかと思いますので、またそれは協力しながらやっていきたいと考えています。","id":"exchange-052"},{"speaker":"横山委員","kind":"質問","question":"私がちょっとお聞きしたかったところは、すみません、私の質問がシンプルにできなかったので申し訳なかったのですけれども、指定管理者に放置自転車等の管理等をしていただいているかと思うのですが、例えば区営の駐輪場と民営のバランス、あとは定期利用と当日利用のバランスみたいなものを調整していただいて、台数の管理ですとか、どんなふうにやっていくのかということを日々、ご検討いただいたりとか。","respondent":"溝口土木管理課長","answer":"一方でやはり、自転車の定期利用とか、駅前の放置自転車がなかなか減らない、そういったところもありますので、同じ課でやっておりますので、それぞれのところで情報の共有を図りながら、今後も適正な駐輪場の利用、または自転車の利用、そういったものを含めて。","id":"exchange-053"},{"speaker":"横山委員","kind":"確認","question":"ありがとうございました。こちらはどういった頻度でバランスの調整を行っているのでしょうか。どういった方針でコントロールしていくのか、何か方針等があるのかということと、４月というタイミング、その前にその１年の傾向みたいなものが話し合われているといいのかなというふうに思っているのですけれども、その辺りの具体的なところ、現状を教えてください。","respondent":"工藤交通安全担当課長","answer":"４月までにどういうような方針でやるのかというのが決定されればというお話だったかと思うのですけれども、指定管理者のほうと、具体的にはまだそういった、いつまでにこういうふうに決めるというような状況ではないのですが。","id":"exchange-054"},{"speaker":"横山委員","kind":"質問・要望","question":"必要なときに話合いの場を持っていただいているというふうに理解したのですけれども、やはり４月というタイミングで、様々皆さん職場が変わったり、特に定期利用の方の利用状況が大きく変わってまいりますので、その辺り、ちょうど４月の前のタイミング等で、なかなか見込みを立てるというのも難しいところがあると思うのですが、その地域でのシェアサイクルのポートをどうやって増やしていくのかですとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"}]},{"id":"topic-05","title":"立会川緑道整備工事（２工区）","agenda":"立会川緑道整備工事（２工区）","exchanges":[{"speaker":"こんの委員","kind":"質問","question":"参考までにお伺いしたいと思います。この工事の工区、いわゆる工事実施の順番を参考までにお聞きしたいのですが、１工区、２工区、３工区という工区になっていて、令和元年度から１工区が始まっているのですが、この２工区が最後になった、こういうのは順番に工事が行われるのではないかと思うのですけれども、この順番が違うというか、その辺を参考までに教えてください。","respondent":"森道路課長","answer":"今回の５５０メートルを４工区に分けて、この第１工区につきましては、当時昼間に、こちらで少したむろされてお酒を飲んだりというような方がおられたというところで、まずはこの１工区について実施をしようということが地元からお話としてありました。","id":"exchange-056"},{"speaker":"こんの委員","kind":"質問・要望","question":"分かりました。地元の方のご意見を伺っていただきながら、この工事も進められているということが分かりましたので、この緑地も、緊急車両も通れる、また自転車も通れるという空間も、水と緑の空間もあってと、整備されることは大変によいことだと思いますので、引き続き、地元の方、近隣の方、地域の方のお声を聞いていただきながら、安全に進めていただきたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"横山委員","kind":"質問","question":"１点だけお伺いいたします。今回、その植栽を一新していただいているということですが、植栽というのは成長いたしますので、また、日当たりがよかったり、植物が茂りやすいような環境にあるようでありましたら、日々のお手入れといいますか、その辺りの状況をどのようにされていくのかというところをお伺いさせてください。","respondent":"森道路課長","answer":"植栽につきましては、区道の整備と同じように、毎年２回、夏前と、それからちょうど今の時期ですけれども、葉が落ちる前に剪定をかけるようにしております。","id":"exchange-058"},{"speaker":"芹澤委員","kind":"質問・要望","question":"すみません、確認で、この１工区と３工区のデッキや完成後の出来上がりデザインというのですか、フェンスであったり、あとは側道の自転車道と歩道を分ける植木の配置とかも若干異なっているのかなと思うのですが、これはどういう意図で違うものが造られているのかお聞かせいただきたいのと、あと整備イメージのところで、多分側道と言われるところが歩道になるのかなと理解しているのですけれども。","respondent":"森道路課長","answer":"ここは全体的に、それぞれの沿道の方のお宅に面しているところが、側道が１.４メートルだったり２メートル程度とかだったりという形で狭いところがありますので、そういったところの段差とその幅員を考慮しながら、それぞれの断面を決めているです。","id":"exchange-059"},{"speaker":"芹澤委員","kind":"確認","question":"もう一度すみません、確認で、そうするとこの１工区なり３工区なりの、この茶色の歩道、基本的には今歩道で使っていて、緊急車両が緊急時は通れるというような道路だと思うのですが、その先に通常の車道があるというのは、段差があることでこうなっているということですか。","respondent":"森道路課長","answer":"そういった部分があって、周りの側道が大分狭くなってきているところがあるのですけれども、そこがなかなか通れないので真ん中を緊急車両の通行帯として考えているです。","id":"exchange-060"},{"speaker":"のだて委員","kind":"質問・要望","question":"この間、３工区やられてきた中で、工事の課題とかがあったら伺いたいのと、ありましたら改善をしていっていただきたいと思いますので、いかがでしょうかというところと、今回この図面が、平面図が載っているのですが、これが結構小さくてよく見えないので、これは次回からぜひ、もう少し大きく分かるようにしていただきたいというふうに思います。","respondent":"森道路課長","answer":"整備をする予定にしております。グレーのはみ出しているように見えるところは、ところどころに側道に下りる階段がございまして、それをちょっと表しています。","id":"exchange-061"}]},{"id":"topic-06","title":"しながわ区民公園北側ゾーン改修工事","agenda":"しながわ区民公園北側ゾーン改修工事","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"スケジュールのところで、１２月上旬に工事説明会を予定しているということで、どのような形で行われるのか伺いたいと思います。それと、運動施設、今回更新、新設するということで、今あるところは使えなくなってしまうと思うのですけれども、この利用者の方への案内をしっかり行っていただきたいと思いますがいかがでしょうか。","respondent":"高梨公園課長","answer":"第二期工事につきましても、継続した工事ということで、同じような形での開催を計画しておるところです。現地工事の開始ですが、工事説明会の後、準備が整い次第、できるだけ早く着手ができるような準備を進めてまいりたいというふうに考えてあります。","id":"exchange-062"}]},{"id":"topic-07","title":"舟運社会実験","agenda":"舟運社会実験","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"１点お伺いいたします。１つお伺いしたいのは、天王洲からお台場のほうに行きたいというときに、その日の出のところでは乗換えが可能というようなご説明が今あったかと思うのですけれども、どういった形でアクセスができるのかというところも含めまして、その人数といいますか、ここで乗換えた方がどのくらいいらっしゃるのかみたいなところはお分かりになるのでしょうか。お願いいたします。","respondent":"栗原河川下水道課長","answer":"今回はそういうことでやらせていただいています。実際どれだけの人数が乗り換えたかにつきましては、現在速報の段階では我々どもは把握しておりません。この後、実施終了後に、どのぐらいの人数がそういった乗換えをしたかについては分析を進めたいと考えています。","id":"exchange-063"},{"speaker":"横山委員","kind":"質問・要望","question":"品川区のほうからお台場であったり、様々な航路を使って移動していただける、逆のパターンもあるかと思うのですけれども、お台場で楽しんでいただいた若い方々が、船を使ってまた品川区に来ていただける、そうしたところをぜひ推進していただきたいという思いがありますので、ぜひ次の速報値で、そうした乗換えの人数ですとか、状況把握というところは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"}]},{"id":"topic-08","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"ご説明ありがとうございました。自転車事故についてのところをお伺いしていきたいのですけれども、（１）、交通事故発生状況の部分です。令和３年度が増加しているということですが、こちらの増加の要因というのがもし分かりましたら、どういった傾向が区内であるのかというところをお聞かせいただきたいと思います。","respondent":"工藤交通安全担当課長","answer":"令和３年の前半についても同様の措置でございましたけれども、徐々にそれが緩和された時期もございまして、緩和されると外に出る、外に出て自転車に乗ると当然交通量が増え、交通量が増えると事故が増えるといったような傾向が見てとれます。","id":"exchange-065"},{"speaker":"横山委員","kind":"確認","question":"第一当事者、第二当事者というのはどういった方々のことを指すのかというのと、第一当事者は過失割合の高いものを表すということですけれども、ちょっと具体的にどういった内容なのかというのを確認したいのと、第一当事者と第二当事者のこの件数というのは、どういった形の、年齢をどのようにこのグラフを見たらいいのかというのがちょっと混乱しているところなのですが、教えていただけたらと考えています。","respondent":"工藤交通安全担当課長","answer":"第一当事者、第二当事者の部分ですけれども、まず第一当事者、先ほどご説明したとおり、過失の重い方、それと第二当事者についてはその相手方ということで、どちらかが自転車に乗っている場合は。","id":"exchange-066"},{"speaker":"横山委員","kind":"質問","question":"そうしますと、その年齢別でいろいろ、啓発活動にどうつなげていくかというところになってくるかと思うのですけれども、ＳＮＳというのは、割と若い世代の方ですとか、高齢者も今、スマホなどもお使いになられているのかなと思うのですが、高齢者に向けた啓発活動というのは、この中でどの部分を指して、どういったことをやられているのかということと、戸越三丁目の交差点でこうした５９台まで、大分。","respondent":"工藤交通安全担当課長","answer":"先日、１０月ですけれども、大崎警察署のほうで、東京都と大崎警察署、区と合同しまして、高齢者の自転車の安全利用教室を実施しました。","id":"exchange-067"},{"speaker":"横山委員","kind":"質問・要望","question":"武蔵小山に関しては、撤去車両を２台から３台に変更したということで台数が増加したとあるのですけれども、そのキャパシティーというのでしょうか、その撤去の、例えばほかの、この武蔵小山、大井町、五反田、目黒辺りの多いところに関して、もう１台増やすと撤去できる台数がもう少し増えるみたいな形で。","respondent":"工藤交通安全担当課長","answer":"放置車両の撤去のキャパですけれども、こちらについては、今現在３台の撤去車両を運用してやっているところですが、今のところ、今の台数で対応可能というところで、もう１台増やしても、ではそれに見合うだけの撤去ができるかというと。","id":"exchange-068"},{"speaker":"横山委員","kind":"質問・要望","question":"最後ですけれども、ちょっと先ほどの指定管理のところでも少しお伺いしたところですが、そこよりもちょっと広げた部分ですけれども、品川区全体、区内全域の自転車駐輪場、またシェアサイクルのポート等も含めたというところになりますが、整備の長期ビジョンのイメージというものが、今どんなものなのかということをお聞きしたいというふうに思っております。","respondent":"工藤交通安全担当課長","answer":"自転車駐輪場ですけれども、委員ご指摘のとおり、やはり地域等に合ったニーズに応えられるのがベストだと考えています。当方としましても、先ほどございましたように、自転車の大きさに対応したスペースを確保できるところは確保するといった形で検討していきたいと考えています。","id":"exchange-069"},{"speaker":"横山委員","kind":"質問・要望","question":"そうしたものをキャッチしていただいて、自転車の整備ですとか、放置自転車の計画ということに反映していただく、どういったビジョンを持って区としてやっていくのかというところをぜひ、ほかの部署と共に連携をして、人口推計の変化ですとか、そういったものを随時見ていただきながら、調整、検討を進めていただきたいというふうに思っておりますので、最後一言お願いいたします。","respondent":"工藤交通安全担当課長","answer":"委員ご指摘のとおり、状況はそれぞれ様々な変化等があると思いますので、その状況等を見ながら、それに適した形で対応していきたいと考えています。","id":"exchange-070"},{"speaker":"こんの委員","kind":"質問","question":"2)の自転車の違反別で、運転操作誤りというのが多かったということですが、自転車の操作の誤りとは具体的にどんな操作の誤りだったのかというのが一つと、それから時間帯ですけれども、私のイメージでは朝の通勤、夕方の帰宅時間が多いのではないかと、数字的にもそんなに大差ないのでしょうけど、その中でもより、この２時という昼間の時間帯が多いという、これはどういう傾向でこういう時間帯に多いのか。","respondent":"工藤交通安全担当課長","answer":"一応、この１４時からが８８件ということで、一番多いということで黄色の表記をさせていただきましたが、委員がおっしゃるとおり、実際には８時から１０時まで、１０時から１２時までと、それがずっと続いているような、件数的には事故は満遍なく発生していますので。","id":"exchange-071"},{"speaker":"こんの委員","kind":"質問","question":"運転操作の誤り、分かりました。時間帯については分かりました。この表で見ても、８時から２時までの間、ほとんど変わりなく推移している発生件数ですので、やはりそうなのだなというふうに思うのですが、でも比較的この昼間の時間帯もこれだけ多いという中で、次の質問ですけれども、事故防止のための啓発活動をこの戸越三丁目交差点でしてくださったと。とてもいい啓発だなというふうに思います。","respondent":"工藤交通安全担当課長","answer":"今後ですけれども、本年度は戸越三丁目でしっかりと違反調査の状況調査をやらせていただいて、その傾向をしっかり分析させていただきたいと考えております。","id":"exchange-072"},{"speaker":"こんの委員","kind":"質問・要望","question":"戸越三丁目交差点を選ばれた理由、よく分かりました。町なかで意識啓発というか、そういう文化を。だから、この品川区でやっている啓発活動については、指導までで警告はできないのですか、指導までですか。警告というところまでもしできるのであれば、そこをもう少し強化するというやり方もあるのかなと思うのですが、その点はいかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"それとあと、指導と警告の定義ですけれども、なかなか難しいところがありまして、当方で運用している指導員については、指導・警告を含めてやっているというところで、口頭での注意と、あとは警告カードというものがございまして、そちらも、対象者、自転車利用者に。","id":"exchange-073"},{"speaker":"こんの委員","kind":"質問・要望","question":"指導・警告、警告もしてくださっているということで、分かりました。そちらの整備のほうも併せてしていっていただきたいというふうに思いますが、最後いかがでしょうか。","respondent":"工藤交通安全担当課長","answer":"委員ご指摘のとおり、ナビマーク、ナビラインについても、所管する課と協力しながら、適宜、検討、実施等をさせていただきたいと思います。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問","question":"この配置と、撤去作業もやられておりますけれども、これは区内全ての駅で、区域がある所ということだと思いますが、それを行っているのかどうか伺いたいと思うのと、この返還率が最近上がってきていて、平成３０年から見ますと約１０％上がってきているわけですけれども、返還率が上がってきている理由というのは区としてはどのように分析されているのか伺います。","respondent":"工藤交通安全担当課長","answer":"放置自転車等の推移の調査の関係です。こちらについては、東京都が年１回実施します。区域については、放置禁止区域の２４か所の駅周辺で実施をします。この１,０８４件というのは品川区内の放置自転車の台数です。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすると、今放置の指導はこの５駅だけでやっているということですか。そうなのですね、分かりました。撤去したときの返還率のところですけど、不動前のほうが増えているというところで、この不動前に保管する地域が拡大したとかそういうわけではない、どうしてこの不動前が増えているのかというのは、何か分析されているところがあれば伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"不動前の保管件数が増えているというところですけれども、一つの要因としましては、武蔵小山の放置禁止区域の拡大というところがございまして、そこの放置自転車の撤去台数が増えている関係で、不動前での保管も増えているといったような状況も要因の一つと考えております。","id":"exchange-076"},{"speaker":"のだて委員","kind":"確認","question":"分かりました。この表を見ますと、年齢層別では高齢の方が増えているというのが、６５歳以上の方が多いというところはありますけれども、ほかのところでも結構、２０代から３０代で２桁増えているのと、高校生のところも約２桁増えているというところで、ここの理由、区として分析されているところがあれば伺いたいと思います。","respondent":"工藤交通安全担当課長","answer":"ただ、残りの３分の２は交通違反、自転車が何らかの違反をしているということで、まだまだ広報啓発の余地はあるというふうにも併せて認識しています。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほど来ご説明があった中で、コロナで密を避けるためという話もありましたし、やはりそうした、二酸化炭素排出を抑制していくためにも車から自転車などに替えていくという意味でも、その自転車の利用などを増やしていくというのは必要なことかなというふうに思いますので、そうした中で、昨年は死者も１件あったということですので、そこをなくしていく、事故をなくしていくということが、放置も含めて。","respondent":"工藤交通安全担当課長","answer":"そういった中で、先ほど来ご説明させていただいています自転車指導員、こちらのほうも、５か所の交差点、その交差点のみならず周辺の地区も巡回をさせていただいて、そういった自転車利用者に対する指導というのも実際に行って対策を取っているところです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問・要望","question":"今回、５つの場所、自転車事故が多いという場所でこの啓発活動をされたということですが、実際の事故件数は何件になるのか伺いたいと思います。それと、この自転車に関連して、今、区では自転車活用推進計画でしたか、検討していると思うのですが、そういったことも含めて検討されていると思いますけれども、現在の進捗状況を伺います。","respondent":"工藤交通安全担当課長、鈴木都市計画課長","answer":"こちらのほうは、具体的な件数というのは警察のほうからまだ提供いただいておりませんで、年間を通じてどのぐらい発生したかというのが、その発生状況のヒートマップというものなどで確認ができるような形になると認識をしております。自転車活用推進計画の策定状況等についてご質問いただきましたので、所管は都市計画課のほうで行っておりますので、私からお答えしますが、計画の策定は今年度と来年度２か年をかけて策定を予定しておりまして。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問・要望","question":"自転車計画のところで、これは公開されているのか、傍聴ができるかどうかですが、ぜひ、できなければできるようにしていただきたいと思うのですけれども、やはりこうした計画をつくって、この自転車対策の問題も含めて検討されているというふうに思いますので、これから、ニーズも高まっていくと思いますので、重要だと思いますので、検討をしっかりしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"西村副委員長","kind":"質問","question":"放置自転車の対策についてですけれども、最寄り駅でしたら駐輪場の場所をある程度把握している方が多いと思うのですが、移動先で駐輪場の場所が分からなくて右往左往して、結果的に放置してしまうというようなこともあるのではないかなと思っておりまして、放置自転車の対策として、放置された自転車に指導書の取付けをしていただくときに、最寄りの駐輪場をご利用ください、みたいな感じで。","respondent":"工藤交通安全担当課長","answer":"警告札をつけている中で、その中に記載はないのですが、その放置駐輪禁止区域の場所に看板を立てているのですが、そちらの案内板のほうには、区営の駐輪場について、駐輪場の場所を表記させていただいているところです。","id":"exchange-081"},{"speaker":"西村副委員長","kind":"提案","question":"例えば、これはご提案ですけれども、放置自転車の対策キャンペーンみたいな感じで、特に駐輪場の利用者が減少しているところですとか、利用されづらい屋上の部分などを、一時利用を対象とした無料開放期間みたいな新しい取組みもあったら効果があるのではないかなと思っていまして、駐輪場の場所を知ってほしいということもありますし、実際に使ってみていただきたいというような利点もあると思うのですが。","respondent":"工藤交通安全担当課長","answer":"一方で、民間の駐輪場については、商店ですとかそういったところを一時的に使われる方がお金を払ってやられるということで、無料で利用していただくと、その分だけ自転車を止める方が増える、増えると本当に使いたい方が使えなくなるといったパターンも出てくるかと思いますので。","id":"exchange-082"},{"speaker":"西村副委員長","kind":"提案","question":"民間でそういった取組みもあるといいのかなと思いまして、なぜこのようなことを申し上げたかといいますと、実際に西大井の駅前でマクドナルドの前が全部、止められないようにきちんと取締りを今強化していただいていまして、購入の間だけと止めていたような方たちが今、右往左往されて、どこに止めたらいいか分からなくなってしまっているというようなことを聞きましたので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-083"},{"speaker":"横山委員","kind":"質問・要望","question":"死亡につながるような重篤な違反というのがどれなのかということを教えていただきたいと思いました。先ほど、１件死亡、車での事故というものが品川区内であって、その２件のうち１件は自転車というような、何かそういった発言が、すみません、私ちょっと聞こえなかったのですが、その辺りをもう一度クリアに教えていただけたらなというふうに思っております。","respondent":"工藤交通安全担当課長","answer":"重大事故につながる違反ですけれども、こちらについては、やはり逆走ですとか、信号無視、一時不停止、あとは歩道を徐行しないでスピードを出して走る、こういったものが非常に危険な運転ということで、警察のほうでも、先ほどこんの委員のほうからお話がありましたとおり。","id":"exchange-084"},{"speaker":"横山委員","kind":"質問・要望","question":"仙台市のほうでは、ヘルメットを試してみたい方に１週間貸し出すというような、そういった仕組みもあるように聞いているのですけれども、子どもの事故を予防する観点で、お子さんも頭のサイズとかというのは成長によって変わってしまったりということもありますので、なかなかヘルメットを購入するというのが難しい。","respondent":"工藤交通安全担当課長","answer":"大きな事故であれば当然報告が入りますし、ただ、けがを伴う事故ということで、こちらのほうには死傷者数の負傷者の部分として数字の３ということが入ってきていると考えています。","id":"exchange-085"},{"speaker":"横山委員","kind":"質問・要望","question":"子どもの事故予防の観点で、今、園バスですか、あの辺りで国も動いているのかなというふうに思うのですけれども、気を付けましょうですとか意識啓発というところもとても大事なことだとは思うのですが、どうやって子どもを守っていくのか、子どもを守れる環境をどのように、各課と連携してつくっていけるのかということに関しては。","respondent":"工藤交通安全担当課長","answer":"各関係機関と連携しまして、子どもの事故防止、最大限、力を尽くしてまいりたいと思います。事故の状況についても、可能な限りこちらのほうで把握に努めたいと考えております。","id":"exchange-086"},{"speaker":"のだて委員","kind":"質問・要望","question":"西村副委員長からあったのですけれども、短時間の無料の駐輪場利用、やはりこれは、放置自転車を削減していくためにも、一つの手なのかなというふうに思いますので、ぜひ利用者の利便性を高めるということにもなると思いますので、そこを実施することを私からも要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/979224?Template=document&Id=4364#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":74157,"voices":261}},{"id":"r04-20221101-9","meetingId":"r04-cm11","date":"2022年11月1日","dateIso":"2022-11-01","committee":"文教委員会","time":"午前１０時００分～午後 ４時４６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を95件抜き出しています。","topics":[{"id":"topic-01","title":"令和４年特別区および東京都人事委員会勧告等","agenda":"令和４年特別区および東京都人事委員会勧告等","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"確認ですが、幼稚園教員のほうが、前段の特別区人事委員会の勧告で給与が変更されるということと、区固有教員のほうは、後段の東京都人事委員会の勧告が給与に影響するということでよろしいのか。それと、区固有教員以外の教員の方もこの東京都の人事委員会の勧告で変更になるのでしょうかという確認です。直近のその状況を数として教えていただきたいのと、あと、辞められる方の例えば経験年数の特徴など。","respondent":"中谷指導課長","answer":"例えば２０代の方もいらっしゃれば、４０代、５０代の方もいらっしゃるというような状況があります。精神的なものでお休みに入られる方というのは、年代的には本当に様々であると言えるかなと考えています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり休職される方のうち、メンタルの面というのがほとんどだということなのですよね。だから深刻ですよね。数も少なくない数ですし。やはり職場改善をしていく必要があるなと思います。区内の数だと思うのですが、それが分からなかったので、これはどういう数なのかということと、あと、もし分かれば、３年間で退職されてしまった方は何人ぐらいだったのか。分かれば、教えていただきたいと思います。","respondent":"中谷指導課長","answer":"そのような状況です。もう一点補足します。先ほど、令和元年度から３年度までの３年間の病気休職の数字につきましては、東京都の教職員の数字です。","id":"exchange-002"},{"speaker":"田中委員","kind":"意見","question":"今回、若年層の給与だけ引上げということで、それはよかったなと歓迎したいと思いますが、比べる民間事業者との差額感というか。一般的に今そんなに給料が上がったという声が区民のほうから聞こえてこない中で、なかなか難しい。職員の方たちの給与が上がったことは本当に歓迎したいのですが。何だか難しいなと思いながら報告を聞いていました。まとまっていなくてすみません。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"試行的な取組としましては、先生方の職員室での監督役でもある副校長先生もお仕事が非常に多いという背景もありますので、副校長補佐という形で、東京都の事業を活用しているものです。現在はまだ試行実施ということでやっております。学校現場の現状としましては、やはり校長を中心に雰囲気づくりというのは、これまでどおり進めてまいります。私たちが持っている研修会は、若手研修、３年目ぐらいまでの先生たちをお呼びしてやっています。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問","question":"結構１人で抱え込んでしまって、子どもへの教え方なども誰に相談したらいいのだろうと悩んでしまっているという声も聞かれていたので、今、でも改善に向けて様々されているということが分かりました。もしお答えいただけたら、副校長補佐の試行実施というのが、今、何校ぐらいで、いつからやられているかということだけ教えていただけますか。","respondent":"中谷指導課長","answer":"副校長補佐の試行実施ですが、現在、小学校で１校、中学校で１校、ちょうど開始したところになります。１０月１日から荏原第五中学校、１１月１日から立会小学校で試行実施をしております。","id":"exchange-004"},{"speaker":"若林委員","kind":"質問","question":"教えてください。人事委員会と東京都、いずれも初任給であるとか若年層、初任層というところの改定となっていますが、ここら辺をどのように理解したらよいか。区としてこれをどのようにして反映していくかというものはお聞かせいただけますでしょうか。","respondent":"中谷指導課長","answer":"勤勉手当につきましては、０.１月分が引き上げられることに伴いまして、引上げ分を加えた形で、管理職を含めた全員が該当するということで、１２月の勤勉手当にて支給ということを予定しております。","id":"exchange-005"},{"speaker":"若林委員","kind":"質問","question":"いわゆる意見が載っていて、人材確保みたいなところがちらっと見えますが、特段、初任層とか若年層という表記はあまり見られませんでした。すみません。意見とポイントがあまり合致しないなというのが率直な感想なのですが、何かお話を聞いてくださったのですか。もう一つ、若年層というのは、年齢で言うとどこら辺で線引きするのか、教えてください。","respondent":"中谷指導課長","answer":"そのほかのものにつきましては全ての方々をということで、公民比較ということでやっておりますので、その２つに分けて比較しております。","id":"exchange-006"}]},{"id":"topic-02","title":"令和４年度（５年度採用）品川区立学校教育職員採用候補者選考状況","agenda":"令和４年度（５年度採用）品川区立学校教育職員採用候補者選考状況","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"去年のご説明ですと、去年３名採用しますということで、その目標のとおり３０名に達するということでしたが、今年はなぜ４人の採用になるのでしょうかと。４人辞めてしまったのですかということですね。２年前は、一次申込みの時点で６１名いたのです。それが２０名ということです。そこら辺について、なぜこんなに減ってしまったのだろうと、どのように分析しているのでしょうか、伺います。","respondent":"中谷指導課長","answer":"そういった声をかけてくださる大学のタイミングを逃さず、学生たちに引き続きアプローチをかけていきたいなと考えています。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺に目を向けていただきたいなと思います。だから空きが４名という理解でよろしいのかというところを質問したいと思います。この区独自教員は３０名を目標としています。こうした現場での要望、柔軟な措置を行っているのはここだけだと思いますが、となると３０名も雇うのに、今２６名ですか、そのうち１名は三木小学校で活用されていると。そこら辺をちょっと伺いたいなと思います。","respondent":"中谷指導課長","answer":"近々ケーブルテレビなどを用いて、何が先生として楽しいか、どういう仕事に魅力があるかというようなところを発信できるような取組を企画して実施していきたいなと考えています。今年度４名募集したということについてです。","id":"exchange-008"},{"speaker":"安藤委員","kind":"質問","question":"三木小学校の話をしましたが、私がちょっと伺ったのは、３０人を目指して２６人採用していって、そのうち１人はそういう使い方をしているのに、２５名の方は一体どこへ行ってしまったのかなというか。クラスを持っているのでしょうけれど、その分、市民科専門の人がいるのですか。実際に三木小学校の３年生はそういうことでやっているのですが、その現状を見ていると、１年生はやはり大変ではないですか。","respondent":"中谷指導課長","answer":"当然その教科をどういった学級形態でやっていくかという検討は、まず学校長がその者とどうしていくかを検討した後に、こうしたいというような具体的なイメージをつくり、そして教育委員会に申請するという理屈になっております。","id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。現場で求められている、あるいは実際の子どもたちや保護者が求めている形で独自教員を活用していくところがあるわけですね。そういう申請があった場合にはぜひ広く検討をしていただきたいですし、これを実際に広げてもらえたらなと思います。すみません。三木小学校のような活用の仕方をしているのは、三木小学校しかないのでしょうか。小中学校でほかにあれば。伺って終わりにします。","respondent":"中谷指導課長、勝亦学務課長","answer":"基本的には、固有教員の活用の仕方というのは先ほど申し上げたとおりになるので、そのもっとミクロな部分だと思いますが、例えばＩＣＴや市民科を担う以外の学級編制というところまでは。学級編制上におきまして、固有教員を少人数学級に充てていますのは三木小学校のみという状況になってあります。","id":"exchange-010"},{"speaker":"田中委員","kind":"意見","question":"すみません。今の加配の部分で三木小学校のみの加配ということでしたが、三木小学校が選ばれた理由というか、どういった経緯で加配になったのか。私も加配については、先生たちの負担を軽減しますし、子どもたちのためにも必要だと思うので、ちょっとそこの部分をお知らせいただければと思います。","respondent":"勝亦学務課長","answer":"こちらの加配といいますか、現在、三木小学校の３年生が６１人ということで、通常ですと２学級の状態ですが、３学級で編制しております。こちらについては、特別に配慮を要するお子さんがいるということで、３学級の編制にしているという状況です。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"その場合は、特別な支援が必要な子がいたために校長から申請があって、加配というかそこに行くということになるのか。その手続を教えていただけますか。","respondent":"勝亦学務課長","answer":"学校から申請をいただきまして、学級編制のほうが細かくできるか、また、人員が充てられるか、指導課と連携しながら決定しているものです。","id":"exchange-012"},{"speaker":"渡部委員","kind":"質問","question":"本当に数字のことで申し訳ないのですが、今の議論の中で、２６名。取りあえずの母数というのは、今２６名でいいのかどうかということと、２６名のうち校長はいなかったと思うのですが、副校長先生が何名、主幹が何名、主任が何名、一般教諭が何名というところまでちょっと教えてほしいなというところで、現状の数字を聞かせてください。その辺も数字が分かったら教えてください。","respondent":"中谷指導課長","answer":"義務教育学校には８名を配置しております。免許の内訳です。小学校の免許を持っている者が１６名、中学校に関しましては、国語が３名、社会が８名、数学が３名、理科が２名、保健体育が５名、英語が７名、特別支援教育が５名、美術科が１名となります。","id":"exchange-013"},{"speaker":"渡部委員","kind":"質問・要望","question":"先に質問をちょっと続けします。これもいよいよ３０名全員ということで、私自身も何度も、これは別に３０人で限ることなくと言っていましたし、品川区の教員の方にいろいろご活躍いただきたいし、例えば校長先生にもなってほしいというのは、もうかねてから質問のたびに言わせていただいています。そこをしっかり持っていないと、議論がどんどんおかしな方向に行ってしまうと思います。","respondent":"中谷指導課長","answer":"今現在そのものを担っている者はいないのですが、同じ６級職というところは変わりはないのですが、名称がやはり校長という名称をつけることができないというのが、昨年まで東京都教育委員会とずっとやり取りを交わしてきた中での今の時点でいただいている結論です。","id":"exchange-014"},{"speaker":"渡部委員","kind":"質問・要望","question":"しっかりと、やはりその学校を任せて、お願いできて、校長先生になってほしいなというのを、やはりずっと僕は思っていますし、そういう制度に変えていただきたいなと思うのですが、私たちができることではないので残念なのですが、よく分かりました。そういうこともしっかりやっていただきたいというのは、そこは要望にしておきますが、再任用のところだけちょっとお聞かせください。","respondent":"中谷指導課長","answer":"今現時点で再任用されている方はもちろんいらっしゃいませんが、１０年スパンで見たときに、これに関して、ご自身のキャリアを検討というか考え直す必要があるという方がいらっしゃいます。そういった経緯で、今回規定をさせていただいたというところがあります。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"３０人になったから採りませんではなくて、やはりこれまでの間、採用事務を品川区としてやってきているわけですから、そこに関しても区の教育委員会事務局の中でもノウハウが蓄積されてきていると思うのです。３０人に欠けたから１人採用ですというのでなくて、本当に優秀な人材をこれから採っていくのだというような姿勢で。そういう施策の推進をしていただきたいと要望します。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"}]},{"id":"topic-03","title":"SHINAGAWA ICT SYMPOSIUMの開催","agenda":"SHINAGAWA ICT SYMPOSIUMの開催","exchanges":[{"speaker":"安藤委員","kind":"確認","question":"今の最後のご説明ですと、区民の方だったら誰でも午後のオンライン配信が見られるということでよろしいのかという確認です。講演のタイトルやディスカッションのタイトルもありますが、この人選の理由をちょっと伺いたいのですが、区教委としては、こちらの方々に何を期待してお呼びしたのでしょうか。伺いたいと思います。","respondent":"中谷指導課長","answer":"これまで令和３年度品川区ＩＣＴ効果検討委員会の委員を務めていただくほか、教育委員会で主催しております教員を対象としましたＩＣＴの研修会で長らく講師を務めていただいております。","id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"理由は分かりました。私、この姿勢が大事なのではないかと思うのです。皆で考える上では、こうしたＩＣＴの限界あるいはリスクについても含めて、私は考えるべきだと思います。それは意見として述べさせていただきたいと思います。質問です。主なテーマというところに、それぞれ３つのポチがあります。現状での区教委としてのそれぞれの成果と課題については、どのように捉えているのか、伺いたいと思います。","respondent":"中谷指導課長","answer":"そういった活用をもっと広めていきたいという思いを持っております。まだまだ一部での活動という認識でおりますので、こちらについては、実践されている学校の取組を広げていきたいと考えています。最後の家庭における活用状況です。","id":"exchange-018"},{"speaker":"田中委員","kind":"確認","question":"ＩＣＴシンポジウムというのは、品川区以外の自治体でもやられているのかということをまず確認したいのと、確かに成果も様々あったとは思いますが、しかしやはり課題も大きく見えているところがあるということは、保護者の一人としても感じています。今ほかの自治体でもこういったシンポジウムが開催されているのかということと、課題についてのお話を伺えればと思います。","respondent":"中谷指導課長","answer":"シンポジウムの開催に向けては、リハーサルも１か月前から行っておりまして、十分にいろいろなことを考え、構築した上での本番を迎えていきたいなと考えています。","id":"exchange-019"},{"speaker":"田中委員","kind":"確認","question":"後でＩＣＴ教育についてというところもあるので、そこでお話しすべきなのかちょっと悩んで、シンポジウムのほうで話してしまいました。私としては、やはり誰でもオンラインで受けられる状況はあっていいのではないかなと思いますが、そこの部分について確認させていただいてもよろしいですか。","respondent":"矢部教育総合支援センター長","answer":"ただ、現状、コロナのことや体調不良で教員のほうが全てに対応できない場合もあるので、それはそれぞれ学校にご相談いただいて、私どもが伝えていることは校長も認識しておりますので、ぜひご相談いただきたいと思います。","id":"exchange-020"}]},{"id":"topic-04","title":"令和４年度品川区学力定着度調査および令和４年度全国学力・学習状況調査の結果","agenda":"令和４年度品川区学力定着度調査および令和４年度全国学力・学習状況調査の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"正答率とありますが、要するに１００問問題があるとすれば、その中で何問正答したかという割合のことなのでしょうか。いわゆる点数ですと、問題ごとに異なる点数が配分されて、トータルで１００点という点数なのですが、その点数とどう違うのかというのをちょっと伺いたいと思います。それぞれどこなのか。ちょっと分からないのですけれど、伺いたいと思います。そこら辺をちょっと伺いたいと思います。","respondent":"中谷指導課長","answer":"つまり１０人の方が受けていて３人の方が正答すれば、３割る１０というような割合で出てくるものが正答率です。そういう意味で申し上げますと、全員が正答すれば１００％というものです。３つ目の業者につきましては、今回、東京書籍に問題を委託という形で実施しております。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう国語と数学と英語にすごく力を入れてしまっていて、ここら辺がおろそかになっているということはないのか、伺いたいと思います。それが質問です。それと、全国の３枚目のほうの右下の８番のところ。同じ授業をやっていて、同じクラスの中で子どもによって使用率が違うということはないと思うので、これはつまり学校ごとにＩＣＴ使用頻度の格差があるということなのでしょうか。伺いたいと思います。","respondent":"中谷指導課長","answer":"３点いただきました。１つ目は、全国学力・学習状況調査の業者というところです。こちらは文部科学省が実施しており、国立教育政策研究所で主に作成しているものです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"予想します。区の調査ですが、品川区と全国を比べているではないですか。全国版でやっているということなのですか。なぜ全国が出てくるのかというのがちょっと分からなかったので、これは伺ってお答えいただきたいです。３枚目の８番の右下のところについてです。全く真逆なのです。ですから、私は、この結果をもってタブレットをさらに活用する口実に使うべきではないと思いますが、いかがでしょうか。","respondent":"中谷指導課長","answer":"やはり年齢に応じて、学年に応じてＩＣＴのタブレットをどういうふうに使っていくかということを具体的に研究していくことが非常に大事かなと思っています特に中学生、義務教育学校後期課程のお子さんたちが、技術的には使い方には慣れているけれども。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"だから、コンピューターを使うとき、探求的な学びにどう役立つかというところで使うべきだし、コンピューターを使うがあまり、そういう顔を突き合わせて行う協同的学びの時間が削られるとか、あるいは追いやられるということがあってはならないので、こういう結果を単純に促えて運用しないでほしいということを改めて要請します。競争でないと言うのだったら、なぜ学校ごとの結果を渡しているのでしょうか。","respondent":"中谷指導課長","answer":"先ほど申し上げたような社会の授業をどうしていくかということや、理科の様々に答えられていない、誤答が多い、また無回答が多い状況をどうしていくかというようなことは、傾向としてやはり出ておりますので。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"それなら、なぜ、あなたの学校は区の平均と比べてこうですよとか、あるいは学校ごとに結果を渡しているのかなというのが理解できませんけれど、そういうことをすることによって、学びの動機が各現場、各学校ではテストの点数をどう上げるかというようなことを目的に動かざるを得なくなってしまうというところなのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"田中委員","kind":"質問","question":"品川区学力定着度調査の結果についての１枚目の７番、課題の見られる問題例のところで、四角に囲った正答の部分についてです。個々のつまずきの箇所に注意する必要があるとありますが、この個々というのは、子どもたちの一人ひとりという意味なのか。そして注意する必要があるのは誰なのかというところを教えていただいてもよろしいですか。","respondent":"中谷指導課長","answer":"ご質問の資料１枚目の７番の課題の見られる問題例というところの解説文になろうかと思います。個々のつまずきというのは、こちらの場合、生徒一人ひとりのつまずき。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"ここの内容はそうだと思っています。この下の右を向いた黒い三角の指している「８年生理科は」から始まる文章の中でも、「９年生でも目標値を下回り、基礎・基本的な知識・技能の定着や主体的に学習に取り組む態度が課題である。そこを補うための工夫が必要なのではないかといった声が聞かれるのですが、今どういった工夫がされているかというところをお知らせいただけたらと思うのですが、いかがでしょうか。","respondent":"中谷指導課長","answer":"先ほどのご質問にあったような、協働的な学びという時間と、それが終わった後に個として１人で振り返って考える時間と、しっかりそういったバランスの取れた授業を展開していくことがやはり力をつけていく上では大事であるという方向性を思っております。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"先生たちが子ども一人ひとりのつまずきに気づきにくい状況があることから、やはり加配などで先生をフォローして、子どもたちもフォローできるような態勢もやはりこれからもつけていかないと、学力の定着というか基礎の知識がつかないまま、分からないところが分からないまま学年が上がっていってしまうということがあるので、ぜひそういった考え方を進めていただけたらなということを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-05","title":"令和３年度指定管理者による管理に対するモニタリング・評価の結果について令和３年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和３年度指定管理者による管理に対するモニタリング・評価の結果について令和３年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今年はマイナスのところはないですね。差引収支というのがマイナスになった場合というのは、それはもう事業者の持ち出しになるということでよろしいのか伺いたいのと、Ａグループの令和元年度と令和３年度の人件費と指定管理料を見ますと、ちょうど人件費の増額分が指定管理料の増額分とほぼ同じように見えるのですが、人件費というのはなぜ上がったのか。伺います。","respondent":"吉田品川図書館長","answer":"１点目の令和２年度におけるＡグループのマイナスの部分です。こちらにつきましては、事業者の持ち出しということになります。２番目の人件費の増につきましては、この間の最低賃金の上昇や指定管理者のほうの従業員の昇級等を含めまして、人件費の増がかかったものです。","id":"exchange-029"},{"speaker":"安藤委員","kind":"質問","question":"そこら辺どうなのかというのをちょっとお伺いしたいと思います。第三者の意見というのが入っていますが、第三者の意見というのは、誰がどのように評価しているのでしょうか。伺います。利用者の満足度調査という記載があります。全部言ってしまいますが、有資格者の配置状況についてですが、Ａ、ＣグループとＢグループではちょっと違う感じなのですが、その違いはなぜなのでしょうか。伺いたいと思います。","respondent":"吉田品川図書館長","answer":"賃金アップにつきましては、指定管理につきましては５年間指定管理を行うことを前提で契約を行います。そのために、５年間の賃金上昇分を見込んだ形での見積り等を出していただいております。それを年度ごとに金額として協定を結んで履行しております。","id":"exchange-030"},{"speaker":"安藤委員","kind":"質問","question":"そういった面からも、区が直接雇用でやるのがいいのではないかなと私は思っています。説明でちょっと分からなかったのが、最後１点だけ。第三者意見と利用者満足度調査というのは、同じということですか。企画調整課で利用者の満足度調査を委託していますという話がありましたが、そこがちょっと分からなかったので、お伺いします。","respondent":"吉田品川図書館長","answer":"実際としては、内容としては同じものになります。ただ、８月に取ったアンケートに基づいて分析するという形になりますので、最終的には内容としては同じものになります。","id":"exchange-031"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと資料についてお伺いしたいのですが、各学校での活用の様子というところの写真の右から２番目の撮影した動画を活用しての対話というところがありますが、これはどういう感じなのか。品川区の場合は、東京都や全国に比べて「ほぼ毎日」や「週３回以上」がかなり多いと思いますが、なぜこのようになっていると品川区は分析しているのでしょうか。伺いたいと思います。","respondent":"中谷指導課長","answer":"３番目のご質問で、タブレットの活用の頻度が全国や東京都と比べて非常に高いと。なぜここまでたどり着けたかというところですが、やはり１つは、研修をずっとやってきた成果というのがあるかなと考えています。","id":"exchange-032"},{"speaker":"安藤委員","kind":"質問","question":"動画を活用しての対話というのはよく分かりました。ちょっと最後の質問のところですが、数字上、品川区の場合はタブレット使用がかなり多いと思うのです。例えば教育委員会として、必ずこれぐらいは使ってくださいねという指導や指示というのはあるのか、ないのか。そこら辺を伺いたいと思います。","respondent":"中谷指導課長、矢部教育総合支援センター長","answer":"そういった面で言いますと、品川区はＷｉ－ＦｉとＬＴＥと両方でやっておりますので、安定したインターネット環境が構築できているのかなと。そこもやはり使用が進んでいく一つの要因なのかなと考えております。授業の中で毎日使っていますが、時間は何分ということは書いてありません。私たちが見ている中で、１時間授業の４５分、５０分を全てＩＣＴを使って授業しているというのは見たことがありません。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"ネット環境についてもかなりきちんと相当なお金もかけているということだとは思いました。アクティブラーニングというキーワードがありますが、やはりこれから必要な学びとか学力というのは、これからはどんどんＡＩに取って代わられる時代になっていくという指摘もあります。そういうことのためにタブレット等は活用していただきたいと思います。それは意見として申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"田中委員","kind":"質問","question":"取組の中のＩＣＴ活用推進の中の活用状況調査の実施というのがあります。その調査内容を伺いたいのと、ヘルプデスクの活用とありますが、具体的にどういったことなのかということをお知らせください。","respondent":"中谷指導課長、勝亦学務課長","answer":"ＩＣＴ活用状況調査について、まずご説明申し上げます。こちらにつきましては、令和３年度の時点の品川区立学校におけるＩＣＴ活用状況を独自に調査しております。内容といたしましては、実際に使っている中でのトラブルの対応や問合せ、使い方への対応、それから障害への対応または故障の対応等々、技術的な支援といったものを電話・メール等でしているものです。","id":"exchange-035"},{"speaker":"田中委員","kind":"確認","question":"先ほど私が事例として挙げた、例えば学校を休んだときの授業の受け方の状況についても、長期休暇以外のときでも活用できている学校とできていない学校があるということは、区教委としても把握はできているということでよろしいのかという確認をさせてください。市民科デジタル化ですが、これから教科書をデジタルにしていくということなのですか。","respondent":"勝亦学務課長、矢部教育総合支援センター長、中谷指導課長","answer":"こちらはｉＰａｄのリースをＮＴＴドコモからしておりまして、その契約の中でヘルプデスクを開設していただいているもので。市民科の教科書につきましては、全てのお子さんのｉＰａｄの中に市民科の教科書をデジタル化したものを１０月から導入しています。先ほどの活用状況調査の質問項目ですが、ご指摘いただいた休み中の授業の受け方というところについては、今回。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"市民科デジタル化のところで、市民科に限らずほかの教科書もデジタルにしてきた、しているということではないのですか。先ほど学校には呼びかけているということでしたが、学びの機会の確保ができるように、できない学校の場合にはなぜできなくて、どういうフォローが必要かといった各学校の状況もくみ取っていただけたらと思うのですが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"学校はかなりそれぞれ工夫をしていて、持ち帰るものと置いていっていいものと分けている。学年によって変えたり、また、お子さんの体格やご家庭のお考えもあるので、個別には対応していると認識しております。ＩＣＴの対応につきましても同様です。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"市民科のデジタル化については、子どもたちのタブレットに入っていることも、ほかの教科も英語からというのは分かりました。本当に本が必要になるかどうかはこの先の判断ということでした。そういったこともちょっとお知らせいただければと思いますが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"データですので、ホームページに上げるかどうかというのは技術的にはできるかもしれません。それも中身の検討や活用方法をきちんと検討してから進めてまいりたいと考えています。","id":"exchange-038"},{"speaker":"渡部委員","kind":"質問","question":"大勢の先生がいらっしゃる中で、この人のやり方は面白いな、すごいなというのは、映像化されるか何かして、ほかの教員の方々に事例集のように共有がなされていて、ほかの方々が活用できるような仕組みになっているのかどうかということを教えてほしいです。一点は児童・生徒の側の話です。ちょっと気になっていたので教えてほしいです。もう一件伺います。例えば因数分解は大事なものではないですか。","respondent":"中谷指導課長","answer":"こういう授業をやったら、子どもたちがこのように変わったということが分かる優良事例をためて、事例集を作って共有できるように、教育委員会として進めていきたいと考えております。","id":"exchange-039"},{"speaker":"渡部委員","kind":"質問・要望","question":"特に課長から最後にご説明いただいたところというのは、せっかくタブレットを持っているわけですから、家庭教育に持ち込んで、保護者と一緒になってそういうのを進められる仕組みができると、今の保護者は、相当一緒になってやってくれるのかと思ったりもしています。品川区の子どもたちですから、そういうところは大丈夫なのかなと思いつつ、やはりどこかちょっと一抹の不安があります。すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"若林委員","kind":"質問","question":"コンパクトな資料ですので、ＩＣＴ教育は、なかなか現場を見ることもふだんありませんので、ご説明のないところをちょっとお聞きしたいと思います。家庭との連携というのは、今までの質疑で、さっきの話のことなのかどうなのかも含めて、ちょっとコメントをいただけますか。はまとめて、ＩＣＴ活用重点校が小学校１校、中学校が２校と。そこら辺の重点校についてのお話もお願いいたします。","respondent":"中谷指導課長、勝亦学務課長","answer":"そういった中で、ロイロノートの活用ということも含めて、それぞれの学校で進めていただいているという状況です。各種アプリの活用導入のところについて、お答えいたします。防災アプリ等々です。","id":"exchange-041"},{"speaker":"若林委員","kind":"質問・要望","question":"課がもう違うのですね。なるほど。分かりました。取りあえずお話を伺いました。重点校のお話は、今度の１１月３０日のシンポジウムを含めて確認をしたり、また、今後の展開にということで楽しみにさせていただきたいと思います。はここに出てこないものとして、これは特別支援教育にはどういうふうに活用されているのか、されていないのか。ちょっとここは、現状も含めて方向性をお聞かせいただけますか。","respondent":"矢部教育総合支援センター長","answer":"特別支援教育につきましては、特別支援学級には特に２人に１台、これまでも使っておりました。この導入に際して１人１台になりました。基本的なアプリは同じなのですが、お子さんに合わせてそれぞれアプリが替わっている場合があります。","id":"exchange-042"},{"speaker":"若林委員","kind":"質問","question":"今のお話だと、自然な流れの中で各学級、先生で活用して、こんなアプリもあんなアプリも活用できますよというふうにどうしてもちょっと聞こえてしまったので、今後の力の入れ具合、また、どこら辺が課題になるのかというのは、教えていただいて。教室は通常学級との関連がありますが、特別支援教室はどういうふうに立て分けているのか。使い方をちょっと、教室についてのコメントをいただければ。","respondent":"矢部教育総合支援センター長","answer":"特別支援教室は、基本的に持っている子が、例えば１年１組のお子さんが木曜日の２時間ぐらいお出かけしていくので、その場合使わないときもありますし、それがとても有効だということが分かれば、また落ち着いた自立活動に向けて有効だということが分かれば持って行って。","id":"exchange-043"},{"speaker":"若林委員","kind":"確認","question":"なるほど。聞いてみないと分からないですね。そういうふうに両課でしていただければいいかなと思います。特別支援学級は、通常教室と特別支援教室の２つの教室を往来している中で、通常学級の先生と特別支援教室の先生の授業の振り返りや確認、連携という意味でのタブレットの有用性というのは、何かあるのか。ありそうな気がしますが、いかがでしょう。","respondent":"矢部教育総合支援センター長","answer":"担任は授業中ですので、離れているその場面をなかなか見ることができないので、放課後などにそのノートを共有して、保護者と情報共有しています。ＩＣＴを使うということであれば、その辺りです。","id":"exchange-044"},{"speaker":"若林委員","kind":"質問・要望","question":"ありがとうございました。人数で言うと、通常は大きくて特別支援は小さいということに当然なるわけですが、さっきありましたように一人ひとりのニーズという意味でいけば、特別支援教育のそもそもの意味がそういうことですので、しっかりと研究、また取組を進めていただきたいなとお願いをして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"ＩＣＴというものが導入されて、もう１年半たったのですね。その中で、ＬＴＥモデル。要はＷｉ－Ｆｉの環境がなくてもできますよというのが本当に売りで、Ｗｉ－Ｆｉ環境がない子どもにもこういう学びを閉ざさないという品川区の姿勢に改めて感謝するとともに、このＬＴＥの使用状況というのですか、電波状況。利用状況というのがちょっと分かったら教えていただきたい。それを教えていただきたい。","respondent":"勝亦学務課長","answer":"ただ、全体の平均をしますと２ギガバイト程度の使用になっているのですが、中には修学旅行にｉＰａｄを持っていって学習に活用するといった使い方もできておりますので、非常に有効な活用ができていると感じております。","id":"exchange-046"},{"speaker":"松澤副委員長","kind":"質問","question":"これからのＩＣＴ向け。でも、スタートして１年半。だからこそ、２年目に向かうときに、そのＩＣＴを、どういう授業にいかすかというのは、この取組にも書いてありますが、とても大事なことだと考えています。そういった先生をどう守ってあげるのかというのが、これから２年目に向かうＩＣＴ教育の課題の一つでもあるかなと私自身は思います。学びをどう持っていくのかというのをちょっと教えてください。","respondent":"中谷指導課長","answer":"校務での支援をきちんとデジタルを活用していくことで、ＩＣＴを活用していくことで、今まで時間がかかっていたことがスムーズになるようなところをしっかり整えていきたいなと思います。","id":"exchange-047"},{"speaker":"松澤副委員長","kind":"質問","question":"ちょっと聞きたいのは、ＩＣＴ支援員というのが、要は学校の勉強の仕方を教えてくれる方向性でありますから、なかなかこのＩＣＴ支援員の活用というのは、先生の学びとイコールになっているかちょっと分かりませんが、先ほどおっしゃっていただいたように、聞くことのできない先生も出てくると思うのです。聞くことが恥だと思ってしまうというのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"田中委員","kind":"質問","question":"ごめんなさい。１点だけ。ちょっと設備のほうですが、プロジェクターや教師用パソコンなど様々ある中で、以前、予算特別委員会かどこかでも質問したと思いますが、先生用のマイクについてです。でも、こうやってＩＣＴを進めていくというのであれば、やはり専用のマイクというのは絶対必要だと私は思いますが、区教委としてはどのようにお考えかというところを１点だけお知らせください。","respondent":"勝亦学務課長","answer":"専用のマイクがあればクリアな音声でというところは理解できますが、そういった周辺機器につきましては、各学校に消耗品を購入する予算を配分していますので、授業の状況等に合わせてご対応いただきたいと考えております。","id":"exchange-049"}]},{"id":"topic-07","title":"その他(1)所管質問","agenda":"その他(1)所管質問","exchanges":[{"speaker":"田中委員","kind":"質問","question":"１０月２７日の高橋しんじ議員の教育・子ども施策についてです。廃園を区教委で行わなかったのか。昨日の議論も含めて質問をしてしまうと、越権行為ではないかということに対しての答弁が明確でなかったのは伺いたいことの１点です。運営事務がどこまでを指しているのかということと、決定権まで委任ができるのが補助執行なのかという部分について伺いたいと思います。","respondent":"勝亦学務課長","answer":"こちらにつきましては、保育園のニーズの高まりや区立幼稚園の入園状況を踏まえて、区では令和３年度よりこども未来部と教育委員会が連携し、プロジェクトチームを立ち上げまして、区立幼稚園の今後の在り方等について検討を重ねてきたものです。","id":"exchange-050"},{"speaker":"田中委員","kind":"質問","question":"越権行為ではないといったことでしたが、そうですかというところです。教育長は、ここで協議して内容の是非を問うということにはならないかと思うとして、ほかの委員の方たちの意見を促しているのですが、１回報告事項で上がった伊藤幼稚園の閉園に向けた方針というのが、もう一度教育委員会で諮られて結果が出ていくのですかという、この手順もちょっと不思議なのですが、そこもお知らせいただけますか。","respondent":"勝亦学務課長","answer":"プロジェクトチーム、検討委員会の中での様々な意見があったというお話に関してです。","id":"exchange-051"},{"speaker":"田中委員","kind":"確認","question":"ただ、話の結論。教育委員会は、早過ぎるとストップをかけていたのです。大変だっただろうなということです。区教委で区立幼稚園の状況については８月２３日に報告が上がって、是非を問う場所ではないですということで報告をしているのですが、再度、条例変更をするために、もう一度区立幼稚園についてということが教育委員会で審議されるのですかという確認をしたいのですが、明確に教えていただけますか。","respondent":"勝亦学務課長、宮尾庶務課長","answer":"幼稚園廃止を行う場合、必ず幼稚園の条例の中で廃止というものが必要になりますので、必ず教育委員会のほうにこちらの条例改正について議論いただき、議決をいただいた後、議会に条例改正の提案をするという形になってあります。すみません。教育委員会の権限というところで、ちょっと私から答弁をさせていただければと思います。地方教育行政の組織及び運営に関する法律の第２１条の中に、教育委員会が職務権限として行うべきものが明記されております。","id":"exchange-052"},{"speaker":"田中委員","kind":"質問・要望","question":"補助執行している中身を教えていただいてもよろしいですか。いつから補助執行しているのか。昨日、平成元年からと言われましたが、ちょっと明らかではなかったので、そこを教えていただきたい。一番最初に子ども、そこに通っている子どもの保護者、地域にもきちんとした説明がないままに進んでしまった今回の手続の進め方について、教育委員会としてどう受け止めているかというところも伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"若林委員","kind":"質問","question":"冒頭の田中委員の質問は、今日、初めて補助執行という言葉が出てきましたが、法律に基づいて教育委員会の権限がどこまであるのか。逆に保育課に、区長部局のほうにどこまで許されるのかという質問だったはずです。ですので、今の拙速だったということは、今日の質問にはそもそも入っていなかったので、それを踏まえて進行していただければと思います。高橋しんじ議員の質問に対してということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"田中委員","kind":"確認","question":"高橋しんじ議員の質問は、これは越権行為ではないのかということだったのです。私は昨日は、越権行為だったのではないですかということに明確な答えがなかったので、改めてということを伺いたかったのです。これは法令違反になる可能性があって、議会としてこれを認めていいのかと、この問題は本当に大事な話ですから、ということをきちんと皆さん共有したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問","question":"これ、実態はどうなのかというところが私は大事だと思っています。これは明らかに越権行為というか。といいますのは、私も８月２３日の教育委員会の議事録も拝見していますが、もう教育委員会がかなり形骸化しているといいますか、報告事項にとどめているわけですね。これは、教育委員会としては、結論が決まっているのに、では、何のために開くのですか。そこについては反省がないのでしょうか。","respondent":"宮尾庶務課長","answer":"一部繰り返しの答弁になりますけれども、改めて廃止の決定というところに関しては、再度、これはもう法に基づくものとして教育委員会を開催し、そこで、また結論はどうなるか、全くフラットなところで教育委員会を開催して。","id":"exchange-056"},{"speaker":"安藤委員","kind":"意見","question":"昔は選挙で決めていたのです。ただ、残念ながら今はそういうふうになっていなくて、ある意味、行政機関の決定の追認機関になってしまっているという現状が、これは１つ大きな問題としてあります。決定のときだけ教育委員会を開きますというのは、これはあまりにも私は教育委員会としての機能をおとしめるものであり、こういうやり方というのは、私は承服できないというふうな意見を言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-057"},{"speaker":"田中委員","kind":"質問","question":"今、方針の決定だけであって、最終的な本当の決定というのは教育委員会ということは理解しました。ただ、方針が決定された時点で、当事者たちにも説明がないままに、もう閉園だということで話は進んでしまっています。でも決定はしていない。では、今から取りやめることはできるのですかということが上がってきたときには、取りやめることはできるのですか。ということを伺いたいのですが、いかがでしょうか。","respondent":"勝亦学務課長","answer":"今、区立幼稚園３園が出ているかと思いますけれど、入園・退園に関しましては、区長部局で補助執行しておりますので、その取扱いは保育課のほうで退園……。","id":"exchange-058"},{"speaker":"田中委員","kind":"質問","question":"今、入園・退園の話ではなくて、今後の幼稚園の在り方についてなのですが、補助執行している範囲というのは分かりました。７３４人の方から陳情が上がっている中で、では廃園を中止することは可能なのですよねという問いが私たちに来た場合に、私たちは何と答えたらいいのでしょうか。今、方針だけが決定しているので可能ですよと答えていいのですか。どうでしょうかと、そこの部分を伺いたいのですが。","respondent":"勝亦学務課長","answer":"繰り返しになりますけれども、廃止の決定については教育委員会で議論いたしまして、条例改正が決定いたしまして区議会で条例を出させていただいて、条例が成立して廃止が決定するものと考えております。","id":"exchange-059"},{"speaker":"田中委員","kind":"確認","question":"実際、今の二世、三世問題とか統一教会の問題がすごく出ている中で、自分が当事者だったのだと気づいた子どもが、今、相談できる体制というのがあるのかと。相談を受けたときに、つなげる先があるのかというところを確認できたらと思うのですが、いかがでしょうか。","respondent":"矢部教育総合支援センター長","answer":"相談窓口や手段が多数あることを指導することが今、重要と考えております。それがたとえ信仰を理由とした虐待行為であったとしても、ご説明した複数の体制で学校が察知するものと考えて、このような答弁になっております。","id":"exchange-060"},{"speaker":"田中委員","kind":"確認","question":"信仰にかかわらずの相談を受ける通常の体制で今カバーをしているといった認識でよろしいですよね。その中で、当事者だったという相談が今現に上がってきているかどうかということをもしも把握できていたら、受けてからどこにつなげたのかということも確認できたらと思います。","respondent":"矢部教育総合支援センター長","answer":"今現在、特別に信仰を理由とした虐待という案件は、センターとしてはまだ聞いておりません。もしもあっても内容によるのですが、お子さんが虐待のような状態でありましたら、すぐに子ども家庭支援センターかなというふうには今考えております。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"連日の報道で、私のこの大変な状況は信仰の二世、三世問題だったのだと気がつく人がでてくる、なぜこんなに自分がつらいのだろうなと分からない人が、自分のつらさの原点が分かる。今のところそういう事例の相談はないという話ですが、仮にそういうお子さんから具体的に相談があった場合、二世、三世問題の相談があった場合、子ども家庭支援センターのほかに何かないのですか。","respondent":"矢部教育総合支援センター長","answer":"学校で担任が最初の窓口になるかと思いますが、そのお子さんの環境をどうやったら改善できるかということを考える。そこから私どもも情報を得て、今、子ども家庭支援センターと申し上げましたが、必要な関係機関につなげる努力はいたします。","id":"exchange-062"},{"speaker":"安藤委員","kind":"意見","question":"マインドコントロールなどいろいろ大変な複雑な問題で、特別な専門的な支援も必要な相談になると思いますので、子ども家庭支援センターにまず相談が行ったとしても、その先のいろいろな専門的な相談先というのを今からしっかり研究して、つなげるようにしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"}]},{"id":"topic-08","title":"審査順を入れ替えまして、(4)その他","agenda":"審査順を入れ替えまして、(4)その他","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"これまでプレテストを何回、いつからやってきたのかということと、このプレテストが、今回のＥＳＡＴ－Ｊ、スピーキングテストとどう関係しているのか。英語スピーキングテストに有効だからこれを行っているのかといったところも教えていただきたいのですが、なぜこのプレテストを実施するようになったのか、その部分もお知らせください。","respondent":"中谷指導課長","answer":"令和元年度からです。２点目の質問ですが、プレテストも含めて、英語のスピーキングテストは東京都教育委員会の主催のものです。今回から入試活用するということに備えまして、その準備として、東京都教育委員会が考えましたプレテストを実施したという経緯になってあります。","id":"exchange-064"},{"speaker":"田中委員","kind":"質問・要望","question":"ということは、東京都の予算でこのプレテストが実施されるということですか。お金のつけ方も伺いたいのと、英語のスピーキングテストは１１月末に実施されるということですが、会場もまだきちんと明確に保護者にも知らされていません。やはり保護者からも多くの中止してほしい、もうやらないでほしいといった声を聞いております。教育委員会にもぜひそうしていただきたいと思うのですが、いかがでしょうか。","respondent":"中谷指導課長","answer":"２つ目ですが、品川区教育委員会としましては、東京都教育委員会の今回のスピーキングテストの導入の目的ということも含めて、保護者の皆様に丁寧にお伝えしまして、１１月末に実施を考えております。","id":"exchange-065"},{"speaker":"田中委員","kind":"確認","question":"長くならないようにします。今、丁寧に説明とありましたが、保護者からは、進路説明会のときにも説明がなかったと。実際知られていないのです。質問したいのが、プレテストのときにでも、タブレットを使って子どもが自分で顔写真を撮って、個人情報を入力して送るものになっているのか。それとも今回スピーキングテストのときだけそれが行われるのかということを確認させてください。","respondent":"中谷指導課長","answer":"写真の活用ということですが、今回のテストの申込みの利用規約というものを東京都教育委員会は発行しております。そちらも含めて保護者の皆様に学校を通じてご案内させていただいた上で、写真の活用ということも含めて申込み手続をしているという状況です。","id":"exchange-066"},{"speaker":"田中委員","kind":"質問・要望","question":"プレテストということは、今プレテストを行っている８年生、９年生は、この顔写真をつけて個人情報を入力するという動作をしているのかというところを確認したいというのと、やはり説明もないまま進んでいく状況がある。なので、ちょっとこのやり方はやめていただきたいというのと、何学年の方たちが個人情報、顔写真を載せて送ってしまっているのか、状況を確認させてください。","respondent":"中谷指導課長","answer":"ただ、利用規約に関しての使用に問題はないと東京都教育委員会は判断しています。そういった個人情報の守り方ということも含めて、しっかりとまた今年度の利用規約をきちんとつくった上での本番実施という形になっております。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問","question":"やはりスピーキングテストですが、非常に問題が多くて拙速過ぎていて、これで１１月末に予定どおりというわけにはいかないと思います。そもそもこの全員強制というところですが、都の教育委員会が中学生にそうしたテストを強制できる権限はないですし、これを入試に活用するということは事実上の強制ですから、教育基本法でも禁じられている不当な支配にも当たるわけです。その２点、お伺いします。","respondent":"中谷指導課長","answer":"こちらについては、希望される方のみということでご案内しています。申込み状況としましては約９５％の方々が今、申込みされておりますが、若干個別の理由により受験されないという方もおります。ということで、希望制であるということをお伝えさせていただきたいと思います。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問","question":"これは実は、様々な事情というのが様々な事情で、基本的には強制なのです。それで、受けていない方。これが入試と言えるのですかねというか、もうあまりにも都の制度が不整備で、こういうのに参加するということに疑問を感じないのかなというか。品川区としては、そこの点の問題点についてどう考えるか。問題だと思わないのかということ。お伺いします。","respondent":"中谷指導課長","answer":"品川区としまして今回のこのプレテストですが、やはり新しく初めてやっていく取組の中で、プレという、準備という段階の中で、東京都教育委員会が実施の目的も含めてご案内しているものですので、そちらに応えていくという形で、しっかり３年間を見据えて。","id":"exchange-069"}]},{"id":"topic-09","title":"令和３年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"令和３年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"こちらは、どんな理由なのかというのが１つと、この間、収支という点ではマイナスがかなり進んでいると思いますが、こちらの原因は何なのかということと、こちらはやはり法人の持ち出しになると思いますが、それが人件費削減等、従業員ひいては利用区民へのしわ寄せにならないのかと心配なのですが、そこら辺については大丈夫なのかという点をお伺いします。","respondent":"飛田子育て応援課長","answer":"収支面のところです。事業費については、各事業を実施するために必要な経費ということで、こちらについては、事業で使用する車両の修理や装備品を購入したことや、学童保育児の玩具等の購入に多くかかったことが原因となっております。","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。赤字になると当然持ち出しになってしまうと思うので、法人のほうでリストラなどはないのかなと、心配だなという思いがあるので、そこら辺は大丈夫なのでしょうかという質問にお答えいただきたいと思います。感謝を述べまして、その上で２つ質問です。再委託先を管理しているというところですが、こちらはどういった業務の再委託をどこにされているのかというのをお伺いします。","respondent":"立木保育課長、飛田子育て応援課長","answer":"再委託に関しましては、ぷりすくーる自体の管理をするための点検委託や、清掃委託といったところが再委託という形になっているということです。令和３年度、こちらに記入させていただきました母子生活支援施設処遇改善臨時特例事業補助金、１５万２,６００円と記載させていただきましたが、引き続き令和４年度も、こちらのほう。","id":"exchange-071"},{"speaker":"田中委員","kind":"確認","question":"それでもしも人の手当てにしわ寄せが行き、マイナスになってしまったら困るなと思って、そこの部分を確認したいと思います。そこの部分を確認したいのと、こういった事故報告書などの点検は、どうしたら私たちができるのかというところを伺いたいというのが２点目です。一般的に知られていないのではないかなと思いますが、どういった周知がされているのかという部分をまず伺いたいと思います。","respondent":"飛田子育て応援課長","answer":"ヒヤリハットと事故防止のリスク等ですが、これは事故があったわけではなく、法人全体としまして高齢者施設や障害者施設等もありますので、そういうところでいろいろな事例を検討しながら、また自分のところはどういうところを気をつけなければいけないかということで。","id":"exchange-072"},{"speaker":"田中委員","kind":"確認","question":"何か事故が発生したとき、区はどうやって事故報告を受けるのか。改善が必要とされた原因の分析および対応方針の中に、職員への処遇改善に取り組むとともに経費の削減にも取り組んでいるとありますが、処遇改善はされているのですよねという確認と、経費の削減というのは、これは人件費の削減と読めてしまうのですが、この経費の削減というのは何を指しているのですかということを伺いたいです。","respondent":"飛田子育て応援課長、立木保育課長","answer":"おかげさまで、事故などの緊急のことは今までありませんが、万が一起こりましたら、すぐに家庭あんしんセンターから法人本部ならびに区の担当へ連絡が行くようになっております。公設民営保育園と同形式の様式につきましては、特にぷりすくーるには提出を求めておりませんが、私どもで把握しているものでは、約６割程度の人件費比率という確認が取れております。","id":"exchange-073"},{"speaker":"田中委員","kind":"質問・要望","question":"ぷりすくーるのところで、保育士の人件費比率が６割程度、確保できているということだったと思いますが、今、公設民営保育園については区のホームページで公開されているので、そういった形で利用者が確認できるように公表していただけたらと思います。何かあったら聞かせてください。担当というのはどこですかという確認だけさせてください。","respondent":"飛田子育て応援課長","answer":"ひとり親相談係が担当となっております。","id":"exchange-074"}]},{"id":"topic-10","title":"第２期品川区子ども・若者計画素案","agenda":"第２期品川区子ども・若者計画素案","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"どなたでもいいかもしれません。これからの未来をつくっていく子ども・若者の可能性をどう切り開いていくかということですから、今回のパブコメに当たっても、そういう説明があるといい。説明会が一番いいと思いますが、オンライン配信でもいいのですが、これはやるべきだと思いますが、いかがでしょうかというのが１つです。この計画をつくる目的を一言で言うと何なのかというのをちょっと教えてください。","respondent":"廣田子ども育成課長","answer":"パブコメ実施に当たっての説明会というお話ですが、パブコメのための説明会というよりは、青少年の関係の委員などにはこの計画についてはお話を少しずつして、理解を得ようと思っているところです。機会を見つけてお話はさせていただこうと考えています。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"なるほどと。ですから、工夫していただきたいなと、改めてこれは要望です。専門委員会は１８名で、検討部会の方を合わせると、延べで言うと２８名ぐらいいると思いますが、こちらは、重複しているのがどういう方々なのかというのを、ある程度、代表的なところを教えていただきたいのと、あと、冊子に書いていないのです。それをどういうふうに捉えていらっしゃるのか、伺いたいと思います。","respondent":"廣田子ども育成課長","answer":"生きづらさを感じるところの検討部会につきましては、フリースペースや教育総合支援センター、各種ひきこもり等の支援を行っている部署の方に入ってもらいながら、オブザーバーとして先ほど申し上げた萩原建次郎先生に入っていただいたり、引き籠もっていて。","id":"exchange-076"},{"speaker":"安藤委員","kind":"質問・要望","question":"分かりました。最後に具体的にお伺いしたいこと、要望があるのですが、Ａ３の資料の重点施策がありますが、特に１番目と２番目のところで、子ども・若者の活動拠点の整備を具体的に検討していくということですが、どういうことを考えていらっしゃるのか。これは要望したいと思いますし、そういった問題についてどう考えるかという点。そこら辺についての問題意識もお伺いできればと思います。","respondent":"廣田子ども育成課長","answer":"フリースペースではやり切れない部分をつなげるところをつくる。つくるか探すというところで、ネットワーク化と重層的支援事業の検討も進んでおりますので、ネットワーク化をしながら、１つの場所で全部は解決できませんので、つながっていくというところを考えています。","id":"exchange-077"},{"speaker":"田中委員","kind":"質問・要望","question":"今回の基本理念の変更については先ほどご説明もあって、大綱が変わっただけでなく、区としてもゴールを自立にするのは危険という判断で、安心できる場所が必要といった考えから変更に至ったということは、本当にそのとおりだなと思いました。そこの部分に本当に取り組んでいただきたい。今後、報告があるということで、動きがあるのかなと思ったのですが、そこの部分を確認させてください。いかがでしょうか。","respondent":"廣田子ども育成課長","answer":"パブコメの説明については、説明会という形ではなくて、主任児童委員や青少年委員になど様々な場面を見つけてお話をしていこうかと思います。","id":"exchange-078"},{"speaker":"田中委員","kind":"質問・要望","question":"若者に特化した部分で、小学校、高学年、中学生とそれ以上の子どもと若者の居場所というのが本当に今ない状態です。唯一あるのがフリースペースです。高学年の子どもと若者の居場所をつくるというのはなかなか難しい問題もあるかもしれませんが、今、居場所がない子たちがそれで間違った方向に行くことがないように、受皿となるような居場所づくりをぜひ進めていただきたいと強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"くにば委員","kind":"質問・要望","question":"パブリックコメントについてです。先ほど、前回は８名から３３件のご意見をいただいたということですが、今回、パブコメに対して具体的にどのような方々からご意見をいただきたいのかについて伺いたいと思います。３０代以下の方は１.７％しかパブコメに参加していなかったという事実がありました。それであえて今回コメントをいただきたいと考えているターゲットを、まず伺います。","respondent":"廣田子ども育成課長","answer":"前回、パブコメが８名３３件でしたが、前回は期間が非常に短かったので、今回はマックスに近い１か月ほど取るようにしております。理想としては、当事者の声を聞きたいというところで、今回検討部会でも今２０代のひきこもりだった方や大学生に入っていただきました。","id":"exchange-080"},{"speaker":"くにば委員","kind":"意見","question":"パブコメが全てではないし、なかなか若い方々からパブコメをいただくのは難しいという部分についてです。今回このＡ４の用紙に、周知方法は広報紙への概要掲載、区ホームページ等と書いてあります。若い人たちが、パブリックコメントというとどういった内容なのか分からないかもしれないので、みんなのコメントを募集してますというポスターを作る。そこについて何かお考えがあれば。","respondent":"廣田子ども育成課長","answer":"次のターゲットを大学生とかそういう世代についてどう広げるかについては、これからまた検討に当たって考えていこうかと思います。委員のご意見も参考にさせていただこうと考えています。","id":"exchange-081"},{"speaker":"くにば委員","kind":"質問","question":"声をいただくという部分に関してですが、具体的に個別に面談をして、それぞれの方々にご質問なさったのか。それとも目安箱のような形で匿名で、自分が発言したことが分からないような形で、プライバシーが守られるような、気軽に投稿できるような形で声を聞いたのか。その声を聞いたという内容について、やり方について教えてください。","respondent":"廣田子ども育成課長","answer":"フリースペースにつきましては自由に来られる時間帯を午前中に設けていますが、１８歳以上が来る若者カフェといって、希望している人だけ来る座談会のような会も設けております。","id":"exchange-082"},{"speaker":"くにば委員","kind":"質問・要望","question":"そういった部分がすごくあると思いますので、中高生のアンケートだけではなく、実際に当事者の方々からも匿名で意見をもらえるような形ももう少し深掘りしてというか、何かしらその方法を考えていただきたいと思うのが１点目です。もう１点は、ひきこもり当事者についてです。こちらに関して、ポスト青年期。そこの線引きについて、明確に２９歳なら２９歳で区切るのかどうか、教えてください。","respondent":"廣田子ども育成課長","answer":"有料だったり、区としてはそんなに持っていませんが、都・国の４０歳を超えたら受けられないというサービスでなければ、対応可能であれば受けています。一旦受けて、その年齢に合う支援先につなぐということはしています。","id":"exchange-083"},{"speaker":"くにば委員","kind":"質問","question":"フリースペースやエールしながわ等の活用に関しては、本当にご努力なさっていると感じております。リアルの現場、人の顔が見えるところに行くのは、やはりハードルが高い。なぜかというと、インターネット上にはひきこもりの人たちが多い場所というかネットの空間がやはりあります。そういうところを品川区として何かしら模索できないかと思うのですが、そこについて何かお考え等ありますでしょうか。","respondent":"廣田子ども育成課長","answer":"そういう対応はできるのですが、エールにしても、今は本当に一人ひとり丁寧に行っている状況なので、ＳＮＳのほうが気軽ではあると思いますが、スタッフの心のメンテナンスということも考えなければならないので、ちょっと今は区としては難しいかなと考えています。","id":"exchange-084"},{"speaker":"くにば委員","kind":"質問・要望","question":"最後に意見というか、今おっしゃったとおり東京都で、専門性がやはり必要、生死の問題なので試行錯誤しながらやっているという部分。少しずつその情報やノウハウを蓄積していきながら、東京都だけではなく、少しずつ品川区でも進められるような体制に後々なっていただきたいなと意見させていただいて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"松澤副委員長","kind":"質問・要望","question":"要は何が言いたいかというと、子どもの貧困というのは、裏に見えるのが親の貧困ということもあるわけではないですか。見学に行きましたけれど、子どもがゲームをやって遊んでいて、居場所という部分ではすごくいい活動だなという中で、今、不登校児童・生徒への教育の中で、ＩＣＴを使った学習をしましょうという話がある、では、そこにどう結びつけるのかなとか。それについて何か一言だけ。","respondent":"廣田子ども育成課長","answer":"大学生だけではないのですが、若い世代に入ってもらえるような仕組みが必要ではないかというご意見も出ました。それは引き続き検討していくということで、計画の策定の検討部会の中で出てきたので、いかしたいと考えています。","id":"exchange-086"}]},{"id":"topic-11","title":"区立児童相談所開設に向けた進捗状況等","agenda":"区立児童相談所開設に向けた進捗状況等","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料に基づいて。場所をお伺いします。それと、竣工から開設までは結構長い期間があると思いますが、開設準備を進めるに当たり、建物をどのように使用していくイメージなのかお伺いしたいと思います。それと夜間休日の対応の件は、委託なのか直営なのか検討中ということですが、先行自治体が既にあると思いますが、そちらの状況というのはつかんでいらっしゃるのか、伺いたいと思います。","respondent":"長谷川児童相談所移管担当課長","answer":"その翌月にその初度の物品搬入というスケジュールになっておりますので、その後の使用スケジュールという意味合いだとは思いますが、その後、開設の６年１０月までの間に関しましては、主に派遣職員や経験者採用職員等の知見・経験といったものをいかしながら。","id":"exchange-087"},{"speaker":"安藤委員","kind":"質問","question":"見守りホットラインの接続先について一本化するということですが、現在はどこにつながっていて、どういうふうな対応をされているのかというのを伺います。4)については、現在既に様々な自治体へ派遣されているのですが、その成果と、派遣されている職員の方々の受け止めみたいなものをどういうふうにつかんでいらっしゃるのか、どんな状況なのか、伺いたいと思います。","respondent":"長谷川児童相談所移管担当課長","answer":"一方で、１人で孤独に戦っている派遣者ですので、そういった方の不満や愚痴といったところを聞く貴重な場にもなっていると認識しております。","id":"exchange-088"},{"speaker":"安藤委員","kind":"質問・要望","question":"すごく人が重要だといいますか、場合によっては大変深刻なケースも扱い、専門性がすごく求められていると思いますので、職員の体制については、加配も含めてかなりしっかり手厚くしていただきたい。ぜひそちらも検討していただきたいのですが、最後にご意見があれば伺いたいと思います。","respondent":"長谷川児童相談所移管担当課長","answer":"その業務の継続性や執行体制なども勘案しまして、これまでも柔軟な配慮・対応を行っていたところでありますけれども、児童相談など専門性が求められる業務に限らず、異動については杓子定規にならずに配慮していく必要があると、我々としても認識しております。","id":"exchange-089"},{"speaker":"田中委員","kind":"質問","question":"２点伺います。児童相談所開設に向けた計画書の１４ページで、子どもの権利擁護について触れています。子どもの権利擁護の機関の設置について、区としてどのように考えているのかを伺いたいのが１点です。それで辞めてしまうケースも多くあると聞くので、メンタルケアの部分を伺いたいのですが、どのように考えているかということを教えてください。","respondent":"長谷川児童相談所移管担当課長","answer":"そういったときに、相談窓口の活用や設置区の状況等を踏まえて、職員のメンタルケアについては引き続き検討していきたいと考えております。","id":"exchange-090"},{"speaker":"渡部委員","kind":"確認","question":"確認だけです。建物ができて、今年の３月にはもう箱が出来上がっているから、児相に関係する人というのはそこに移動といいましょうか、その建物で仕事を始めるということでよろしいのですよねというのが１点です。継続している案件というのは一旦全部引き取って、それで徐々に新たな案件もそこでどんどん取っていくというイメージなのかというところの確認です。その３点だけ教えてください。","respondent":"長谷川児童相談所移管担当課長","answer":"来年はもう少しプラスで１年派遣という方法も検討していきたいと考えていますので、そういった職員はその建物の中には入らない。","id":"exchange-091"}]},{"id":"topic-12","title":"品川区保育所等の利用調整基準の一部改正","agenda":"品川区保育所等の利用調整基準の一部改正","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の２の（１）のところですが、申請の直近３か月の就労状況で出していたような記憶があるのですが、それを４月入園の場合は、直前の３月、２月、１月の実績でよいという変更なのでしょうか。その場合、結構ばたばたするのではないかなと思いますが、間違っていたら訂正して説明いただければと思います。","respondent":"立木保育課長","answer":"委員のご指摘のとおり、４月入園の場合は３月、２月、１月の勤務実績をもとにという形に変更になるです。","id":"exchange-092"},{"speaker":"安藤委員","kind":"質問","question":"申請は１１月にするのですが、直近の就労状況については後で書類を出すという流れ、イメージということでしょうか。","respondent":"立木保育課長","answer":"引き続き就労しているものとみなしまして、変更があった場合には書類を出していただくということになります。申請の段階で内定とか勤務が始まっている場合には、今後こういう形で就労しますという形で出していただき、事務手続を行うことになっております。","id":"exchange-093"},{"speaker":"田中委員","kind":"質問・要望","question":"改正前は診断書等が必要でしたが、改正後は、医師が証明した病状内容で指数の認定ということで、とても楽になったというか、負担が軽減されたということでよろしいですねという確認と、この改正については、品川区独自で改正ができるのですか。品川区が基準を持っていて、こうやって改正ができるのかという部分を教えていただきたいと思います。","respondent":"立木保育課長","answer":"項番２の（２）に関しましては、これまで自由書式で出していただいておりましたが、書かれている内容がそれぞればらばらでございまして、保育の必要性を認定する際にかなり聞き取り調査等をしておりました。","id":"exchange-094"},{"speaker":"安藤委員","kind":"質問","question":"目的のところの保護者・企業の負担軽減というのがいろいろ説明があったのですが、保護者間の公平性確保という点では、これはどういうところが改正なのでしょうかというという説明をお聞かせください。","respondent":"立木保育課長","answer":"入園月を基準にすることによりまして、１１月ぐらいから働き始めて既に５か月働いている方が、以前より継続して働いている方と同じ条件で入園審査が受けられるということで、公平性を担保したという形になってあります。","id":"exchange-095"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/449994?Template=document&Id=5082#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":97180,"voices":290}},{"id":"r04-20221101-5","meetingId":"r04-cm11","date":"2022年11月1日","dateIso":"2022-11-01","committee":"総務委員会","time":"午前１０時００分～午後 ４時３５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"吉田委員","kind":"確認","question":"いつもこのような補正予算審査のときに、何度かこの総務委員会で確認させていただいているのですけれども、改めて伺います。もし間違っていたら、修正していただけると大変ありがたいです。","respondent":"黒田財政課長","answer":"補正予算の考え方のご質問になりますが、基本的には年度当初の予算で想定できなかった事態が発生した際に補正予算を編成いたしますけれども、いわゆる国や都の補助金につきましては、その事態が発生したときに、財源として活用できるものについては、当然その活用をいたしますし。","id":"exchange-001"},{"speaker":"吉田委員","kind":"確認","question":"度々確認させていただいてすみません。そのような考え方でいうと、歳出のほうの産業経済費の創業支援施設等経費というものは、旧ゆうぽうと跡地の活用というところで、もう既に大分前から計画があって、私が別の委員会にいるときも説明を伺っていたと思うのですけれども、この中での施設内装工事設計委託というものは、今この時期に補正予算でということの意味が分からないので、ちょっと教えてください。","respondent":"黒田財政課長","answer":"いわゆる躯体連動工事のところの予算編成につきましては、令和４年度編成時につきましては、金額が不明な点もあって、令和５年度の当初予算で計上することを想定して、令和４年度予算を当初編成したところですが、本来の日本郵政のほうで建設している事業者のほうから。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"ということは、区の計画で見込んだものより、先方のという言い方でいいでしょうか、相手方の事情、それもいろいろなものの高騰ということは、そちらとしても想定外だったと思うのですけれども、そういうことで、なるべく費用を抑えるとか、そのような意味で、このたびの補正になったということで理解してよろしいでしょうか。","respondent":"黒田財政課長","answer":"ご指摘のとおりです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"建物の持ち主である日本郵政がやるのではなくて、品川区がそういった設計から内装工事まで、品川区の予算でやるというようなことになるのか、その仕組みをひとつ教えていただきたいと思います。","respondent":"黒田財政課長","answer":"今回の五反田産業文化施設につきましては、郵政が建物の一部、ホールを借り受けて、区が公の施設として条例設置で運営するという施設になりますので、いわゆる借り方の中で、内装まで全て工事が終わったものを借りるという形式もあろうと思いますが。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうしますと、その内装工事全体としては幾らぐらいかかるという試算などが出ているのか、ちょっとその点を伺いたいということと、それから賃料が１年間に１億４,５２０万円ということで日本郵政から借りるということで、区民委員会のほうでは答弁があったと聞いているということなのですけれども、これは指定管理者になっていきますよね。","respondent":"黒田財政課長","answer":"指定管理者については、通常でいいますと、公の施設を１年間運営するに当たって、必要な経費について様々なご提案をいただいて、条例に定めた使用料を徴収して、収支が、所管課の説明ですと７５％ぐらいの稼働率だと３,０００万円から４,０００万円ぐらいの運営費。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、区の負担としては、賃料が年間１億４,５２０万円かかった上に、指定管理者に対して赤字になるかもしれないというようなことを見込んだ委託料というような形で、賃料と、それに加えて委託料がかかるということで考えていいのでしょうか。","respondent":"黒田財政課長","answer":"先ほど申し上げましたが、あくまでも賃料は整備費相当というように考えた場合、運営費というものは別という考え方というふうに捉えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうはいっても、毎年１億５,０００万円近くの賃料がかかった上に、これだけすごく高い、イベントホールを全日借りると約６０万円、ギャラリーでも全日借りると９万９,０００円、エントランスロビーでも全日借りると５万５,０００円ということで、区のほかの施設に比べたら、ここは１０倍くらい高い施設であるにもかかわらず、それなのにそのように赤字になって。","respondent":"黒田財政課長","answer":"整備は日本郵政がするものを借りるという意味で、運営は、建てても借りても委託として行うものですので、そこは今回、整備費はかかっていないということであれば、基本的には運営のやり方としては、通常どおり公の施設を運営していくという考え方に立っているところです。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"日本郵政がもともと旧ゆうぽうと跡になぜこのようなホールをつくらなかったのかといったら、日本郵政としては採算が取れないというようなところでつくらないと、そのようなことで区から答弁もあったということなのですけれども、それをあまりに高い、一般の区民が使うというよりは、株主総会ですとか、セミナーとか、商品発表会とか、パーティですとか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"衛生費のところで、国庫支出金返還金とあります。実際では、予防接種を受けられる方の人数を想定してやったけれども、実際はそれだけ少なかったということで、最初の予定と違ったので、その分を国に対して、ただ単に返金したということと考えてよろしいでしょうか。","respondent":"黒田財政課長","answer":"時間外、休日の接種のほうも、予約が取りやすくなるに当たりまして、いわゆる個別医療機関のほうでも診療時間内に接種するような形が増えてきまして、そこの部分に計上した予算も不用となりまして、そういった複合的な要因で、１４億円余の返還となったというものです。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問","question":"逆に、ここでまた啓発事業というものに取り組んでいかないと、ますます接種する人が減ってしまうのか、ちょっと心配するのですけれども、その辺はどのようにお考えでしょうか。","respondent":"黒田財政課長","answer":"所管課から聞いておりますのは、これまでの様々な株の変異の中で、国のほうでもいわゆる重症化率というところも変異によって変わってきているという中で、区民の皆さんもいろいろ考えるところがあって、接種についていろいろな考えをお持ちなのだろうなと考えていますが。","id":"exchange-010"},{"speaker":"つる副委員長","kind":"質問・要望","question":"では順番に、総務費の選挙費のことなのですけれども、報酬で６００万円で、一応そのそれぞれの大括りの人件費に当たる部分として、投票事務費の中で、これは期日前と当日ということで分かれていると思うのですけれども、期日前が３３０万円で、当日と思われるものが２４５万円、それから開票事務費、開票作業所での事務経費だと思いますが、それが２５万円と分かれているのですけれども。","respondent":"鈴木選挙管理委員会事務局長","answer":"期日前につきましては、１３か所の地域センターで、投票管理者お一人と投票立会人お二人がいらっしゃいます。それの１３か所分の人数。それから、投票所に関しましては、４３か所に投票管理者１人ずつと、立会人が３人ずつということになります。","id":"exchange-011"},{"speaker":"つる副委員長","kind":"質問","question":"これはいろいろ一般論で伺っている中では、本選から逆算して何か月などというものがあったかと思うのですが、今回は再選挙という、そこを基本の日にちにしての、それに付随しての補欠選挙という扱いなのかなと理解している部分と、全く純然たる、ここが区長選挙の本選とはいつなのでしょう、であれば、ここで区議会議員の補欠選挙というものはできなかったのか、できたのかという。","respondent":"鈴木選挙管理委員会事務局長","answer":"区議会議員選挙の補欠選挙ですが、公職選挙法の規定によりまして、通常は定数の６分の１を欠けた場合に、単独でも補欠選挙を実施します。","id":"exchange-012"},{"speaker":"つる副委員長","kind":"確認","question":"そうすると、当然今後の品川区の中でも、考え方が、いろいろ条例だとかの改正、そのようなものがある等々しれませんけれども、今回の１２月４日執行の区長選挙というものが、ここで当選人が出ると、ここが４年後、何もなければ４年後の区長選挙が、また１２月４日に実施されるとなったときに、その間区議会側で欠員等が発生した場合には、ここでは補欠選挙は行わず、本選に寄せられるというか、本選で行う。","respondent":"鈴木選挙管理委員会事務局長","answer":"現在の区議会議員の皆様の任期が４月末日ですので、その任期が今後何かの事情でずれない限りは、１２月に区長選挙を行うときには補欠選挙は行わないと、区議会議員の補欠選挙は同時には行わないということが、４年後以降の想定になります。","id":"exchange-013"},{"speaker":"つる副委員長","kind":"質問・要望","question":"それで、所得制限がなければ、マイナンバーの情報から行政がそれを確認、マイナンバー経由ではなくても、いろいろな事務連携というのですか、それでできる部分もあるかとは思うのですけれども、それが、所得制限を東京都が設けなければ、その作業というものは現場の区にしてみると、どれだけの手間なのかどうか分かりませんが、必要なくいけたのかなという確認は、委員会後にさせていただいたのです。","respondent":"黒田財政課長","answer":"都からの補助金の考え方ですが、事務に関しては一定程度条件がありまして、その範囲で東京都で１０分の１０として出すというように聞いておりますので、明確に所得制限を超えている部分の対象事務に対する事務費が補助対象云々ということではなくて、全体の事業費の中で。","id":"exchange-014"},{"speaker":"つる副委員長","kind":"質問・要望","question":"それと、ここは私も不勉強な部分で、逆に教えていただきたいのですが、事項別明細書を見ると、この高校生等医療費助成というものは、子どもすこやか医療費助成の中でという理解でいるのですけれども、事項別明細書を見ると子どもすこやか医療費助成事業で２,８２０万円という部分と、それから高校生等医療費助成事業で２,８２０万円ということで、見積り総額が２つになっているのです。","respondent":"黒田財政課長","answer":"この高校生等医療費助成制度につきましては、今副委員長からご指摘があったとおり、もともとの区の制度の立てつけとしては、いわゆる１つの条例の中で、乳幼児医療ですとか、義務教育医療費助成制度と同じ枠組みの中で制度として立てつけているというところはありますが。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"先ほどの五反田産業文化施設について、料金設定のことで伺いたいのですけれども、きゅりあんなどのイベントホールが、５６０席で、平日であれば全日借りても８万３,７００円で、日曜・祝日が１０万４００円という状況ですし、ホールなどでいえば、荏原文化センターなどももっと本当に、この１０分の１ぐらいで全日借りられる状況なのですが、これだけ全日借りて約６０万円という利用料というものは。","respondent":"黒田財政課長","answer":"そういった中で、近隣のホール等の料金等も勘案しながら、区では大崎でＳＨＩＰが運営するブライトコアホールなどもありますので、そういったところも鑑みて、今回の使用料を設定したというふうに所管課からは伺っております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"産業ものづくり部門として決めたというよりは、区の方針としてこれをつくろうというようなことで決めていると思うのですけれども、商業利用としてというようなことなのですが、対象や目的などというようなものは、にぎわいのあるまちづくりというようなことでしか書いていないのですけれども、どのように区としてそのような対象や目的をつくろうという方針になったのかということと。","respondent":"黒田財政課長","answer":"一定程度そういった運営費も見ながら設定しませんと、結局稼働率が１００％でも運営費が回収できないということでは施設が成り立ちませんので、そういった意味では、そういった運営費も鑑みて使用料を決定しているというふうに伺っています。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"賛成です。先ほど申し上げましたように、区民が使うというよりは、にぎわいの創出と言いながらほかの施設の１０倍近い料金設定で、本当に開発を誘導していくという、そのような施設としての位置づけになるのではないかなというような思いで、この施設に対しての補正予算は反対なのですが、そのほかのところは全て区民にとって有益な予算が組まれていると思いますので、総合的なところでは賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問","question":"賛成します。先ほど私たち品川・生活者ネットワークとしても、五反田産業文化施設のこの委託の補正について質問をいたしましたが、この補正、この建物自体は、私はたしか２０１９年の建設委員会の報告のときには建設委員会にいたのですけれども、様々なご意見が出たかと記憶しております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-02","title":"令和４年１０月２日執行 品川区長選挙 品川区議会議員補欠選挙 結果","agenda":"令和４年１０月２日執行 品川区長選挙 品川区議会議員補欠選挙 結果","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"選挙のご報告等があるたびに、今まで障害者の方で、なかなか投票しにくい方からのご意見を基に、私の意見を申し上げていたのですけれども、昨日の陳情審査のときに、投票所に入れる人について、子どもは昔は駄目だったけれども、今は親と一緒に入っていく、入れるようになっているということなのですが、そのほか付添いというものはどうなのでしょうか。確認させていただきたいのですけれども。","respondent":"鈴木選挙管理委員会事務局長","answer":"障害をお持ちだったり、けがをしていたりして、付添いなり、介助が必要な方につきましては、各投票所にいる職員には、そのような支援が必要な方のための人員も配置しておりますので、基本的には職員のほうで、車椅子なり、お隣で介添えするというところの職務をしまして。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。その私が直接意見を伺った方は、娘さんに手を引いてもらって入ろうとしたら、娘さんはそこの投票をする立場の方ではなかったと思うのですが、かといって誰かが手を引いてくれるわけでもなくという感じで、大変ご立腹だったのです。そのような指示が徹底されていなかったのか、その辺について見解を伺いたいと思います。","respondent":"鈴木選挙管理委員会事務局長","answer":"私ももう２０年以上投票所をやっておりましたが、必ずそのようなときには対応するようにしてきましたけれども、そのように一部対応が不足の部分があったのかもしれませんので、１２月の選挙では、改めてそのことについても注意喚起をしまして。","id":"exchange-021"},{"speaker":"吉田委員","kind":"意見","question":"今までもコミュニケーションボードでしたか、せっかく選挙管理委員会として用意されたものが掲示されていない。今回も何か所か聞いたのですけれども、もうしっかり出ていましたというところと、それからやはり見当たらないなというようなところがあったのです。現実的に。やはりそのような方たちが投票しやすいように、改めて徹底していただけると大変いいと思いますので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"要介護の方もこの対象になるのではないかと思うのですが、介護度が幾つまでの方がこの郵便等投票証明書をもらうことができるのか、そして郵便等投票証明書というものはいつまでにどのような形で申請すればいいのか、ちょっとその仕組みを教えてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"それから介護を要する方のほうも、やはり基本的には移動を、投票所に、もしくは期日前投票所に移動してできない方ですので、介護３から５で四肢の支障のある方だというように、たしか記憶しております。すみません、ちょっと今手元に詳細を記載した資料がないのですが。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、障害の方というものは、基本的に身体障害者、身体障害の方ということになるのでしょうか。もちろん精神障害の方などはなかなかならないのだろうなと思うのですけれども、身体障害の１級、２級や、それとももっと軽くても、ちょっと移動が困難ということで選挙管理委員会のほうで認めてもらえればできるということなのか。ちょっとその辺の細かいところを、申し訳ないのですけれども。","respondent":"鈴木選挙管理委員会事務局長","answer":"選挙管理委員会の裁量で対象にする、しないと決められるものではなくて、障害者手帳、それから要介護認定の等級と、それからその要件、歩くのに支障はあるかとか、その要件が決まっていて、それに該当するかどうかになりますので。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、その要件というものは要綱か何かで決まっているという、何か基準を決めている文章というものはあるのか、ちょっとその点も教えてください。","respondent":"鈴木選挙管理委員会事務局長","answer":"この要件につきましては、公職選挙法に基づくものですので、区の要綱などではなくて、公職選挙法と、それからそれに関する国の基準、通知などで定められているものです。","id":"exchange-025"}]},{"id":"topic-03","title":"令和４年職員の給与等に関する報告及び勧告の概要","agenda":"令和４年職員の給与等に関する報告及び勧告の概要","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"ちょっと我々が新聞報道を見ている限りでは、民間でもうほとんど８０％、９０％を占める中小企業の人たち、お店をやっている人たち、商店街を含めて、給与が上がっているというような実感がほとんどないということと、どうしても比較に対してこれだけ職員の皆さんが給料が低い、民間と比べて低いというようにはどうも思えないのです。","respondent":"崎村人事課長","answer":"実態と違うのかというところのお話なのですけれども、今回の調査につきましては、これまでもご説明しておりますとおり、企業規模５０人以上で事業所規模５０人以上の事業所を対象としているというところについては、これはやはり公務と同様の役職段階を有しているという部分で。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、このように区民に報告をするわけではないですか。それを私は、区に求めるということはきついのだろうけれども、やはりこれでは説得を、我々もできないし、なかなか説明がしにくいというのが１つなので、そこは人事課に言うよりは人事委員会のほうに意見として、明確な説明、区民でも分かりやすい説明をするように、私は要求していただきたいと思います。ご見解があったらお聞かせください。","respondent":"崎村人事課長","answer":"採用につきましては、これまでもお話をしてきましたとおり、特別区２３区全体で人事委員会というものを設置して、人事委員会による統一の採用選考というものを行っている中で、各区のほうで採用するという流れになっております。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"今、２３区のほうで決められるという話ですが、会社として見るならば、やはりその会社にいい人材が来れば、将来、この品川区というものは、私は安泰だと思うのです。いろいろ人材というものは、品川区を支えるという意味で大きな位置、事業もそうですが、事業をやるにはやはり人ですから、何とかいい人材をできるだけ１人でも採用するように、努力してほしいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問・要望","question":"以前も伺ったかもしれないのですけれども、これは勧告なので、勧告ということで、特にいろいろな人事・給与制度、勤務環境の整備等に関する意見となっているのです。読めば何か分かっているのだけれども、それに対しての、これの文章の扱いというものは、ただ、はい分かりました、聞いておきますというようなことでいいのでしょうか。すみません、改めて教えていただきたいと思います。","respondent":"崎村人事課長","answer":"意見の部分につきましては、これも人事委員会が行うもの、また区が行うものと分かれておりますけれども、今後このような取組をしなさいではなくて、したほうがよいのではないかというようなお話ですが、ただ、こちらで書かれていることにつきましては。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"要は、３０％の目標値を達成するように努力するようにという、そして女性の取得者より男性の取得者のほうが短いから、もう少し長く取るように職場風土を変えていきなさいよという意見だというように読んで、分かりましたという、それだけのことなのでしょうか。以前も同じように違和感を感じて、同じようなことを伺ったかと思うのですけれども、そのような性質のものと理解してよろしいのでしょうか。","respondent":"崎村人事課長","answer":"意見に書いてあるものが「必要」でしたり、「懸念」でしたり、何かそういった言葉で締めくくられているので、何となく委員のお話もあるように、言いっ放しで終わっているような印象は受けるかもしれないのですけれども、ただ。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"１点、４ページの３の、区民からの信頼の確保というところ。公益通報制度というものが、私の理解に違いがあるかもしれないので、改めてその制度について伺いたいということと、「従来の不祥事防止策に加えて」ですので、不祥事防止につながる制度ということを考えると、例えばこの辺は私としてもぜひ強化をしていただきたいと思うのですが、現段階で何かお考えがあったら伺いたいと思います。","respondent":"崎村人事課長","answer":"こちらの活用といったところにつきましては、公益通報制度は、確かになかなか制度として、これまでも通報件数がほぼ０件というような状況でもありますけれども、あることが正しいのか、ないことが喜ばしいのかという部分はかなり評価が難しいところではありますが。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"ぜひよろしくお願いします。ちょっと記憶が曖昧なのですけれども、それも保育士、退職した保育士からの通報で明らかになったという例を以前伺いました。今私が言っているのが、この公益通報制度の範囲に入るのかどうかも分からないのですけれども、その点について、もしご見解があればお伺いしたいと思います。","respondent":"崎村人事課長","answer":"公益通報の対象者としては、もちろん退職者も含まれますし、今委員のお話がありました事業等の委託事業者等々も含まれますので、そういった方が区の委託事業等を行う中で、違法または不当な行為というところの事案を認識して改善を求めるといったところでありましたら。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。辞めないと言えないというのは不適切な表現だったかもしれませんけれども、おっしゃるとおり、何かあったときに適切な指摘をした人に関してのきちんとした権利の保障など、そのようなことがされるようになっていただきたいし、調査をした結果、特に問題はありませんでしたということもあると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]},{"id":"topic-04","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"ちょっと１点だけ、私の解釈が悪いのかもしれないのですが、文面の初めに新型コロナウイルス感染症のことで、「一昨年より続く」と書いてありますね。これはもう、今回で３年目に入るのですけれども、この文章でいいですか。いや、解釈の話なのです。「続く」と書いてあるので、それでいいのかもしれない。「長年続く」より、いいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-05","title":"立会川緑道整備工事（２工区）請負契約","agenda":"立会川緑道整備工事（２工区）請負契約","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"建設委員会のほうの資料を見ていなくて、お聞きして申し訳ないのですけれども、この緑道の整備工事は１工区から４工区になっていて、そのうちの今回は２工区ということなのですが、その２工区のところというのは、たしかにぎわいゾーンという、そのような位置づけがされると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-06","title":"「よくわかる！品川区財務諸表」の作成","agenda":"「よくわかる！品川区財務諸表」の作成","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"質問というより意見です。データでは、ホームページで今まで財務４表のあたりが出ていたのですけれども、今度は求めなくても冊子で出てくるのでしょうかということが１つと、このように早く情報が出されるようになったということは大変歓迎したいということを意見として申し上げたいと思います。冊子は、できたら私は紙でいただきたいのですけれども、そのように理解していいか、それをお聞きします。","respondent":"中山会計管理者","answer":"こちらの「よくわかる！品川区財務諸表」につきましても、紙の状態で決算特別委員会の前には議員の皆様に配布して、区民の皆様への配布というのは決算の認定後というように、決算書のデータアップと一緒にと考えています。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"では区民の皆さんにも、求めればどこか、地域センターとか、そのようなところに冊子を置かれているのでしょうか。それを教えてください。","respondent":"中山会計管理者","answer":"昨年度から実際に置かせていただいたのですが、地域センターや図書館、あるいは中小企業センター、そういったところには紙のものも置かせていただくようにいたします。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９ページ、１０ページ辺りのところで伺いたいのですけれども、これは令和２年度の内訳と令和３年度の内訳ということで、どう変わったのかというようなことでグラフで一目瞭然というような形で配置していただいていると思うのですが、これはなぜこうなったかという理由は、例えばここでいえば、行政コスト計算書のところでいうと、扶助費・補助費等が５５％から４１％に減っているとか。","respondent":"中山会計管理者","answer":"最初のグラフの構成の変化についてですが、こちらのほうは８ページのところの「３年度のポイント」というところに、具体的な数字も載せながら記載しています。","id":"exchange-038"},{"speaker":"湯澤委員","kind":"意見","question":"それでちょっと意見になってしまうのですけれども、１点、もし可能であれば、このようなものは何か目次とか、そのようなものがあるといいかなと。何か今の説明だと、これはどこだ、どこだとページで追っていくような感じだったので、もしそのようなものがあると、さっと調べられてさらに分かりやすいかなという意見だけ述べします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"１０ページのところの行政費用の内訳という中に、減価償却費と引当金繰入額が一緒に表されているのですけれども、この減価償却費と引当金繰入額はどうして一緒なのですか。ごめんなさい、よく分からないので教えてください。","respondent":"中山会計管理者","answer":"なぜ減価償却費と引当金繰入額かというと、この２つはあまり現金の移動のない、今後の予定の、支出の可能性というところで、１つのカテゴリーとさせていただいています。","id":"exchange-040"},{"speaker":"つる副委員長","kind":"質問・要望","question":"今回３回目ですね。よく分かるというところで、そもそも新公会計制度の東京都方式ということで、ずっと、大分昔から要望、質問等をさせていただいて、それが取り入れられて、そして、このような形になって３年目ということですよね。それはそれでいいなと思うのですけれども、この過去の質疑を今見る中では、「よくわかる！その数字の位置、これとこれが一致していてなどと。","respondent":"中山会計管理者","answer":"まだまだ改善点はあるかと思いますので、皆さんのご意見をいただきながら、少しボリュームも増やしていこうかと考えているところです。","id":"exchange-041"},{"speaker":"つる副委員長","kind":"提案","question":"私も過去ずっと、十数年議員をさせていただいて、何年かにわたってこのことを質問しながら、自分も勉強しながら提案して、そして提案して勉強してという形で、それこそ公会計制度とか、会計制度そのものの本を何冊も買って、その読み方も、よく分かる読み方の本まで買わないと分からないぐらい、本当に複雑だなという思いをしながら見てきたわけです。この手のものというのは結構同じような書きぶりなのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/982063?Template=document&Id=2248#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":42536,"voices":130}}]);
